insert into public.atlas_dish_texts (dish_id,lang,name,place,description,steps) values
('bouillabaisse','pt','Bouillabaisse','Marselha, França','Nascida do caldeirão dos pescadores de Marselha, a bouillabaisse transforma o peixe de rocha num caldo de açafrão de rara profundidade. Serve-se primeiro a sopa com rouille e croûtons, depois o peixe.',ARRAY['Refogue a cebola e o funcho em azeite sem deixar alourar.','Junte tomate, alho, casca de laranja e açafrão, cubra com água e deixe ferver brandamente 30 minutos.','Passe o caldo pelo passe-vite para extrair todo o sabor e acerte os temperos.','Escalfe o peixe do mais firme ao mais delicado, 8 a 12 minutos no total.','Sirva o caldo bem quente sobre croûtons esfregados com alho, com o peixe e as batatas à parte.']::text[]),
('cassoulet','pt','Cassoulet','Castelnaudary, França','Este guisado de feijão branco e carnes confitadas coze horas na caçarola de barro que lhe deu o nome. A crosta dourada, quebrada e afundada sete vezes, é a sua lenda.',ARRAY['Demolhe o feijão na véspera e coza-o 1 hora com cenoura, cebola e tomilho.','Aloure as salsichas e a entremeada em gordura de pato e reserve.','Alterne feijão e carnes na caçarola e cubra com o caldo da cozedura.','Polvilhe com pão ralado e leve ao forno 2 horas a 150 °C.','Quebre a crosta com uma colher várias vezes durante a cozedura e sirva no próprio recipiente.']::text[]),
('pizza-napoletana','pt','Pizza napolitana','Nápoles, Itália','Três ingredientes e nenhum truque: tomate San Marzano, mozarela de búfala e manjericão. A massa, de longa fermentação, incha em 90 segundos a 450 °C e forma aquele bordo malhado.',ARRAY['Misture farinha, água, fermento e sal e amasse 15 minutos até ficar lisa.','Deixe levedar 2 horas à temperatura ambiente e 24 horas no frio.','Divida em bolas de 250 g e deixe repousar 4 horas antes de abrir à mão.','Esmague os tomates com um garfo, tempere e espalhe em espiral sobre a massa.','Junte a mozarela escorrida e um fio de azeite, leve ao forno no máximo; manjericão à saída.']::text[]),
('risotto-milanese','pt','Risoto à milanesa','Milão, Itália','Um risoto de amarelo intenso tingido com açafrão, cuja cor a lenda atribui a um vidraceiro do Duomo. Tudo depende do gesto final: fora do lume, bate-se manteiga fria e parmesão.',ARRAY['Refogue a chalota picada em um pouco de manteiga com o tutano.','Envolva o arroz 2 minutos, refresque com vinho branco e deixe evaporar.','Junte o caldo quente concha a concha, mexendo, 16 a 18 minutos.','Incorpore o açafrão infundido em um pouco de caldo a meio da cozedura.','Fora do lume, envolva manteiga fria e parmesão, repouse 1 minuto e sirva cremoso.']::text[]),
('paella-valenciana','pt','Paella valenciana','Valência, Espanha','A verdadeira paella valenciana não leva marisco: frango, coelho, feijão-verde largo e garrofó, cozinhados em lenha de videira. O tesouro está no fundo, o socarrat estaladiço.',ARRAY['Aloure bem o frango e o coelho no azeite, junto ao bordo da paelleira.','Junte o feijão-verde, depois o tomate ralado e o pimentão fora do lume para não queimar.','Cubra com água, junte o açafrão e deixe cozer esse caldo 20 minutos.','Deite o arroz em cruz, espalhe-o uma única vez e nunca mais mexa.','Coza 18 minutos baixando o lume, suba a chama 1 minuto para o socarrat e repouse 5 minutos.']::text[]),
('gazpacho','pt','Gaspacho andaluz','Sevilha, Espanha','Uma sopa fria nascida da necessidade: pão duro, azeite e legumes da horta, triturados para enfrentar os 40 °C do verão andaluz. Bem emulsionado, fica aveludado e quase rosado.',ARRAY['Demolhe o pão 10 minutos em um pouco de água.','Triture tomates, pepino descascado, pimento e alho até obter um líquido homogéneo.','Junte o pão espremido e o vinagre e triture de novo.','Deite o azeite em fio com a máquina a trabalhar até a cor empalidecer.','Passe pelo chinês, tempere e refrigere pelo menos 3 horas; sirva bem frio.']::text[]),
('bacalhau-a-bras','pt','Bacalhau à Brás','Lisboa, Portugal','Um prato de tasca do Bairro Alto onde o bacalhau desfiado encontra batata palha e ovos mal ligados. O segredo é desligar o lume antes de o ovo coalhar por completo.',ARRAY['Demolhe o bacalhau 24 horas mudando a água e desfie-o à mão.','Corte as batatas em palha fina e frite até ficarem douradas.','Aloure cebola e alho no azeite, junte o bacalhau e deixe apurar 5 minutos.','Envolva a batata palha, deite os ovos batidos e mexa 30 segundos fora do lume.','Sirva de imediato com salsa picada e azeitonas pretas.']::text[]),
('francesinha','pt','Francesinha','Porto, Portugal','A sanduíche portuense levada ao exagero: fiambre, salsicha e bife entre duas fatias de pão, afogados em queijo derretido e molho picante de cerveja. Nasceu nos anos 50 para aquecer as noites do Porto.',ARRAY['Faça o molho: prepare um roux, junte cerveja, tomate e piri-piri e deixe reduzir 15 minutos.','Grelhe os bifes e as salsichas e torre o pão.','Empilhe pão, fiambre, salsicha aberta, bife e feche com a outra fatia.','Cubra totalmente com fatias de queijo e leve ao grelhador até derreter.','Regue com o molho a ferver, coroe com um ovo estrelado e sirva com batata frita.']::text[]),
('wiener-schnitzel','pt','Schnitzel vienense','Viena, Áustria','Um escalope de vitela batido até ficar fino como uma folha, panado e frito em manteiga clarificada até o pão ralado soltar-se. O limão é obrigatório, o molho é proibido.',ARRAY['Bata os escalopes entre duas películas até 4 mm de espessura.','Tempere e passe por farinha, ovo batido e pão ralado sem calcar.','Aqueça manteiga clarificada abundante a 170 °C.','Frite 2 minutos de cada lado, agitando a frigideira para o panado inchar.','Escorra em papel e sirva de imediato com um gomo de limão.']::text[]),
('pierogi','pt','Pierogi ruskie','Cracóvia, Polónia','Pastéis recheados com batata, queijo fresco e cebola frita, escalfados e por vezes salteados em manteiga. Cada família polaca guarda a sua forma de selar as bordas.',ARRAY['Amasse farinha, água morna, ovo e sal numa massa macia; repouse 30 minutos.','Esmague as batatas cozidas com o queijo e uma cebola frita; tempere bem.','Estenda a massa fina, corte discos de 8 cm e coloque uma noz de recheio.','Sele bem as bordas e escalfe 3 minutos em água salgada em fervura branda.','Salteie em manteiga com a restante cebola e sirva com natas ácidas.']::text[]),
('moussaka','pt','Moussaka','Atenas, Grécia','Camadas de beringela assada e carne de borrego com canela, sob um béchamel dourado no forno. A versão moderna, criada pelo chef Tselementes nos anos 20, tornou-se o prato nacional.',ARRAY['Salgue as fatias de beringela, deixe suar 30 minutos e asse-as no forno com azeite.','Aloure o borrego com cebola e alho, junte tomate, vinho e canela e reduza 25 minutos.','Prepare um béchamel espesso e envolva o queijo e uma gema fora do lume.','Monte: beringela, carne, beringela e cubra com o béchamel.','Leve ao forno 45 minutos a 180 °C e repouse 20 minutos antes de cortar.']::text[]),
('fish-and-chips','pt','Fish and chips','Londres, Reino Unido','Um lombo de bacalhau fresco num polme de cerveja que estala ao morder, com batatas grossas e puré de ervilhas com hortelã. O vinagre de malte faz parte do ritual.',ARRAY['Corte as batatas em palitos grossos e branqueie-as 8 minutos a 140 °C.','Misture as farinhas, o fermento e a cerveja gelada mesmo antes de fritar: o polme fica grumoso.','Seque os lombos, passe por farinha, mergulhe no polme e frite a 180 °C 6 a 7 minutos.','Volte a fritar as batatas a 190 °C até ficarem bem douradas.','Esmague as ervilhas com hortelã e sirva com sal e vinagre de malte.']::text[]),
('kottbullar','pt','Köttbullar','Estocolmo, Suécia','Pequenas almôndegas de vaca e porco ligadas com pão e leite, servidas com molho cremoso, puré e doce de airela. A acidez do fruto corta a untuosidade.',ARRAY['Demolhe o pão ralado no leite e aloure a cebola picada em manteiga.','Misture as carnes, o ovo, a cebola fria e a pimenta-da-jamaica até obter massa lisa.','Enrole almôndegas do tamanho de uma noz com as mãos húmidas.','Aloure-as em manteiga agitando a frigideira para ficarem redondas e reserve.','Deglace com o caldo, junte as natas, deixe engrossar 5 minutos e devolva as almôndegas.']::text[]),
('borscht','pt','Borscht','Kiev, Ucrânia','Uma sopa púrpura de beterraba e couve, ácida e profunda, de que cada aldeia ucraniana defende a sua versão. A colher de smetana desenha espirais rosadas ao derreter.',ARRAY['Faça um caldo com a carne, o louro e a cebola inteira durante 1h30 e desfie a carne.','Refogue cenoura, cebola e beterraba raladas com o concentrado de tomate e o vinagre, que fixa a cor.','Junte batatas e couve ao caldo e coza 12 minutos.','Incorpore o refogado de beterraba e ferva apenas 5 minutos para manter o vermelho vivo.','Junte o alho esmagado fora do lume, repouse uma noite e sirva com smetana e endro.']::text[]),
('fondue-moitie','pt','Fondue meio a meio','Friburgo, Suíça','Metade gruyère, metade vacherin de Friburgo, derretidos em vinho branco com um toque de alho e kirsch. Mexe-se em oito, nunca em círculo, e quem perde o pão paga a rodada.',ARRAY['Esfregue o caquelon com o dente de alho cortado e deite o vinho branco.','Junte os queijos ralados em lume brando, mexendo em oito com colher de pau.','Dissolva o amido no kirsch e incorpore assim que a mistura estiver homogénea.','Tempere com pimenta e noz-moscada e deixe fremir 2 minutos sem ferver.','Coloque o caquelon no fogareiro e mergulhe cubos grandes de pão.']::text[]),
('gulyas','pt','Goulash','Budapeste, Hungria','Originalmente a sopa dos boiadeiros da puszta, cozida em caldeirão sobre o fogo. O pimentão, junto fora do lume para não amargar, dá a cor ardente a este caldo de vaca e batata.',ARRAY['Aloure as cebolas em banha durante 15 minutos até ficarem douradas.','Retire do lume, junte o pimentão e mexa logo para não queimar.','Junte a carne em cubos, o cominho e o alho, cubra com água e coza 1h30 em lume brando.','Acrescente pimentos, tomate e batata e cozinhe mais 30 minutos.','Acerte o sal e deixe repousar: o goulash é melhor no dia seguinte.']::text[]),
('sushi-edomae','pt','Sushi edomae','Tóquio, Japão','No século XIX o sushi era comida de rua vendida à peça na baía de Edo. Tudo depende do shari: um arroz morno e avinagrado cujos grãos devem manter-se soltos.',ARRAY['Lave o arroz até a água sair límpida, coza-o e deixe repousar tapado 10 minutos.','Aqueça vinagre, açúcar e sal, deite sobre o arroz quente e separe os grãos abanando.','Apare os peixes e corte fatias regulares de 8 g contra a fibra.','Molde bolinhas de arroz de 15 g na palma húmida, sem nunca esmagar.','Coloque uma ponta de wasabi e a fatia de peixe, pressione com suavidade e sirva de imediato.']::text[]),
('ramen-tonkotsu','pt','Ramen tonkotsu','Fukuoka, Japão','O caldo de ossos de porco de Kyushu ferve com força doze horas até ficar branco e cremoso. Sobre massa fina e direita, coroa-se com chashu e um ovo marinado de gema mole.',ARRAY['Escalde os ossos 10 minutos, lave-os e ferva com força 8 horas repondo a água.','Enrole e ate a entremeada e estufe-a 2 horas em soja, mirin, alho e gengibre.','Coza os ovos 6 minutos e meio, descasque e marine de um dia para o outro no molho do estufado.','Coza a massa apenas 90 segundos e escorra energicamente.','Deite o caldo a ferver sobre a massa e junte chashu, meio ovo, cebolinho e nori.']::text[]),
('peking-duck','pt','Pato de Pequim','Pequim, China','Servido na corte Ming desde o século XV, o pato é escaldado, envernizado com malte e seco ao ar antes de assar. Come-se primeiro a pele, estaladiça como vidro, enrolada numa panqueca fina.',ARRAY['Separe a pele da carne com ar ou o cabo de uma colher, sem a furar.','Escalde o pato, pincele com a mistura de maltose e vinagre e seque 24 horas no frio.','Asse 30 minutos a 200 °C e depois 50 minutos a 160 °C, com o peito para cima.','Corte a pele em losangos e depois a carne em lâminas finas.','Sirva com as panquecas mornas, molho hoisin, pepino e cebolinho em palitos.']::text[]),
('mapo-tofu','pt','Mapo tofu','Chengdu, China','O prato emblemático de Sichuan, atribuído à mulher marcada por varíola de um estalajadeiro do século XIX. A pimenta de Sichuan provoca o famoso málà: ardor suave e formigueiro elétrico.',ARRAY['Corte o tofu em cubos de 2 cm e demolhe-os 5 minutos em água quente com sal.','Frite a carne até ficar crocante e junte doubanjiang e feijão preto fermentado.','Junte alho, gengibre e caldo e deslize com cuidado os cubos de tofu.','Deixe fremir 5 minutos sem mexer, apenas agitando o wok.','Ligue com o amido em três vezes, regue com óleo de malagueta e polvilhe pimenta de Sichuan.']::text[]),
('har-gow','pt','Har gow e dim sum','Cantão, China','A rainha das casas de chá cantonesas: um camarão inteiro numa massa translúcida com exatamente treze pregas. O yum cha faz-se de manhã, entre cestos de bambu e bules sempre cheios.',ARRAY['Deite a água a ferver de uma vez sobre os amidos e trabalhe logo até obter uma bola lisa.','Pique metade dos camarões e deixe os restantes inteiros; misture com o resto do recheio.','Achate discos muito finos com a lâmina untada de um cutelo.','Recheie e dobre formando pelo menos dez pregas apertadas de um lado.','Coza a vapor forte 6 a 8 minutos num cesto de bambu forrado.']::text[]),
('kimchi-jjigae','pt','Kimchi jjigae','Seul, Coreia do Sul','O guisado que se faz quando o kimchi está demasiado ácido para comer cru — e é aí que dá o melhor de si. Chega à mesa ainda a borbulhar na panela de pedra.',ARRAY['Frite a entremeada em tiras no óleo de sésamo até libertar a gordura.','Junte o kimchi cortado e o seu suco e salteie 5 minutos para concentrar a acidez.','Envolva gochujang, gochugaru, alho e açúcar e deite o caldo.','Deixe ferver destapado 20 minutos.','Junte o tofu às fatias e o cebolinho, cozinhe mais 5 minutos e sirva com arroz branco.']::text[]),
('pad-thai','pt','Pad thai','Banguecoque, Tailândia','Tornado prato nacional nos anos 30 para reduzir o consumo de arroz, o pad thai joga com quatro sabores: tamarindo ácido, açúcar de palma, molho de peixe e malagueta. O wok tem de estar em brasa.',ARRAY['Demolhe a massa 30 minutos em água morna: deve ficar firme.','Misture tamarindo, açúcar de palma e molho de peixe até dissolver por completo.','Salteie o tofu, o camarão seco e o camarão fresco no wok bem quente.','Junte a massa e o molho, salteie 2 minutos, empurre para o lado e mexa os ovos.','Termine com rebentos de soja e cebolinho-alho; sirva com amendoim, malagueta e lima.']::text[]),
('pho-bo','pt','Phở bò','Hanói, Vietname','Um caldo límpido de rabo e ossos de vaca perfumado com especiarias tostadas: anis-estrelado, canela, cardamomo preto. Em Hanói bebe-se desde as seis da manhã, num banco de plástico.',ARRAY['Escalde os ossos 10 minutos e lave-os bem para obter um caldo límpido.','Queime a cebola e o gengibre inteiros na chama até enegrecerem.','Coza ossos, cebola, gengibre e especiarias tostadas 4 horas, escumando, sem ferver.','Tempere com molho de peixe e coe o caldo duas vezes.','Escalde a massa, disponha a carne crua em lâminas e deite o caldo a ferver; ervas à parte.']::text[]),
('nasi-goreng','pt','Nasi goreng','Jacarta, Indonésia','Nascido da recusa em deitar fora o arroz da véspera, este arroz frito deve a cor âmbar ao kecap manis, uma soja espessa e doce. Coroa-se com um ovo estrelado rendilhado e krupuk.',ARRAY['Pise chalotas, alho, malaguetas e pasta de camarão até obter uma pasta lisa.','Frite-a em óleo quente até perfumar, cerca de 2 minutos.','Junte o frango e o camarão e salteie-os rapidamente.','Envolva o arroz frio desfazendo-o com a espátula e depois o kecap manis.','Salteie em lume máximo 3 minutos e sirva com um ovo estrelado e pepino.']::text[]),
('penang-laksa','pt','Assam laksa','Penang, Malásia','Uma sopa de massa com cavala desfiada, acidulada pelo tamarindo e pela flor de gengibre. Ao contrário do laksa de coco, o de Penang é vivo, picante e refrescante.',ARRAY['Escalfe a cavala 10 minutos, guarde a água e desfie a carne retirando todas as espinhas.','Triture malaguetas, erva-príncipe, galanga e pasta de camarão numa pasta rempah.','Refogue-a e junte a água do peixe, o tamarindo e a flor de gengibre; coza 30 minutos.','Devolva o peixe desfiado, adoce e tempere até equilibrar o ácido e o salgado.','Sirva sobre a massa grossa com ananás, pepino, cebola roxa e hortelã.']::text[]),
('butter-chicken','pt','Frango à manteiga','Deli, Índia','Inventado em Deli nos anos 50 para aproveitar o frango tandoori que sobrava, cozinhado num molho de tomate e manteiga. As natas nunca ficam insossas: o feno-grego seco levanta tudo no final.',ARRAY['Marine o frango 4 horas em iogurte, alho, gengibre e especiarias.','Grelhe-o em forno bem quente até as pontas tostarem ligeiramente.','Reduza o puré de tomate com a manteiga 20 minutos, até escurecer.','Triture o molho até ficar perfeitamente liso e junte natas e açúcar.','Devolva o frango, coza 10 minutos e esfarele o feno-grego seco entre os dedos ao servir.']::text[]),
('masala-dosa','pt','Masala dosa','Bengaluru, Índia','Uma panqueca fermentada de arroz e lentilhas, espalhada tão fina que fica renda estaladiça, enrolada sobre batata com açafrão-da-terra. A fermentação natural dá-lhe a acidez.',ARRAY['Demolhe arroz e lentilhas em separado 6 horas com o feno-grego e triture até obter massa lisa.','Fermente 12 horas em local morno, até duplicar e cheirar ácida.','Prepare o recheio: mostarda e folhas de caril rebentadas em ghee, cebola, açafrão-da-terra e batata esmagada.','Deite uma concha de massa numa chapa muito quente e espalhe em espiral com as costas da concha.','Regue com ghee, coloque o recheio ao centro, dobre e sirva com sambar e chutney de coco.']::text[]),
('hyderabadi-biryani','pt','Biryani de Hyderabad','Hyderabad, Índia','O kacchi biryani coze a carne crua marinada e o arroz meio cozido juntos, selados sob massa de pão. O vapor preso, o dum, faz todo o trabalho: a tampa só se levanta à mesa.',ARRAY['Marine o borrego 3 horas em iogurte, cebola frita, ervas, malaguetas e especiarias.','Ferva o basmati apenas 4 minutos em água muito salgada e perfumada.','Coloque a carne crua marinada no fundo de uma panela grossa e cubra com o arroz.','Regue com açafrão infundido em leite morno e ghee derretido e sele a tampa com massa.','Coza 15 minutos em lume forte e 40 no mínimo; envolva só à mesa.']::text[]),
('khachapuri','pt','Khachapuri adjariano','Tbilisi, Geórgia','Um pão em forma de barco cheio de queijo derretido, onde se parte um ovo à saída do forno. Mistura-se a gema e a manteiga com o queijo e arrancam-se as bordas para molhar.',ARRAY['Amasse farinha, leite morno, fermento, açúcar e sal; deixe levedar 1 hora.','Misture os queijos ralados, guardando algum líquido para ficarem macios.','Estenda cada bola em oval, recheie e enrole as bordas para dentro apertando as pontas.','Leve ao forno 12 minutos a 230 °C, até dourar e o queijo borbulhar.','Abra um poço, parta um ovo, junte manteiga e volte 2 minutos ao forno.']::text[]),
('plov','pt','Plov de Samarcanda','Samarcanda, Usbequistão','Cozinhado por homens num kazan gigante, tanto para casamentos como para dias comuns. O arroz nunca se mistura: coze por cima das cenouras amarelas e do borrego, absorvendo o zirvak.',ARRAY['Lave o arroz sete vezes e deixe-o de molho em água morna salgada.','Derreta a gordura no kazan e aloure a carne em pedaços grandes e depois as cebolas.','Junte as cenouras em palitos grossos e o cominho, mexendo o mínimo possível.','Cubra com água, junte grão-de-bico e cabeças de alho inteiras e coza 40 minutos: é o zirvak.','Espalhe o arroz escorrido por cima, água 2 cm acima, coza destapado e 20 minutos tapado sem lume.']::text[]),
('iskender-kebab','pt','İskender kebab','Bursa, Turquia','Inventado em Bursa em 1867 por İskender Efendi, que teve a ideia de pôr o espeto na vertical. As fatias de borrego assentam em pão torrado, com molho de tomate e manteiga queimada a ferver.',ARRAY['Corte o borrego em lâminas finas e marine 2 horas com cebola ralada, orégãos e pimentão.','Salteie em frigideira muito quente, em pequenas quantidades, para caramelizar.','Reduza o puré de tomate com um pouco de manteiga até napar.','Corte os pães em losangos e aloure-os na frigideira.','Monte pão, carne, molho e iogurte e deite a manteiga queimada a ferver à frente dos convidados.']::text[]),
('hummus-beiruti','pt','Húmus de Beirute','Beirute, Líbano','Um puré de grão-de-bico de uma sedosidade absoluta, onde o tahine conta tanto como o limão. O segredo libanês é um pouco de bicarbonato na água de cozedura, que solta as peles.',ARRAY['Demolhe o grão de um dia para o outro com metade do bicarbonato.','Coza-o 1 hora com o restante, até esmagar entre dois dedos.','Triture o alho com o sumo de limão, deixe infundir 10 minutos e coe.','Triture demoradamente o grão quente com tahine, limão e água gelada, pelo menos 4 minutos.','Espalhe abrindo um sulco, regue com azeite e polvilhe sumagre e cominho.']::text[]),
('tagine-agneau','pt','Tagine de borrego com ameixas','Fez, Marrocos','O prato das grandes ocasiões de Fez, onde o doce e o salgado se encontram sem se anularem. A tampa cónica devolve o vapor ao fundo: a carne coze no próprio suco, quase sem água.',ARRAY['Aloure o borrego com as cebolas raladas, a manteiga, o açafrão e o gengibre.','Cubra até meio com água, junte a canela e coza tapado 2 horas.','Deixe as ameixas inchar num pouco de caldo com o mel e a canela.','Aloure as amêndoas e toste o sésamo a seco.','Nape a carne com o suco reduzido e disponha ameixas, água de flor de laranjeira, amêndoas e sésamo.']::text[]),
('couscous','pt','Cuscuz','Tunes, Tunísia','A sêmola rolada à mão coze no vapor do próprio caldo, três vezes seguidas, para ficar leve e solta. À sexta-feira todo o Magrebe se junta à volta do mesmo prato.',ARRAY['Aloure a carne e a cebola, junte tomate e harissa e cubra com água.','Humedeça a sêmola, role-a entre as palmas e deixe-a inchar 10 minutos.','Coza-a a vapor 20 minutos por cima do caldo.','Espalhe, borrife, solte com um garfo e repita mais duas vezes.','Junte os legumes ao caldo conforme o tempo de cozedura e sirva a sêmola em cúpula, o caldo à parte.']::text[]),
('koshari','pt','Koshari','Cairo, Egito','O prato de rua egípcio por excelência: arroz, lentilhas, macarrão e grão empilhados, cobertos de molho de tomate com vinagre e coroados de cebola frita. Uma pilha de amidos que não devia resultar, e resulta.',ARRAY['Corte as cebolas muito finas e frite-as devagar até ficarem escuras e crocantes.','Coza em separado lentilhas, arroz e macarrão e misture arroz e lentilhas no óleo perfumado.','Faça o molho: alho, cominho, puré de tomate e vinagre, reduzido 15 minutos.','Prepare uma daqqa picante com vinagre, alho e malagueta.','Empilhe lentilhas com arroz, macarrão e grão, regue com molho e cubra de cebola frita.']::text[]),
('doro-wat','pt','Doro wat','Adis Abeba, Etiópia','O guisado das grandes festas etíopes, cuja base é uma montanha de cebolas cozidas a seco durante uma hora antes de qualquer gordura. O berbere dá-lhe o vermelho escuro e o calor persistente.',ARRAY['Esfregue os pedaços de frango com limão e sal e deixe repousar 30 minutos.','Coza as cebolas picadas a seco numa panela 45 minutos, mexendo com frequência.','Junte a manteiga especiada, o alho, o gengibre e o berbere e coza 10 minutos.','Junte o frango, com pouquíssimo líquido, e coza tapado 1 hora.','Introduza os ovos cozidos riscados no molho 10 minutos antes do fim; sirva sobre injera.']::text[]),
('jollof-rice','pt','Arroz jollof','Lagos, Nigéria','O arroz vermelho que alimenta há décadas uma rivalidade alegre entre a Nigéria, o Gana e o Senegal. O verdadeiro segredo é a camada ligeiramente queimada do fundo, que perfuma tudo.',ARRAY['Triture tomates, pimentos, malaguetas e uma cebola num puré liso.','Frite o concentrado de tomate em óleo quente 5 minutos, até escurecer.','Deite o puré e reduza 20 minutos: tem de perder o sabor cru.','Junte caldo, especiarias e arroz lavado, tape com papel vegetal e depois a tampa.','Coza 25 minutos em lume mínimo sem levantar a tampa e solte com um garfo.']::text[]),
('thieboudienne','pt','Thieboudienne','Dacar, Senegal','O prato nacional senegalês, inscrito pela UNESCO: arroz cozido em caldo de peixe com legumes e um recheio de ervas chamado rof. Serve-se numa travessa comum, cada um comendo à sua frente.',ARRAY['Pise salsa, alho, malagueta e sal para o rof e recheie com ele cortes feitos no peixe.','Frite as postas, reserve e refogue a cebola com o concentrado de tomate.','Junte água, peixe seco e legumes; coza 25 minutos retirando-os à medida que amolecem.','Devolva o peixe 10 minutos, retire-o e deite o arroz partido no caldo.','Coza o arroz tapado 25 minutos, deixe o fundo caramelizar e sirva com peixe e legumes.']::text[]),
('bobotie','pt','Bobotie','Cidade do Cabo, África do Sul','Um gratinado de carne especiada com frutos secos, coberto por um creme de ovo e folhas de louro. Vem da cozinha cabo-malaia e conta cinco séculos de trocas entre a Ásia e a África austral.',ARRAY['Demolhe o pão no leite e esprema-o, guardando o leite.','Aloure as cebolas, junte o caril e o açafrão-da-terra e depois a carne.','Envolva o pão, o doce de alperce, o vinagre, as passas e as amêndoas; tempere bem.','Calque num tabuleiro, bata os ovos com o leite reservado e deite sobre a carne.','Espete as folhas de louro e leve ao forno 40 minutos a 180 °C, até ganhar presa.']::text[])
insert into public.atlas_dish_texts (dish_id,lang,name,place,description,steps) values
('nyama-choma','pt','Nyama choma','Nairobi, Quénia','Carne de cabra grelhada devagar sobre carvão, sem marinada: bastam o sal e o fumo. Corta-se em pedaços pequenos numa tábua e come-se com os dedos, com kachumbari e ugali.',ARRAY['Salgue generosamente a carne em peças grandes e deixe-a atemperar 1 hora.','Prepare brasas suaves e grelhe longe da chama viva 1h30, virando com frequência.','Pincele com água salgada e limão durante a cozedura para não secar.','Prepare o kachumbari: tomate, cebola roxa, malagueta e coentros com limão.','Prepare o ugali deitando a farinha de milho em chuva na água a ferver e trabalhando até descolar.']::text[]),
('tacos-al-pastor','pt','Tacos al pastor','Cidade do México, México','O shawarma libanês reinventado com porco e malagueta pelos migrantes chegados a Puebla nos anos 20. O trompo gira diante da chama e o taquero corta a carne atirando o ananás para a tortilha.',ARRAY['Hidrate as malaguetas 20 minutos e triture-as com achiote, vinagre, alho e especiarias.','Corte o porco em lâminas finas e marine pelo menos 3 horas nessa pasta vermelha.','Empilhe as lâminas alternando com rodelas de ananás e asse 1 hora a 200 °C.','Fatie a carne assada bem fina e salteie numa chapa a escaldar.','Sirva em tortilhas de milho quentes com cebola, coentros, ananás grelhado e lima.']::text[]),
('mole-poblano','pt','Mole poblano','Puebla, México','Um molho quase negro que reúne mais de vinte ingredientes, entre eles quatro malaguetas secas e um toque de chocolate. Diz a lenda que uma freira de Puebla o improvisou para um arcebispo de passagem.',ARRAY['Toste as malaguetas a seco sem queimar, retire as sementes e demolhe 30 minutos.','Frite em separado amêndoas, amendoins, passas, sésamo, tortilha e especiarias na banha.','Triture tudo com os tomates e algum caldo, por partes, até obter uma pasta muito lisa.','Frite essa pasta na banha 20 minutos mexendo sempre e alivie com caldo.','Junte o chocolate, coza 1 hora e sirva sobre o frango escalfado com sésamo tostado.']::text[]),
('ropa-vieja','pt','Ropa vieja','Havana, Cuba','«Roupa velha»: a carne, desfiada após horas de cozedura, parece tecido rasgado. O refogado de pimentos, cominho e azeitonas faz dela o prato de domingo cubano por excelência.',ARRAY['Coza a carne 2 horas num caldo aromatizado até se desfazer.','Desfie-a com um garfo no sentido da fibra e reserve o caldo.','Prepare o refogado: cebola, pimentos e alho apurados devagar em azeite.','Junte tomate, vinho, cominho, orégãos e louro e reduza 15 minutos.','Envolva a carne desfiada e um pouco de caldo, coza 30 minutos, junte as azeitonas e sirva com arroz.']::text[]),
('jerk-chicken','pt','Frango jerk','Kingston, Jamaica','Uma técnica herdada dos quilombolas jamaicanos, que fumavam a carne sobre madeira de pimenta para a conservar nas montanhas. A malagueta scotch bonnet e a pimenta-da-jamaica formam uma marinada ardente.',ARRAY['Triture todos os aromáticos numa marinada espessa, doseando a malagueta conforme a coragem.','Faça cortes até ao osso e massaje o frango com a marinada; repouse 12 horas.','Prepare um fogo indireto com aparas de madeira húmidas para o fumo.','Asse o frango com a pele para cima, tapado, 45 minutos.','Termine sobre as brasas 10 minutos para caramelizar e sirva com arroz e feijão.']::text[]),
('gumbo','pt','Gumbo','Nova Orleães, Estados Unidos','O prato crioulo onde se encontram África, França e os Choctaw: um roux cozido até à cor do chocolate, quiabo e a «santíssima trindade» de cebola, aipo e pimento. Serve-se sobre um monte de arroz.',ARRAY['Faça o roux: farinha e óleo em lume médio, mexendo sem parar 30 a 40 minutos até à cor de chocolate.','Deite de uma vez a trindade picada: trava a cozedura do roux.','Junte a salsicha, o alho e as especiarias e incorpore aos poucos o caldo quente.','Coza destapado 1 hora, junte o quiabo e cozinhe mais 20 minutos.','Junte o camarão 5 minutos antes do fim e sirva sobre arroz branco.']::text[]),
('clam-chowder','pt','Clam chowder','Boston, Estados Unidos','Uma sopa espessa de amêijoas, batatas e bacon fumado que aquece os portos da Nova Inglaterra desde o século XVIII. Em Boston, juntar-lhe tomate ainda é uma provocação.',ARRAY['Abra as amêijoas a vapor com um fundo de água, coe bem o suco e pique a carne.','Derreta o bacon em cubos e aloure as cebolas e o aipo nessa gordura.','Polvilhe com a farinha, deite o suco das amêijoas e deixe engrossar.','Junte as batatas em cubos, o tomilho e o louro e coza 15 minutos.','Junte leite, natas e amêijoas picadas, aqueça sem ferver e sirva com bolachas.']::text[]),
('poutine','pt','Poutine','Montreal, Canadá','Batatas fritas, grãos de queijo e molho escuro: nascida nas tascas do Quebec rural no final dos anos 50, a poutine tornou-se um emblema nacional. O queijo tem de chiar nos dentes.',ARRAY['Corte as batatas em palitos grossos e lave-as em água fria.','Faça um roux louro com manteiga e farinha, deite os caldos e engrosse 10 minutos.','Realce o molho com vinagre, molho inglês e pimenta.','Frite as batatas primeiro a 150 °C e depois a 190 °C até ficarem bem douradas.','Monte as batatas quentes, espalhe os grãos de queijo e regue com o molho a ferver para começarem a derreter.']::text[]),
('gallo-pinto','pt','Gallo pinto','San José, Costa Rica','O pequeno-almoço costa-riquenho: arroz e feijão preto da véspera, salteados juntos até o arroz ficar malhado — daí «galo pintado». O molho Lizano é indispensável.',ARRAY['Refogue cebola, pimento e alho bem picados até amolecerem.','Junte o feijão preto com um pouco do seu caldo.','Envolva o arroz frio e o molho Lizano, misturando sem esmagar os grãos.','Salteie 5 minutos para o arroz ganhar cor e o fundo agarrar ligeiramente.','Sirva com ovo estrelado, banana-pão frita e coentros frescos.']::text[]),
('feijoada','pt','Feijoada','Rio de Janeiro, Brasil','O guisado de feijão preto e porco que o Brasil come às quartas e aos sábados, nunca sozinho nem à pressa. Leva obrigatoriamente farofa, arroz, couve salteada e laranja para aligeirar.',ARRAY['Demolhe a carne-seca 12 horas mudando a água várias vezes.','Coza o feijão preto demolhado com as folhas de louro durante 1 hora.','Junte as carnes da que precisa de mais tempo para a que precisa de menos e coza 2 horas.','Retire uma concha de feijão, amasse-a com alho frito e devolva-a para engrossar.','Sirva com arroz, couve salteada, farofa dourada em manteiga e gomos de laranja.']::text[]),
('moqueca-baiana','pt','Moqueca baiana','Salvador, Brasil','Um guisado de peixe com leite de coco e azeite de dendê, cozido numa panela de barro preto da Bahia. O dendê, herança oeste-africana, dá-lhe o laranja profundo e o aroma inconfundível.',ARRAY['Marine o peixe 20 minutos em sumo de lima, alho e sal.','Disponha em camadas na panela: cebola, tomate, pimentos e depois o peixe.','Deite o leite de coco e o dendê, sem nunca mexer.','Tape e coza 20 minutos em lume médio, apenas agitando a panela.','Junte o camarão e os coentros 5 minutos antes do fim; sirva com arroz e pirão.']::text[]),
('asado-argentino','pt','Asado argentino','Buenos Aires, Argentina','Muito mais do que um churrasco: um ritual de domingo em que o asador reina sozinho sobre as brasas durante três horas. A carne coze devagar, longe do fogo, com sal grosso e chimichurri.',ARRAY['Acenda o fogo uma hora antes: assa-se sobre brasas, nunca sobre a chama.','Salgue as costelas com sal grosso e coloque-as com o osso para baixo, a 20 cm das brasas.','Asse 2 horas sem lhes tocar, juntando brasas frescas com regularidade.','Prepare o chimichurri: salsa, alho, orégãos, vinagre, azeite e malagueta, em repouso 1 hora.','Vire a carne apenas uma vez, por 30 minutos, e corte para servir com o chimichurri.']::text[]),
('ceviche','pt','Ceviche','Lima, Peru','Peixe cru «cozido» pela acidez da lima em poucos minutos — os cozinheiros de Lima dizem hoje que nunca mais de cinco. O sumo que fica, o leite de tigre, bebe-se de um trago.',ARRAY['Corte o peixe muito fresco em cubos regulares de 2 cm e mantenha-os frios.','Esprema as limas sem esmagar a casca, que tornaria o sumo amargo.','Triture parte do sumo com um pouco de peixe, aipo, alho e malagueta: é o leite de tigre.','Misture peixe, sal, leite de tigre e cebola roxa em juliana; espere 3 minutos.','Sirva de imediato com batata-doce cozida, milho e coentros picados.']::text[]),
('arepas','pt','Arepas reina pepiada','Caracas, Venezuela','Um bolo de milho pré-cozido, tostado e depois aberto e recheado como um bolso. A reina pepiada, criada em 1955 em honra de uma Miss Venezuela, junta frango desfiado e abacate.',ARRAY['Misture farinha de milho, água morna e sal e deixe repousar 5 minutos para hidratar.','Forme bolos de 1,5 cm alisando as bordas entre as palmas.','Aloure 4 minutos de cada lado na frigideira e termine 10 minutos no forno: devem soar ocos.','Desfie o frango escalfado e misture com abacate esmagado, maionese, cebola e lima.','Abra as arepas ainda quentes e recheie generosamente.']::text[]),
('pastel-de-choclo','pt','Pastel de choclo','Santiago, Chile','Um picado de vaca, cebola, azeitonas e ovo cozido, coberto por um puré de milho fresco perfumado com manjericão. Polvilhado com açúcar, carameliza no forno e sai a borbulhar.',ARRAY['Refogue demoradamente as cebolas picadas, junte a carne, o cominho e o pimentão: é o pino.','Triture o milho com o leite e o manjericão e engrosse esse puré em lume brando 15 minutos.','Reparta o pino por tigelas individuais e junte frango, azeitonas, passas e ovo cozido.','Cubra com o puré de milho e alise a superfície.','Polvilhe com açúcar e leve ao forno 30 minutos a 200 °C, até caramelizar.']::text[]),
('bandeja-paisa','pt','Bandeja paisa','Medellín, Colômbia','Uma travessa desmesurada nascida da comida dos almocreves de Antioquia, que caminhavam o dia todo na montanha. Feijão, arroz, carne picada, chicharrón, ovo, banana-pão, abacate e arepa, tudo ao mesmo tempo.',ARRAY['Coza o feijão vermelho demolhado 2 horas com um pedaço de banana-pão verde, que o engrossa.','Prepare um hogao: tomate e cebola apurados devagar, para juntar ao feijão.','Faça cortes na entremeada e cozinhe tapada e depois destapada até o courato estalar.','Frite a carne picada com cominho, grelhe os chouriços e frite as bananas maduras.','Disponha tudo lado a lado numa travessa grande com o ovo estrelado, o abacate e a arepa.']::text[]),
('pavlova','pt','Pavlova','Auckland, Nova Zelândia','Um disco de merengue estaladiço por fora e de marshmallow por dentro, criado em honra da bailarina Anna Pavlova na digressão de 1926. A Nova Zelândia e a Austrália ainda disputam a autoria.',ARRAY['Bata as claras à temperatura ambiente juntando o açúcar em chuva muito devagar.','Bata 10 minutos: o merengue deve aguentar se virar a taça ao contrário.','Envolva com a espátula o amido, o vinagre e a baunilha.','Forme um disco de 22 cm com o centro ligeiramente afundado e leve ao forno 90 minutos a 120 °C.','Deixe arrefecer no forno desligado com a porta entreaberta e cubra com natas batidas e fruta.']::text[]),
('meat-pie','pt','Meat pie australiana','Melbourne, Austrália','A empada que se come de pé nos estádios australianos, com uma mão e um jato de molho de tomate. Massa quebrada em baixo, folhada em cima e um guisado de vaca espesso que não escorre.',ARRAY['Corte a carne em cubos pequenos e aloure-a por partes para ganhar cor.','Junte a cebola, polvilhe com farinha e regue com caldo, tomate e molho inglês.','Coza 1 hora até obter um molho muito espesso e arrefeça por completo.','Forre as formas com massa quebrada, recheie com a carne fria e cubra com massa folhada.','Sele as bordas, pincele com ovo e leve ao forno 25 minutos a 200 °C.']::text[]),
('kokoda','pt','Kokoda','Suva, Fiji','O ceviche do Pacífico: o peixe marina em lima e depois repousa em leite de coco fresco, que suaviza a acidez. Serve-se tradicionalmente bem frio em meia casca de coco.',ARRAY['Corte o peixe branco muito fresco em cubos de 1,5 cm.','Cubra com sumo de lima e marine 20 minutos no frio, até ficar opaco.','Escorra o peixe deitando fora metade do sumo, demasiado ácido.','Misture com leite de coco, tomate picado, pepino, cebola e malagueta.','Leve ao frio 15 minutos e sirva bem fresco, polvilhado com cebolinho.']::text[]),
('poke','pt','Poke de ahi','Honolulu, Havai','Muito antes de ser moda global, o poke era o petisco dos pescadores havaianos: atum aos pedaços, sal marinho, algas e nozes de kukui. A palavra significa apenas «cortar».',ARRAY['Escolha atum de qualidade sashimi e corte-o em cubos de 2 cm.','Hidrate o wakame 10 minutos e pique-o grosseiramente.','Misture molho de soja, óleo de sésamo, malagueta e sal marinho.','Tempere o atum com delicadeza com as cebolas em juliana e a alga; repouse 15 minutos no frio.','Sirva sobre arroz morno avinagrado com abacate e sementes de sésamo tostadas.']::text[]),
('choucroute-garnie','pt','Choucroute guarnecida','Estrasburgo, França','Couve fermentada em sal, técnica chegada da China pela Europa central, estufada em riesling com cinco ou seis enchidos diferentes. Um prato de cervejaria que se partilha, nunca em porção individual.',ARRAY['Lave o chucrute em água fria e esprema-o com força para retirar o excesso de acidez.','Aloure as cebolas em banha e junte o chucrute, o zimbro e o louro.','Regue com riesling, enterre o toucinho e o lombo fumado, tape e coza 2 horas em lume muito brando.','Junte as batatas descascadas 40 minutos antes do fim.','Escalfe as salsichas à parte em água a fremir 10 minutos: nunca devem ferver.']::text[]),
('boeuf-bourguignon','pt','Bœuf bourguignon','Dijon, França','Um guisado camponês que o vinho tinto da Borgonha tornou célebre: a carne marina uma noite e depois desfaz-se em três horas. A guarnição de bacon, cebolinhas e cogumelos faz-se sempre à parte.',ARRAY['Marine a carne uma noite em vinho tinto com cenoura, cebola, tomilho e louro.','Escorra e seque bem os pedaços e aloure-os em pequenas quantidades.','Polvilhe com farinha, junte o concentrado de tomate, a marinada coada e o caldo.','Tape e coza 3 horas a 150 °C, até a carne ceder ao garfo.','Salteie à parte o bacon, as cebolinhas e os cogumelos e envolva-os no final.']::text[]),
('galette-sarrasin','pt','Galette de trigo-sarraceno','Rennes, França','O trigo-sarraceno, cultivado nas terras pobres da Bretanha desde o século XV, dá uma massa sem glúten que se espalha numa chapa a escaldar. A completa leva ovo, fiambre e emmental.',ARRAY['Misture farinha de trigo-sarraceno, sal e um ovo e junte a água aos poucos, batendo.','Deixe a massa repousar pelo menos 2 horas: deve ficar fluida e lisa.','Aqueça bem uma frigideira untada e espalhe uma concha de massa num disco muito fino.','Ao fim de 1 minuto, vire a galette, parta um ovo ao centro e espalhe fiambre e queijo.','Dobre os quatro bordos em quadrado e sirva bem quente, com sidra bruta.']::text[]),
('quiche-lorraine','pt','Quiche lorraine','Nancy, França','A verdadeira quiche lorraine não leva queijo nem cebola: massa, toucinho e uma migaine de natas, ovos e noz-moscada. A palavra vem do alsaciano Küchen e a receita é atestada desde o século XVI.',ARRAY['Forre uma forma com a massa, pique o fundo e leve ao frio 30 minutos.','Aloure o toucinho sem gordura e escorra-o em papel.','Bata ovos, natas e leite e tempere com sal, pimenta e noz-moscada ralada.','Espalhe o toucinho sobre a massa e deite o preparado por cima.','Leve ao forno 35 a 40 minutos a 180 °C: o centro deve ainda tremer à saída.']::text[]),
('ratatouille','pt','Ratatouille nissarda','Nice, França','O segredo da ratatouille está numa regra simples: cada legume coze em separado, ao seu ritmo, antes de se juntar aos outros. Nada se deve desfazer — cada garfada tem de se reconhecer.',ARRAY['Corte todos os legumes em cubos regulares de 2 cm, em separado.','Salteie a beringela sozinha em azeite até dourar e reserve.','Repita com as curgetes, depois os pimentos e depois as cebolas.','Apure os tomates com alho, tomilho e louro durante 20 minutos.','Junte tudo, coza destapado 15 minutos e acrescente o manjericão fora do lume.']::text[]),
('tartiflette','pt','Tartiflette','Annecy, França','Inventada nos anos 80 pelo sindicato do reblochon para escoar o queijo, a partir de um velho gratinado saboiano, a péla. A história é recente; o conforto permanece.',ARRAY['Coza as batatas com pele 20 minutos, deixe amornar e corte em rodelas grossas.','Aloure o toucinho e as cebolas, refresque com vinho branco e deixe evaporar.','Esfregue um tabuleiro com alho e alterne batatas com a mistura de toucinho e cebola.','Junte as natas e coloque o reblochon cortado ao meio, com a côdea para cima.','Leve ao forno 25 minutos a 200 °C até o queijo borbulhar e dourar.']::text[]),
('carbonade-flamande','pt','Carbonada flamenga','Lille, França','O guisado do norte, onde a cerveja escura substitui o vinho e uma fatia de pão de especiarias barrada com mostarda, derretida no molho, traz o agridoce. Fica melhor aquecido no dia seguinte.',ARRAY['Aloure a carne em cubos grandes na manteiga, por partes, e reserve.','Aloure devagar as cebolas laminadas na mesma panela.','Devolva a carne, polvilhe com farinha e deite a cerveja e o vinagre.','Barre o pão de especiarias com mostarda e pouse-o à superfície, com a mostarda para baixo.','Tape e coza 3 horas em lume muito brando; o molho engrossa sozinho.']::text[]),
('piperade','pt','Piperade','Baiona, França','Pimentos doces, tomate e malagueta de Espelette longamente apurados, ligados com ovo no último momento. Nas cores da bandeira basca, acompanha uma fatia de presunto de Baiona salteada.',ARRAY['Lamine os pimentos e apure-os 20 minutos com as cebolas em azeite.','Junte os tomates pelados e picados, o alho, o açúcar e a malagueta de Espelette.','Coza destapado 20 minutos: a piperade deve ficar untuosa, nunca líquida.','Salteie as fatias de presunto 30 segundos de cada lado e reserve.','Deite os ovos batidos na piperade quente e mexa fora do lume até ligar.']::text[]),
('aligot','pt','Aligot','Laguiole, França','Um puré de batata trabalhado com tomme fresca do Aubrac até formar longas fitas. Os monges serviam-no aos peregrinos de Santiago; o gesto do braço não mudou desde então.',ARRAY['Coza as batatas em água salgada e passe-as pelo passe-vite, nunca pela varinha.','Volte a pôr o puré em lume brando com manteiga, natas e alho esmagado.','Junte a tomme fresca em lâminas finas, em três vezes.','Trabalhe com a espátula em oitos largos, levantando a massa, 8 a 10 minutos.','Pare assim que o aligot formar uma fita contínua e sirva de imediato.']::text[]),
('cannele','pt','Canelés de Bordéus','Bordéus, França','Uma crosta quase queimada e um coração de pudim macio a rum e baunilha: todo o paradoxo do canelé está nesse contraste. A massa repousa 24 a 48 horas antes de ir para as formas de cobre.',ARRAY['Leve o leite a fremir com a manteiga e a vagem de baunilha aberta e deixe infundir.','Misture farinha e açúcar e envolva ovos e gemas sem bater, para não incorporar ar.','Deite o leite morno em fio, junte o rum, coe e repouse 24 horas no frio.','Unte as formas de cobre com a mistura de manteiga e cera de abelha, aquecidas e viradas.','Encha três quartos e coza 15 minutos a 240 °C e 50 minutos a 180 °C; desenforme quente.']::text[]),
('blanquette-veau','pt','Blanquette de vitela','Paris, França','Um guisado «branco»: a carne nunca aloura, é escalfada num caldo aromático que depois se transforma num molho ligado com gema e natas. Toda a sua finura vem dessa disciplina.',ARRAY['Cubra a carne com água fria, leve a fremir e escume com cuidado 10 minutos.','Junte cenouras, alhos-franceses, cebola com cravinho e ervas; escalfe 1h30 sem ferver.','Coza à parte os cogumelos e as cebolinhas com um pouco de manteiga e limão.','Prepare um roux branco, molhe com o caldo coado e coza 15 minutos.','Fora do lume, ligue com natas e gemas, junte um fio de limão e reúna tudo.']::text[]),
('kouign-amann','pt','Kouign-amann','Douarnenez, França','«Bolo de manteiga» em bretão: uma massa de pão folhada com quantidades desmedidas de manteiga com sal e açúcar, que carameliza no forno. Criado por volta de 1860 por um padeiro sem farinha bastante.',ARRAY['Amasse farinha, água, fermento e sal numa massa macia e deixe levedar 1 hora.','Estenda em retângulo, coloque a placa de manteiga ao centro e feche como um envelope.','Dê uma volta simples, polvilhe generosamente com açúcar e repita três vezes, com 30 minutos de repouso entre voltas.','Corte e disponha em formas untadas e açucaradas; deixe levedar 30 minutos.','Leve ao forno 40 minutos a 200 °C e desenforme logo, antes de o caramelo solidificar.']::text[]),
('caldo-verde','pt','Caldo verde','Braga, Portugal','A sopa do Minho, hoje presente em todas as festas portuguesas: um puré de batata com azeite onde se lança couve galega cortada fininha no último momento. Uma rodela de chouriço basta para a perfumar.',ARRAY['Coza as batatas, a cebola e o alho em água temperada durante 25 minutos.','Triture tudo com metade do azeite até obter um creme fluido.','Enrole as folhas de couve e corte-as o mais fininho que conseguir.','Leve o creme a ferver, deite a couve e conte exatamente 5 minutos.','Junte as rodelas de chouriço fritas e um fio de azeite cru em cada prato.']::text[]),
('pasteis-de-nata','pt','Pastéis de nata','Belém, Lisboa, Portugal','Nascidos no mosteiro dos Jerónimos, onde os monges aproveitavam as gemas que sobravam de engomar os hábitos com as claras. Cozidos a temperatura altíssima, saem malhados de preto e ainda a tremer.',ARRAY['Leve o açúcar e a água a 105 °C com a canela e a casca de limão: é a calda.','Dissolva a farinha em um pouco de leite frio e junte o restante leite a ferver, batendo.','Incorpore a calda morna em fio, arrefeça, junte as gemas e coe.','Enrole a massa folhada num rolo apertado, corte rodelas e espalme-as com o polegar nas formas.','Encha três quartos e leve ao forno 12 minutos a 280 °C, até malharem de preto.']::text[]),
('cozido-a-portuguesa','pt','Cozido à portuguesa','Coimbra, Portugal','O cozido português, onde se juntam vaca, porco, galinha, quatro enchidos e uma dúzia de legumes, cozidos juntos e servidos separadamente. Com o caldo coze-se o arroz que acompanha.',ARRAY['Demolhe as carnes salgadas de véspera e leve-as ao lume em água fria.','Junte a vaca, deixe fremir 1 hora escumando, e depois o porco e a galinha.','Junte os enchidos só no fim, para não rebentarem.','Coza os legumes à parte numa concha de caldo, cada um no seu tempo.','Faça o arroz com o caldo coado e disponha carnes, enchidos e legumes numa travessa grande.']::text[]),
('arroz-de-marisco','pt','Arroz de marisco','Figueira da Foz, Portugal','Ao contrário da paella, este arroz é malandrinho: caldoso, quase a escorrer, servido em panela de barro. O caldo feito com as cabeças do camarão dá-lhe toda a profundidade.',ARRAY['Descasque o camarão e ferva cabeças e cascas 20 minutos para obter um caldo forte.','Abra amêijoas e mexilhões com vinho branco, coe a água e junte-a ao caldo.','Faça um refogado de cebola, alho, pimento e tomate em azeite.','Junte o arroz, envolva e deite o caldo quente: três medidas de líquido para uma de arroz.','Coza 15 minutos, junte o marisco, o piri-piri e os coentros; sirva logo, bem malandrinho.']::text[]),
('sardinhas-assadas','pt','Sardinhas assadas','Setúbal, Portugal','Em junho, Portugal inteiro cheira a sardinha assada: fazem-se na brasa, sem outro tempero além do sal grosso, e comem-se sobre uma fatia de pão que recolhe a gordura.',ARRAY['Salgue generosamente as sardinhas inteiras, sem amanhar, e deixe repousar 1 hora.','Prepare brasas vivas e coloque as sardinhas numa grelha bem quente.','Asse 4 a 6 minutos de cada lado, sem mexer antes de a pele se soltar sozinha.','Asse os pimentos, pele-os e tempere com azeite, alho e vinagre: é a salada de pimentos.','Sirva com batata cozida e pão, pousando as sardinhas sobre as fatias.']::text[]),
('alheira','pt','Alheira de Mirandela','Mirandela, Portugal','Um enchido nascido de um estratagema: os judeus convertidos à força no século XVI faziam-no sem porco, com pão e aves, para parecer que o comiam. Tornou-se um emblema de Trás-os-Montes.',ARRAY['Pique ligeiramente as alheiras para não rebentarem ao cozinhar.','Frite-as em óleo quente 6 a 8 minutos, virando, até a pele ficar estaladiça.','Corte as batatas em palitos e frite-as em duas vezes.','Salteie os grelos escaldados com alho e azeite.','Termine com um ovo estrelado sobre a alheira, com a gema mole.']::text[]),
('leitao-bairrada','pt','Leitão da Bairrada','Mealhada, Portugal','Um leitão assado em forno de lenha, barrado com uma pasta de alho, banha e pimenta enfiada debaixo da pele. Toda a Bairrada julga um assador por uma só coisa: o estaladiço do courato.',ARRAY['Pise alho, banha, pimenta em grão, louro e sal até obter uma pasta espessa.','Descole a pele com a mão e barre o interior e o avesso da pele; deixe repousar 12 horas.','Espete o leitão, regue com vinho branco e asse 2h30 a 200 °C.','Pincele o courato de 30 em 30 minutos com um pano embebido na mistura de gordura.','Corte à lâmina e sirva com batata frita de pacote, pão e um espumante da Bairrada.']::text[]),
('acorda-alentejana','pt','Açorda alentejana','Évora, Portugal','A sopa dos pastores do Alentejo: apenas um pilão de alho e coentros, azeite, água a ferver deitada sobre pão duro e um ovo escalfado. A prova de que um grande prato pode não custar nada.',ARRAY['Pise o alho com o sal grosso e os talos de coentros até obter uma pasta verde.','Desfaça essa pasta com o azeite no fundo de uma terrina grande.','Escalfe os ovos em água com vinagre a fremir durante 3 minutos e reserve.','Deite a água a ferver do escalfado sobre a pasta de alho, mexendo.','Junte o pão duro às fatias, deixe inchar 2 minutos e coroe com os ovos e os coentros picados.']::text[])
insert into public.atlas_dish_texts (dish_id,lang,name,place,description,steps) values
('bibimbap','pt','Bibimbap','Jeonju, Coreia do Sul','«Arroz misturado»: cinco cores de legumes dispostas em círculo sobre o arroz, cada uma temperada à parte, e depois envolvidas de uma só colherada. Na tigela de pedra a quente, o fundo forma crosta dourada.',ARRAY['Tempere cada legume em separado: escaldado ou salteado, com óleo de sésamo, alho e sal.','Marine a carne em tiras 20 minutos em soja, açúcar, alho e sésamo e salteie.','Aqueça bem uma tigela de pedra untada e calque lá o arroz quente.','Disponha os legumes em gomos à volta e a carne ao centro.','Coroe com uma gema crua, junte gochujang e misture com vigor à mesa.']::text[]),
('adobo','pt','Adobo','Manila, Filipinas','Muito antes da chegada dos espanhóis, os filipinos já conservavam a carne em vinagre; os colonos apenas deram nome ao método. Vinagre, soja, alho e louro: quatro ingredientes e nenhum enfeite.',ARRAY['Marine o frango e o porco 1 hora em soja, vinagre, alho e pimenta.','Leve a ferver sem mexer e coza destapado 10 minutos para evaporar a aspereza do vinagre.','Junte o louro e a água, tape e coza 40 minutos.','Retire as carnes e reduza o molho com o açúcar até napar.','Aloure os pedaços na própria gordura, devolva-os ao molho e sirva com arroz.']::text[]),
('kottu-roti','pt','Kottu roti','Colombo, Sri Lanka','Ouve-se antes de se ver: duas lâminas de metal a picar o pão godamba numa chapa quente, num ritmo que cada tasca faz seu. É o prato da noite, nascido das sobras do almoço.',ARRAY['Corte os rotis em tiras finas e o frango cozido em pedaços pequenos.','Salteie cebola, alho-francês, cenoura, malaguetas e folhas de caril em lume muito forte.','Empurre os legumes para o lado e mexa os ovos no espaço livre.','Junte o frango, as especiarias e o molho de soja e envolva 1 minuto.','Deite as tiras de roti e pique tudo com a espátula, batendo na chapa, até ficar homogéneo.']::text[]),
('cevapi','pt','Ćevapi','Sarajevo, Bósnia e Herzegovina','Pequenos rolos de carne picada grelhados no carvão, servidos aos dez dentro de um pão somun ainda inchado de vapor, com cebola crua e kajmak. Herança otomana tornada identidade dos Balcãs.',ARRAY['Misture as carnes com o alho esmagado, o bicarbonato, o sal e a água com gás.','Trabalhe a massa 10 minutos até ficar pegajosa e deixe repousar 12 horas no frio.','Forme rolos de 8 cm de comprimento e da grossura de um dedo.','Grelhe sobre brasas vivas 3 a 4 minutos de cada lado, sem os esmagar.','Abra o pão e recheie com dez ćevapi, cebola crua fatiada e uma colher de kajmak.']::text[]),
('cepelinai','pt','Cepelinai','Vílnius, Lituânia','Bolinhos de batata ralada recheados com carne, cuja forma alongada lhes valeu o nome de «zepelins» nos anos 20. O molho de toucinho e natas ácidas não se discute.',ARRAY['Rale finamente três quartos das batatas cruas e esprema-as num pano para extrair o sumo.','Deixe o sumo decantar, recupere o amido do fundo e junte-o à polpa, com o quarto restante cozido e esmagado.','Tempere a carne picada com uma cebola alourada, manjerona, sal e pimenta.','Forme bolas na palma húmida, recheie-as e feche em fuso.','Escalfe 25 minutos em água salgada a fremir e cubra com toucinho derretido e natas ácidas.']::text[]),
('shakshuka','pt','Shakshuka','Telavive, Israel','Trazida do Norte de África pelos judeus tunisinos e líbios, esta frigideira de tomate e pimento com ovos partidos tornou-se o pequeno-almoço tardio de todo o Levante. O pão substitui os talheres.',ARRAY['Aloure a cebola e os pimentos em tiras 15 minutos em azeite.','Junte alho, cominho, pimentão e harissa e aqueça 1 minuto para libertar os aromas.','Deite o tomate picado e reduza 15 minutos até obter um molho espesso.','Abra covas com a colher, parta lá os ovos e tempere as gemas.','Tape e coza 6 a 8 minutos: claras presas, gemas moles; polvilhe com feta e coentros.']::text[]),
('romazava','pt','Romazava','Antananarivo, Madagáscar','O prato nacional malgaxe: um caldo de carnes variadas onde se desfazem as brèdes mafana, folhas que deixam um ligeiro formigueiro anestesiante na língua. Serve-se com arroz, de manhã e à noite.',ARRAY['Aloure as carnes em cubos grandes no óleo com a cebola, o alho e o gengibre ralado.','Junte os tomates picados e deixe-os desfazer 10 minutos.','Cubra com água e coza 1 hora, até a carne estar tenra.','Junte as brèdes lavadas e os espinafres e cozinhe mais 10 minutos, destapado.','Acerte os temperos e sirva o caldo e as carnes sobre arroz branco bem quente.']::text[]),
('waakye','pt','Waakye','Acra, Gana','Arroz e feijão cozidos com folhas de sorgo vermelho, que dão ao prato a sua cor castanha inconfundível. Vendido de madrugada em folhas, acompanha-se com tudo o que o vendedor tiver.',ARRAY['Demolhe o feijão de um dia para o outro e coza-o 40 minutos com as folhas de sorgo e o bicarbonato.','Retire as folhas: o caldo deve ficar castanho-avermelhado intenso.','Junte o arroz lavado a esse caldo, tempere, tape e coza 20 minutos em lume brando.','Prepare o shito: malaguetas, cebola e tomate triturados e fritos demoradamente em óleo.','Sirva com ovos cozidos, gari, banana-pão frita e uma concha de molho.']::text[]),
('mofongo','pt','Mofongo','San Juan, Porto Rico','Descendente direto do fufu da África Ocidental, adaptado à banana-pão: os pedaços fritos são pisados num pilão de madeira com alho, sal e gordura de porco. Serve-se em cúpula, muitas vezes recheada com marisco.',ARRAY['Descasque as bananas-pão verdes e corte-as em troços de 3 cm.','Frite-as 6 minutos a 175 °C: tenras por dentro mas sem alourar.','Pise o alho com o sal e o azeite num almofariz de madeira.','Esmague os troços quentes com essa pasta e os torresmos, juntando um pouco de caldo.','Calque a mistura numa taça, desenforme em cúpula e sirva com sumo de lima.']::text[]),
('chivito','pt','Chivito','Montevideu, Uruguai','Nascido de um mal-entendido em 1946: uma cliente argentina pediu cabrito, o cozinheiro não tinha e improvisou com lombo de vaca. A sanduíche daí resultante é hoje o prato nacional uruguaio.',ARRAY['Espalme as fatias de lombo a 1 cm e tempere-as no último momento.','Grelhe o bacon até estalar e depois os bifes 1 minuto de cada lado em chapa a escaldar.','Coloque o queijo sobre a carne ainda no lume para derreter apenas ligeiramente.','Estrele os ovos e torre os pães barrados com manteiga.','Monte: maionese, alface, tomate, bife com queijo, fiambre, bacon, ovo e azeitonas; feche e sirva com batata frita.']::text[]),
('carbonara','pt','Carbonara','Roma, Itália','Numa carbonara autêntica nunca entram natas: apenas guanciale, pecorino, gemas e pimenta preta. O molho liga fora do lume, só com o calor da massa, num gesto que não perdoa hesitações.',ARRAY['Corte o guanciale em tiras e frite-o a seco até libertar gordura e ficar estaladiço.','Bata as gemas, o ovo inteiro, o pecorino ralado e muita pimenta moída.','Coza o esparguete 1 minuto a menos do indicado, bem al dente.','Fora do lume, misture a massa com o guanciale e um pouco de água da cozedura.','Deite o creme de ovos mexendo depressa e sem parar, para ficar cremoso sem talhar.']::text[]),
('ossobuco-milanese','pt','Ossobuco à milanesa','Milão, Itália','Um chambão de vitela estufado até o tutano se soltar sozinho, servido com gremolata — casca de limão, alho e salsa — que desperta a riqueza do prato com um toque de frescura.',ARRAY['Polvilhe os chambões atados com farinha e aloure-os de todos os lados em manteiga.','Reserve e aloure cebola, cenoura e aipo na mesma panela.','Devolva a carne, refresque com vinho branco, junte tomate, caldo e louro.','Tape e coza 2 horas em lume muito brando, virando uma vez.','Pique casca de limão, alho e salsa para a gremolata e polvilhe cada prato ao servir.']::text[]),
('trofie-al-pesto','pt','Trofie ao pesto genovês','Génova, Itália','O manjericão de Prà, cultivado nas encostas sobre o mar, esmagado em almofariz com pinhões e parmesão para a folha nunca aquecer. Juntam-se sempre feijão-verde e batata, cozidos na água da massa.',ARRAY['Pise manjericão, alho e uma pitada de sal grosso em almofariz até obter uma pasta fina.','Junte os pinhões e depois os queijos ralados, continuando a pisar com suavidade.','Incorpore o azeite em fio, sem nunca bater, para manter o verde vivo.','Enrole as trofie à mão com farinha e água, torcendo cada pedacinho.','Coza massa, batata em cubos e feijão juntos, escorra e envolva no pesto fora do lume.']::text[]),
('ribollita','pt','Ribollita','Florença, Itália','«Refervida»: uma sopa camponesa de feijão cannellini, couve-negra toscana e pão duro, melhor no dia seguinte, reaquecida em frigideira até se formar crosta no fundo.',ARRAY['Coza o feijão demolhado 1 hora e triture metade para engrossar o caldo.','Aloure cebola, cenoura e aipo em azeite 15 minutos.','Junte couve-negra, couve branca e tomate, molhe com o caldo de feijão e coza 30 minutos.','Envolva o restante feijão e fatias de pão duro, deixe inchar 15 minutos.','Reaqueça no dia seguinte em frigideira com um fio de azeite, até formar crosta dourada.']::text[]),
('orecchiette-cime-rapa','pt','Orecchiette alle cime di rapa','Bari, Itália','Uma massa pequena em forma de orelha, escavada com o polegar, que retém o molho na sua cova. Os grelos, ligeiramente amargos, apuram-se com anchova e malagueta até quase desaparecerem no molho.',ARRAY['Amasse sêmola, farinha e água até uma massa firme, repouse 30 minutos.','Enrole cordões finos, corte discos pequenos e escave cada um com o polegar na bancada.','Derreta o alho e as anchovas no azeite até se desfazerem, junte a malagueta.','Coza as orecchiette com os grelos na mesma água a ferver, 10 minutos.','Escorra massa e legumes juntos e salteie na frigideira com o alho e a anchova.']::text[]),
('arancini','pt','Arancini','Palermo, Itália','Bolas de arroz com açafrão, panadas e fritas, cujo nome recorda a laranja pequena que imitam. Originalmente um prato de festa árabe-normando, recheado com carne, ervilhas e mozarela derretida.',ARRAY['Coza o arroz com açafrão como um risoto sem mexer sem parar, deixe arrefecer por completo.','Prepare um pequeno ragù de carne picada, tomate, cebola e ervilhas, bem reduzido.','Forme uma bola oca de arroz na palma, recheie com ragù e um cubo de mozarela, feche.','Passe cada bola por farinha, ovo batido e pão ralado.','Frite a 170 °C até dourar e ficar estaladiço; escorra e sirva quente.']::text[]),
('tortellini-in-brodo','pt','Tortellini in brodo','Bolonha, Itália','Uma massa minúscula recheada com porco, mortadela e parmesão, dobrada em forma de umbigo — a lenda local conta que nasceu de um estalajadeiro que espreitou o de uma deusa pelo buraco da fechadura.',ARRAY['Prepare um caldo com vaca, frango, cenoura, aipo e cebola, coza 3 horas escumando.','Amasse farinha e ovos até uma massa lisa, repouse 30 minutos sob um pano.','Pique bem fino porco assado, mortadela e presunto, ligue com parmesão, ovo e noz-moscada.','Estenda a massa muito fina, corte quadrados de 4 cm, recheie e dobre em triângulo e depois em umbigo à volta do dedo.','Escalfe os tortellini 3 minutos diretamente no caldo coado a ferver e sirva de imediato.']::text[]),
('brasato-barolo','pt','Brasato al Barolo','Alba, Itália','Um assado de vaca marinado uma noite inteira numa garrafa inteira de Barolo, depois estufado até o vinho, reduzido e triturado, se tornar um molho quase negro. A polenta cremosa é a sua única escolta legítima.',ARRAY['Marine o assado atado a noite toda no vinho com legumes e especiarias.','Escorra a carne, seque-a e aloure-a de todos os lados em manteiga.','Junte os legumes da marinada e depois o vinho coado; tape e estufe 3 horas em lume muito brando.','Retire a carne, triture o molho até ficar liso e napante, acerte o sal.','Corte o assado, nape com o molho e sirva com uma polenta cremosa cozida em caldo.']::text[]),
('cacio-e-pepe','pt','Cacio e pepe','Roma, Itália','Dois ingredientes, pecorino e pimenta preta, e ainda assim um dos pratos mais difíceis da cozinha italiana: o queijo tem de cremar na água da cozedura sem nunca formar grumos fibrosos.',ARRAY['Toste a pimenta moída a seco 1 minuto para despertar os óleos.','Coza a massa em água pouco salgada, guardando bastante água da cozedura.','Ralhe o pecorino bem fino e dilua-o com um pouco de água morna numa creme lisa.','Escorra a massa bem al dente e misture com a pimenta fora do lume.','Envolva o creme de pecorino mexendo com energia, ajustando a água até à textura sedosa desejada.']::text[]),
('focaccia-di-recco','pt','Focaccia di Recco','Recco, Itália','Nada a ver com a focaccia fofa: aqui duas folhas de massa, esticadas quase transparentes, encerram o crescenza, um queijo fresco que derrete em bolsa cremosa em forno muito quente.',ARRAY['Amasse farinha, água, azeite e sal numa massa macia, repouse 1 hora sob um pano untado.','Divida em dois e estique cada pedaço à mão sobre superfície enfarinhada, quase transparente.','Distribua noz de crescenza sobre a primeira folha.','Cubra com a segunda folha, sele as bordas e faça alguns furos para o vapor sair.','Leve ao forno 10 a 12 minutos a 250 °C até aparecerem grandes manchas douradas.']::text[]),
('sarde-in-saor','pt','Sarde in saor','Veneza, Itália','Inventada para os marinheiros vênetos levarem peixe que se conservasse no mar: sardinhas fritas marinadas sob camadas de cebola doce em vinagre, com passas e pinhões. Melhor após dois dias de repouso.',ARRAY['Limpe e escame as sardinhas, polvilhe com farinha e frite até dourar.','Corte as cebolas em juliana fina e aloure-as devagar em óleo até ficarem translúcidas.','Refresque com vinagre, junte o louro e deixe reduzir ligeiramente.','Demolhe as passas em um pouco de água morna e escorra.','Alterne em camadas sardinhas, cebola, passas e pinhões numa travessa; tape e marine 2 dias no frio antes de servir à temperatura ambiente.']::text[]),
('pizza-margherita','pt','Pizza margherita','Nápoles, Itália','Uma massa levedada três vezes, esticada à mão sem nunca tocar num rolo, cozida noventa segundos num forno a lenha a 450 °C. Tomate, mozarela e manjericão recordam, dizem, as cores da bandeira italiana.',ARRAY['Amasse farinha, água, fermento e sal 10 minutos até uma massa lisa e elástica.','Deixe levedar 2 horas à temperatura ambiente, divida em bolas e deixe levedar mais 4 horas.','Estique cada bola à mão num disco fino, mantendo uma borda grossa.','Cubra com tomate triturado, mozarela escorrida em pedaços, um fio de azeite e sal.','Leve ao forno mais quente possível até a borda ficar inchada e tostada em manchas, junte manjericão fresco ao sair.']::text[]),
('tortilla-espanola','pt','Tortilha espanhola','Madrid, Espanha','Nada mais do que batata confitada em azeite, cebola e ovos — e ainda assim dois campos irreconciliáveis: com ou sem cebola. O verdadeiro debate é sobre o centro, que tem de ficar mole.',ARRAY['Corte as batatas em lâminas finas e confite-as 20 minutos em azeite em lume brando com a cebola.','Escorra reservando o azeite e esmague ligeiramente algumas lâminas.','Bata os ovos, tempere e envolva com as batatas ainda mornas; repouse 10 minutos.','Deite numa frigideira com um pouco de azeite reservado, coza 3 minutos em lume forte e 2 tapado em lume brando.','Vire a tortilha com um prato e coza mais 2 minutos: o centro deve ficar cremoso.']::text[]),
('fabada-asturiana','pt','Fabada asturiana','Oviedo, Espanha','Um guisado de fabes — grandes feijões brancos das Astúrias — cozido com chouriço, morcela e toucinho fumado, cujo caldo com açafrão deve napar a colher. Nunca se mexe: apenas se abana a panela.',ARRAY['Demolhe as fabes uma noite e comece a cozedura em água fria sem sal.','Junte cebola, alho e louro, leve a fremir muito de leve e escume com frequência.','Junte as carnes inteiras e coza 2 horas em lume muito brando, abanando a panela de vez em quando.','Retire um pouco de caldo quente para infundir o açafrão e devolva-o à panela.','Repouse 20 minutos fora do lume antes de servir, com as carnes fatiadas sobre o guisado.']::text[]),
('pulpo-a-la-gallega','pt','Polvo à galega','Santiago de Compostela, Espanha','Servido em tábua de madeira, cortado à tesoura e polvilhado com pimentão fumado e sal grosso. O segredo das pulpeiras: mergulhar o polvo três vezes em água a ferver antes de o cozer, para nunca endurecer.',ARRAY['Leve a ferver bastante água sem sal.','Segure o polvo pela cabeça e assuste-o três vezes uns segundos na água a ferver antes de o submergir por completo.','Coza 40 a 50 minutos conforme o tamanho, até um garfo entrar sem resistência.','Coza as batatas na mesma água e corte-as grossas sobre a tábua.','Corte o polvo à tesoura em rodelas, disponha sobre as batatas, regue com azeite e polvilhe os dois pimentões e sal grosso.']::text[]),
('cochinillo-segoviano','pt','Leitão de Segóvia','Segóvia, Espanha','Um leitão de três semanas, assado em forno de lenha até a pele estalar como vidro. Segundo a tradição dos mesones de Segóvia, corta-se simbolicamente com a borda de um prato, nunca com faca.',ARRAY['Esfregue o leitão inteiro com banha e sal, por dentro e por fora.','Coloque-o sobre uma cama de louro e alho em travessa de barro, junte água e vinho.','Asse 1h30 a 160 °C, com a pele para baixo, regando com o suco regularmente.','Vire com cuidado, pele para cima, e continue 30 minutos a 220 °C até estalar.','Repouse 10 minutos e corte com um prato, pressionando o lombo para ouvir a pele estalar.']::text[]),
('cocido-madrileno','pt','Cozido madrileno','Madrid, Espanha','Um cozido de grão-de-bico servido em três «vuelcos» sucessivos: primeiro a sopa de aletria, depois os legumes, por fim as carnes. Um almoço de inverno que ocupa toda uma tarde de domingo.',ARRAY['Demolhe o grão de véspera em água salgada, atado numa gaze para não se partir.','Comece vaca, frango, osso com tutano e toucinho em água fria, escume e junte o grão.','Coza 2 horas, juntando chouriço, cenoura e batata 40 minutos antes do fim.','Coza a couve à parte e salteie-a com alho.','Sirva primeiro o caldo com aletria, depois os legumes e o grão, por fim as carnes fatiadas.']::text[]),
('pisto-manchego','pt','Pisto manchego','Toledo, Espanha','A ratatouille de La Mancha, cozinhada devagar até uma textura quase confitada em vez de crocante. Serve-se tradicionalmente coroada com um ovo frito, para a gema se misturar com os legumes.',ARRAY['Aloure cebola, pimentos e alho em azeite 15 minutos em lume brando.','Junte a curgete em cubos e continue 10 minutos.','Envolva os tomates pelados e picados, o açúcar e o sal.','Coza destapado 25 minutos, mexendo pouco, até ficar confitado.','Sirva quente, cada prato coroado com um ovo estrelado de gema mole.']::text[]),
('migas-extremenas','pt','Migas extremenhas','Cáceres, Espanha','O pão duro dos pastores da Estremadura, esfarelado, humedecido de véspera e depois salteado em gordura de porco até virar pequenas pérolas douradas e secas. Acompanha-se com uvas ou chouriço, conforme o dia.',ARRAY['Esfarele o pão duro bem fino, humedeça com água salgada e cubra com um pano húmido a noite toda.','Frite a entremeada em cubos e o chouriço em banha, reserve.','Aloure os alhos inteiros com casca na mesma gordura, junte o pimentão fora do lume.','Junte o pão esfarelado e salteie em lume forte 15 minutos mexendo sempre com espátula para secar bem.','Devolva as carnes e os alhos, sirva a escaldar com um cacho de uvas frescas.']::text[]),
('calcots-romesco','pt','Calçots com romesco','Valls, Espanha','Grandes cebolas doces catalãs, grelhadas em sarmentos até enegrecerem por completo, descascadas com os dedos e molhadas em romesco. A calçotada come-se ao ar livre, com babete ao pescoço.',ARRAY['Grelhe os calçots inteiros sobre brasas vivas até a pele enegrecer por completo.','Envolva-os em papel de jornal 10 minutos para acabarem de cozer em vapor próprio.','Triture pimentos assados, tomate, amêndoas, avelãs, alho, ñoras hidratadas e pão frito numa pasta.','Monte com azeite como uma maionese, tempere com vinagre e sal.','Descasque os calçots com os dedos puxando a pele enegrecida e molhe na romesco.']::text[]),
('marmitako','pt','Marmitako','San Sebastián, Espanha','O guisado que os pescadores bascos preparavam a bordo, com o atum acabado de pescar e as provisões do barco: batatas partidas à mão para libertar o amido e engrossar o caldo sem farinha.',ARRAY['Aloure cebola, pimentos e alho em azeite 15 minutos.','Junte o tomate picado e o pimentão fora do lume, deixe apurar 10 minutos.','Parta as batatas com a ponta da faca em vez de as cortar, para libertarem o amido.','Junte-as com o vinho e o caldo, coza 20 minutos tapado até o caldo engrossar.','Junte o atum em cubos grandes, apague o lume e deixe escalfar 5 minutos no calor residual.']::text[]),
('salmorejo-cordobes','pt','Salmorejo de Córdova','Córdova, Espanha','Mais espesso e rico do que o seu primo gaspacho: muito mais pão, muito mais azeite, triturado até ficar liso como um creme. Serve-se frio, coroado com ovo cozido e presunto serrano.',ARRAY['Triture os tomates crus com o alho até um sumo homogéneo.','Junte o pão duro esfarelado e deixe absorver o sumo 10 minutos.','Triture demoradamente, pelo menos 5 minutos, deitando o azeite em fio.','Junte o vinagre de Jerez e o sal, triture de novo até uma textura perfeitamente lisa.','Leve ao frio 2 horas e sirva bem frio, coroado com ovo cozido esmigalhado e presunto serrano em cubos.']::text[]),
('empanada-gallega','pt','Empada galega','Vigo, Espanha','Uma grande empada de massa fermentada, recheada com uma compota de atum ou bacalhau e pimentos, cozinhados devagar até ficarem quase doces. Come-se fria, cortada em quadrados, do cesto de piquenique.',ARRAY['Amasse farinha, fermento, azeite, água e sal numa massa macia, deixe levedar 1h30.','Aloure cebolas e pimentos muito devagar em azeite, pelo menos 45 minutos, até caramelizarem.','Junte tomate e pimentão, cozinhe mais 15 minutos e envolva o atum escorrido.','Estenda metade da massa, recheie, cubra com o resto e sele as bordas enrolando-as.','Pincele com ovo batido e leve ao forno 30 a 35 minutos a 200 °C até dourar bem por cima.']::text[]),
('churros-con-chocolate','pt','Churros com chocolate','Madrid, Espanha','Uma massa frita em longos bastões acanalados, estaladiços por fora e macios por dentro, molhados num chocolate espesso como um creme inglês feliz falhado. O pequeno-almoço da manhã seguinte à festa.',ARRAY['Leve a água salgada a ferver, deite a farinha de uma vez e trabalhe com energia fora do lume até a massa se despegar.','Deixe amornar 5 minutos e encha um saco com bico canelado.','Frite bastões longos a 180 °C, cortando-os à tesoura sobre o óleo, até dourar.','Escorra e role em açúcar ainda quente.','Derreta o chocolate no leite com o amido, mexendo até engrossar, e sirva a escaldar para molhar.']::text[]),
('baklava','pt','Baklava','Gaziantep, Turquia','Quarenta folhas de massa filo, cada uma pincelada com manteiga derretida, empilhadas sobre pistácios triturados e regadas com uma calda quente deitada sobre a massa fria, para ficar estaladiça.',ARRAY['Pique os pistácios grosseiramente à faca, não na varinha, para manter o crocante.','Unte uma travessa, empilhe oito folhas de filo untando cada uma, e espalhe metade dos pistácios.','Repita com mais oito folhas, o resto dos pistácios, e termine com oito últimas folhas untadas.','Corte em losangos antes de assar e leve ao forno 35 minutos a 180 °C até dourar por cima.','Prepare uma calda de açúcar, água, limão e mel, e deite-a quente sobre o baklava frio; repouse 4 horas.']::text[]),
('mochi-daifuku','pt','Mochi daifuku','Quioto, Japão','Uma massa de arroz glutinoso, cozida a vapor e depois pisada até ficar elástica, envolvendo uma bola de pasta de feijão vermelho doce. Trabalha-se com as mãos húmidas de amido, ou tudo cola.',ARRAY['Enrole a pasta de feijão vermelho em doze bolinhas e leve ao frio.','Misture farinha de arroz glutinoso, açúcar e água, coza a vapor 8 minutos mexendo a meio.','Vire a massa cozida, ainda a escaldar, sobre uma superfície muito polvilhada de amido.','Divida em doze partes com as mãos húmidas e polvilhadas de amido, sem deixar arrefecer.','Achate cada parte, encerre uma bola de pasta de feijão e feche apertando para selar.']::text[]),
('schwarzwaelder-kirschtorte','pt','Bolo Floresta Negra','Triberg, Alemanha','Camadas de pão de ló de chocolate embebidas em kirsch, montadas com natas batidas e ginjas, tudo coberto de raspas de chocolate negro. O nome viria do traje tradicional preto, branco e vermelho da região.',ARRAY['Prepare um pão de ló de chocolate, coza e deixe arrefecer antes de cortar em três discos.','Cozinhe as ginjas com um pouco de açúcar, escorra-as reservando o suco.','Embeba cada disco com o suco de ginja misturado com kirsch.','Bata as natas com açúcar em pó, sobrepondo discos, natas e ginjas.','Cubra por completo com natas, decore com raspas de chocolate negro e ginjas inteiras.']::text[]),
('sachertorte','pt','Sachertorte','Viena, Áustria','Inventada em 1832 por um aprendiz de dezasseis anos para um príncipe descontente com a sobremesa, este pão de ló de chocolate é cortado, recheado com doce de alperce e coberto com uma cobertura tão lisa que deve refletir a luz.',ARRAY['Derreta o chocolate, misture com a manteiga em pomada e metade do açúcar.','Incorpore as gemas uma a uma e depois a farinha peneirada.','Bata as claras com o restante açúcar em picos firmes e envolva com suavidade.','Leve ao forno 45 minutos a 170 °C, arrefeça, corte o bolo e cubra com doce de alperce quente, também por cima.','Prepare uma cobertura de açúcar em pó e água aquecida com chocolate, deite de uma vez e alise sem repassar.']::text[]),
('tres-leches','pt','Bolo três leites','León, Nicarágua','Um pão de ló propositadamente seco e poroso, picado por todo o lado, para absorver sem se desfazer uma mistura de leite gordo, condensado e evaporado. Serve-se gelado, com um merengue leve ou natas batidas.',ARRAY['Separe os ovos, bata as claras em picos firmes com metade do açúcar.','Envolva as gemas e o restante açúcar, depois a farinha e o fermento peneirados, com movimentos suaves.','Leve ao forno 25 minutos a 180 °C em forma retangular, arrefeça e pique toda a superfície com um garfo.','Misture os três leites e deite-os devagar sobre o bolo frio, por etapas, até absorção completa.','Leve ao frio 3 horas, cubra com natas batidas e polvilhe canela antes de servir.']::text[]),
('gulab-jamun','pt','Gulab jamun','Agra, Índia','Pequenas bolas de leite em pó fritas devagar em lume brando até um castanho profundo, depois mergulhadas numa calda de cardamomo e água de rosas. Duplicam de tamanho ao embeber, sem nunca se desfazerem.',ARRAY['Misture leite em pó, farinha e fermento, envolva o ghee e leite suficiente para uma massa macia sem amassar.','Enrole bolas perfeitamente lisas, sem fendas, do tamanho de uma noz.','Frite em lume brando e constante, girando o óleo, até um castanho profundo e uniforme, 10 minutos.','Prepare uma calda de açúcar, água e cardamomo, apenas fervida, perfumada com água de rosas.','Mergulhe as bolas quentes na calda morna e deixe inchar pelo menos 2 horas antes de servir.']::text[])
insert into public.atlas_dish_texts (dish_id,lang,name,place,description,steps) values
('basbousa','pt','Basbousa','Alexandria, Egito','Um bolo de sêmola e iogurte, cortado em losangos antes mesmo de ir ao forno, cada peça coroada com uma amêndoa. A calda fria deitada sobre o bolo a escaldar cria esse contraste húmido perfumado a flor de laranjeira.',ARRAY['Misture sêmola, iogurte, açúcar, manteiga derretida e fermento numa massa homogénea.','Espalhe numa travessa untada, corte em losangos de imediato e ponha uma amêndoa em cada um.','Leve ao forno 30 minutos a 180 °C até dourar por cima.','Prepare uma calda de açúcar, água, limão e água de flor de laranjeira, deixe arrefecer por completo.','Deite a calda fria sobre o bolo acabado de sair do forno e deixe absorver antes de servir.']::text[]),
('stroopwafel','pt','Stroopwafel','Gouda, Países Baixos','Duas finas bolachas cozidas em ferro, partidas ainda quentes e recheadas com uma calda espessa de açúcar mascavado. Coloca-se sobre uma chávena de café quente para o vapor amolecer só a calda.',ARRAY['Amasse farinha, fermento, manteiga derretida, ovo e leite numa massa macia, deixe levedar 1 hora.','Forme bolas e coza 2 minutos numa máquina de waffles redonda muito quente, de desenho pouco fundo.','Ainda quentes, parta cada waffle em dois discos finos com uma faca.','Misture açúcar mascavado, manteiga, xarope e canela aquecidos até textura de calda.','Barre um disco com a calda quente e feche logo com o outro, pressionando as bordas.']::text[]),
('gaufres-liege','pt','Waffle de Liège','Liège, Bélgica','Uma massa tipo brioche, levedada duas vezes, onde se enterra açúcar em pérolas que não derrete mas carameliza em pequenos bolsos crocantes contra o ferro quente. Come-se simples, à mão, na rua.',ARRAY['Amasse farinha, fermento, ovos, leite e sal numa massa macia, deixe levedar 1 hora.','Incorpore a manteiga em pomada aos poucos, amassando, até ser absorvida.','Deixe levedar uma segunda vez 30 minutos, depois enterre o açúcar em pérolas sem o derreter.','Forme porções ovais e deixe repousar 15 minutos.','Coza 3 minutos por waffle em ferro bem quente, até o açúcar caramelizar à superfície.']::text[]),
('pastel-de-nata-macaense','pt','Pastel de nata macaense','Macau, China','Descendente direta do pastel de nata português, adaptado por um pasteleiro britânico nos anos 90: o topo não fica malhado de preto mas queimado em largas placas de caramelo, à maneira de um crème brûlée.',ARRAY['Enrole a massa folhada num rolo apertado, corte discos e espalme-os com o polegar nas formas.','Aqueça natas, leite e açúcar sem ferver, deixe amornar.','Bata as gemas com o leite condensado, deite a mistura morna em fio e coe.','Encha as formas de massa três quartos.','Leve ao forno 15 minutos a 250 °C até aparecerem largas placas caramelizadas, quase queimadas.']::text[]),
('sangria','pt','Sangria','Barcelona, Espanha','Um vinho tinto jovem onde macera fruta de verão durante horas, alongado no último momento com um jato de soda para manter as bolhas. A regra de ouro: nunca usar um vinho que não se beberia sozinho.',ARRAY['Corte laranjas, limão e maçã em gomos finos, sem descascar.','Misture com o vinho, o açúcar, a canela e a aguardente numa jarra grande.','Tape e deixe macerar no frigorífico pelo menos 4 horas, idealmente uma noite.','Retire o pau de canela e prove para ajustar o açúcar.','Junte a soda e gelo mesmo antes de servir, para conservar as bolhas.']::text[]),
('caipirinha','pt','Caipirinha','Paraty, Brasil','A lima inteira, cortada em gomos e macerada com açúcar para libertar os óleos amargos da casca, é a verdadeira assinatura desta aguardente de cana. Serve-se sempre macerada no próprio copo, nunca coada.',ARRAY['Lave a lima e corte-a em oito gomos, retirando as pontas brancas amargas.','Coloque os gomos e o açúcar no fundo do copo.','Macere com energia 30 segundos, até o açúcar absorver o sumo e os óleos.','Encha o copo com gelo picado.','Deite a cachaça e mexa bem com uma colher para distribuir o açúcar.']::text[]),
('mojito','pt','Mojito','Havana, Cuba','A hortelã bate-se suavemente entre as palmas em vez de se macerar, para libertar o aroma sem trazer o amargor verde. É a bebida atribuída, talvez depressa demais, a certo escritor de Havana Velha.',ARRAY['Bata as folhas de hortelã entre as palmas para as despertar, sem as esmagar.','Corte a lima em gomos, macere levemente com o açúcar no fundo do copo.','Junte a hortelã e macere apenas um pouco, só para a marcar.','Encha com gelo picado, deite o rum branco e mexa.','Complete com água com gás, mexa uma última vez e decore com um raminho de hortelã.']::text[]),
('horchata-mexicana','pt','Horchata mexicana','Puebla, México','Arroz demolhado a noite toda e depois triturado com canela e baunilha, coado fino para ficar só com o leite branco e perfumado. Uma bebida sem lacticínios nem álcool, vendida gelada em grandes jarras de vidro.',ARRAY['Demolhe o arroz com o pau de canela na água a noite toda à temperatura ambiente.','Triture demoradamente arroz, água de demolha e baunilha até um líquido bem branco.','Coe num pano fino, espremendo bem para extrair todo o leite de arroz.','Adoce e alongue com o leite, prove e ajuste a textura com um pouco de água.','Leve ao frio pelo menos 2 horas e sirva bem gelado, polvilhado com canela.']::text[]),
('gluehwein','pt','Vinho quente','Nuremberga, Alemanha','O vinho tinto dos mercados de Natal alemães, aquecido sem nunca ferver com canela, cravinho e casca de laranja. Fervê-lo eliminaria o álcool, é certo, mas também todo o seu aroma.',ARRAY['Retire a casca da laranja em tiras largas, evitando a parte branca amarga.','Deite o vinho numa panela com a casca, canela, cravinho, anis-estrelado e açúcar.','Aqueça muito devagar 15 minutos, sem nunca deixar fremir ou ferver.','Prove e ajuste o açúcar conforme o vinho usado.','Coe as especiarias e sirva a escaldar em copos resistentes ao calor, com um pau de canela.']::text[]),
('chai-masala','pt','Chá masala','Bombaim, Índia','Um chá preto fervido com gengibre, cardamomo, canela e cravinho, depois batido com leite para levantar uma espuma leve. Cada família indiana guarda o seu próprio equilíbrio de especiarias, com ciúme.',ARRAY['Esmague grosseiramente gengibre, cardamomo, canela, cravinho e pimenta num almofariz.','Leve a água a ferver com essas especiarias, infunda forte 5 minutos tapado.','Junte o chá preto, ferva 2 minutos.','Deite o leite e o açúcar, volte a ferver três vezes vigiando para não transbordar.','Coe batendo com energia para levantar espuma, e sirva bem quente.']::text[]),
('sauerbraten','pt','Sauerbraten','Colônia, Alemanha','Um assado marinado até cinco dias em vinagre, vinho tinto e especiarias, para amaciar uma peça outrora demasiado dura para assar tal e qual. O molho liga-se tradicionalmente com migalhas de pão de especiarias, que lhe dão a cor quase negra.',ARRAY['Marine o assado 3 a 5 dias no frio em vinagre, vinho, água, legumes em rodelas e especiarias, virando-o todos os dias.','Escorra a carne reservando a marinada, seque-a e aloure-a de todos os lados em manteiga.','Junte os legumes da marinada, molhe com o líquido coado e estufe 2h30 tapado em lume brando.','Retire a carne, triture o molho com as migalhas de pão de especiarias até engrossar.','Junte as passas, acerte o agridoce com açúcar, corte o assado e nape com molho quente.']::text[]),
('currywurst','pt','Currywurst','Berlim, Alemanha','Nascida em 1949 de uma troca de uma berlinense com soldados britânicos por curry em pó e ketchup, esta salsicha grelhada cortada em rodelas e regada com molho de tomate picante tornou-se o emblema de rua de Berlim, comida de pé, sem talheres.',ARRAY['Refogue a cebola em rodelas no óleo até ficar translúcida.','Junte tomate, ketchup, açúcar, vinagre e colorau, cozinhe 15 minutos até um molho espesso.','Grelhe as salsichas em frigideira ou churrasqueira até a pele estalar e dourar.','Corte-as em rodelas grossas num prato ou tabuleiro de cartão.','Regue generosamente com molho quente e polvilhe mais curry em pó antes de servir com batatas fritas.']::text[]),
('stamppot','pt','Stamppot','Amesterdão, Países Baixos','«Puré compacto»: batatas esmagadas com couve-galega ou endívia, servidas com salsicha fumada e um poço de suco de cozedura ao centro. Um prato de inverno simples, feito para aquecer sem nunca cansar.',ARRAY['Descasque e corte as batatas, coza em água salgada 20 minutos.','Junte a couve-galega picada à água das batatas 5 minutos antes do fim.','Escalfe a salsicha fumada à parte em água mal fervendo 15 minutos.','Escorra batatas e couve, esmague com manteiga, leite e noz-moscada.','Sirva o puré com um poço ao centro, com mostarda e fatias de salsicha fumada quente.']::text[]),
('moules-frites','pt','Mexilhões com batatas fritas','Bruxelas, Bélgica','Mexilhões abertos em minutos a vapor de vinho branco, aipo e chalota, servidos na própria panela com batatas fritas duas vezes — a verdadeira fritura belga, nunca ao contrário.',ARRAY['Raspe e desbarbe os mexilhões, descarte os que fiquem abertos.','Refogue chalota e aipo em rodelas na manteiga, molhe com vinho branco.','Deite os mexilhões no líquido a ferver, tape e agite a panela 5 minutos até abrirem todos.','Corte as batatas em bastonetes, frite uma primeira vez a 150 °C e escorra.','Frite de novo a 190 °C até dourar e ficar estaladiças, sirva com os mexilhões e a salsa picada.']::text[]),
('farikal','pt','Fårikål','Oslo, Noruega','O prato nacional norueguês, escolhido por votação popular em 1972: carneiro e couve branca em camadas numa só panela com grãos de pimenta inteiros e nada mais, cozinhado até a carne se soltar do osso.',ARRAY['Corte o carneiro em pedaços grandes com osso e a couve em gomos largos.','Alterne em camadas carne e couve numa panela grande, salgando e apimentando bem cada camada.','Polvilhe um pouco de farinha entre as camadas para engrossar levemente o molho.','Deite a água, tape e deixe cozinhar em lume muito brando 2h30 sem mexer.','Verifique que a carne se solta com o garfo, sirva com batatas a vapor.']::text[]),
('smorrebrod','pt','Smørrebrød','Copenhaga, Dinamarca','Uma única fatia de pão de centeio escuro, barrada até às bordas e coberta com uma única cobertura — arenque marinado, ovo e camarão, ou rosbife — nunca empilhado, sempre comido com faca e garfo.',ARRAY['Barre cada fatia de pão de centeio até às bordas, sem deixar zonas secas.','Coza os ovos duros 9 minutos, arrefeça e corte em rodelas.','Para a versão de arenque, arranje os filetes marinados sobre a manteiga, polvilhe cebola roxa e endro.','Para a versão de camarão, ligue-os com maionese e forme uma cúpula sobre as rodelas de ovo.','Decore cada sanduíche aberta com rabanete em lâminas e um raminho de endro fresco, sirva de imediato, fresco.']::text[]),
('karjalanpiirakka','pt','Karjalanpiirakka','Carélia, Finlândia','Finas crostas de centeio moldadas em forma de barquinha, recheadas com uma papa de arroz com leite e assadas muito quentes até as bordas empolarem. Servidas com munavoi, manteiga com ovo cozido esmagado, indispensável ao pequeno-almoço.',ARRAY['Coza o arroz no leite em lume muito brando 40 minutos, mexendo com frequência, até uma papa espessa.','Amasse farinha de centeio, farinha, água e sal numa massa firme, repouse 20 minutos.','Estenda a massa muito fina, corte ovais e afine mais as bordas.','Recheie o centro com a papa de arroz, dobre as bordas apertando para formar uma barquinha aberta.','Leve ao forno 15 minutos a 250 °C, pincele com manteiga derretida ao sair e sirva morno com munavoi.']::text[]),
('plokkfiskur','pt','Plokkfiskur','Reiquiavique, Islândia','Um prato nascido para não desperdiçar nada: restos de bacalhau ou arinca escalfados, esmigalhados numa bechamel leve com batatas, servido com pão de centeio escuro tradicionalmente cozido a vapor vulcânico.',ARRAY['Escalfe o bacalhau 8 minutos em água mal fervendo, ligeiramente salgada, escorra e esmigalhe grosseiramente.','Coza as batatas em água, escorra e corte em cubos.','Refogue a cebola em rodelas na manteiga, polvilhe farinha e junte o leite batendo para uma bechamel leve.','Junte o curry, o peixe esmigalhado e as batatas, envolva com suavidade sem esmagar.','Reaqueça devagar 5 minutos sem ferver, sirva com pão de centeio escuro e um pouco de manteiga.']::text[]),
('irish-stew','pt','Guisado irlandês','Dublin, Irlanda','Um guisado de carneiro ou borrego tão simples que tradicionalmente só leva carne, batatas, cebolas e água — nem sequer cenoura na origem, a espessura vem apenas das batatas que se desfazem ao cozinhar.',ARRAY['Corte o borrego em pedaços grandes, descasque batatas, cebolas e cenouras.','Alterne em camadas carne, cebolas, cenouras e metade das batatas numa panela.','Cubra com a água, junte o louro, tape e deixe cozinhar 1h30 em lume muito brando.','Junte o restante das batatas em pedaços grandes e continue a cozinhar 30 minutos, até se desfazerem um pouco e engrossarem o caldo.','Acerte o tempero, polvilhe salsa picada e sirva bem quente em pratos fundos.']::text[]),
('svickova','pt','Svíčková na smetaně','Praga, Chéquia','Um lombo de vaca marinado e depois estufado sobre uma cama de raízes — cenoura, aipo, pastinaga — trituradas numa molho cremoso e ácido, servido com knedlíky, bolinhos de pão, e uma colherada de compota de arando.',ARRAY['Marine a vaca a noite toda com as raízes em rodelas, o vinagre, o louro e as especiarias.','Aloure a carne lardeada com bacon, depois junte os legumes da marinada e estufe 2 horas tapado.','Retire a carne, triture o molho de legumes com as natas até ficar liso e aveludado.','Prepare a massa de knedlíky com farinha, fermento, ovo e leite, forme rolos e escalfe 20 minutos em água a ferver.','Corte a vaca, nape com o molho, sirva com rodelas de knedlíky e uma colherada de compota de arando.']::text[]),
('sarmale','pt','Sarmale','Bucareste, Roménia','Folhas de couve fermentada inteira, enroladas com porco picado, arroz e endro, cozinhadas horas numa panela de barro até a couve ficar macia. Prato indispensável do Natal, ainda melhor reaquecido no dia seguinte.',ARRAY['Desprenda com cuidado as folhas da couve fermentada, apare as nervuras muito grossas.','Misture porco picado, arroz cru, cebola picada e endro picado, tempere com sal e pimenta.','Coloque uma colherada de recheio na borda de cada folha e enrole apertado, dobrando os lados.','Forre o fundo de uma panela com bacon e couve picada, disponha os rolos apertados, cubra com tomate e água até acima.','Deixe cozinhar tapado 2 horas em lume muito brando, juntando água se necessário, até a couve ficar macia.']::text[]),
('banitsa','pt','Banitsa','Sófia, Bulgária','Folhas de massa filo amarrotadas à mão, nunca empilhadas planas, recheadas com uma mistura de queijo branco sirene e ovos batidos. Na véspera de Ano Novo, esconde-se um papelzinho dobrado que prevê a sorte do ano.',ARRAY['Esfarele o queijo sirene e esmague-o com garfo com três ovos batidos.','Unte generosamente cada folha de filo, amarrote-a sem cuidado num monte solto.','Disponha as folhas amarrotadas em círculos numa forma redonda untada, recheando com queijo à medida.','Bata os dois ovos restantes com o iogurte e o bicarbonato, deite por cima.','Leve ao forno 35 minutos a 180 °C até inchar e dourar bem por cima, deixe amornar antes de cortar.']::text[]),
('pasticada','pt','Pašticada','Split, Croácia','Um assado de vaca lardeado com bacon e cenoura, marinado dois dias em vinagre e vinho antes de estufar com ameixas e cravinho até um molho quase doce. Prato de casamento dálmata, nunca cozinhado para um dia comum.',ARRAY['Larde o assado com bastões de bacon e cenoura com uma faca afiada.','Marine-o 2 dias no frio no vinho, no vinagre, na cebola e no cravinho.','Escorra e aloure a carne de todos os lados, depois molhe com a marinada coada e o tomate.','Estufe tapado 3 horas em lume muito brando, juntando as ameixas a meio da cozedura.','Retire a carne, reduza o molho e triture-o com as ameixas, corte o assado e nape generosamente.']::text[]),
('karadjordjeva-snicla','pt','Karađorđeva šnicla','Belgrado, Sérvia','Um escalope de porco achatado e depois enrolado com kajmak, um creme de leite fermentado, antes de ser panado e frito. Criado nos anos 50 para homenagear um herói nacional, em forma de rolo que evoca a medalha que usava.',ARRAY['Achate finos escalopes de porco com maço até 3 mm de espessura.','Ponha uma colherada de kajmak no centro de cada escalope e enrole apertado, fechando as pontas com um palito.','Passe cada rolo por farinha, ovo batido e pão ralado, pressionando bem para aderir.','Repita a panagem uma segunda vez para uma crosta mais grossa e crocante.','Frite a 170 °C até o rolo dourar, deixe repousar um minuto antes de cortar.']::text[]),
('fenkata','pt','Fenkata (coelho maltês)','Valeta, Malta','O coelho, rei da mesa maltesa, primeiro frito com alho e depois cozinhado em vinho tinto até a carne se soltar do osso. Tradicionalmente servido em dois pratos: o molho sobre massa primeiro, a carne depois.',ARRAY['Corte o coelho em pedaços, marine-o 1 hora no vinho com alho esmagado e louro.','Escorra a carne e aloure-a em azeite numa panela grande.','Junte a cebola em rodelas, refogue, depois molhe com a marinada e o tomate.','Tape e cozinhe 1h30 em lume brando até a carne se soltar do osso.','Coza o esparguete, sirva-o primeiro com o molho, depois o coelho como segundo prato, com salsa.']::text[]),
('judd-mat-gaardebounen','pt','Judd mat Gaardebounen','Luxemburgo','O prato nacional luxemburguês: pescoço de porco fumado, dessalgado e depois cozinhado até macio, servido em fatias grossas com favas e um molho roux ligado com o caldo de cozedura.',ARRAY['Dessalgue o pescoço fumado 12 horas em água fria, mudando a água uma vez.','Escalfe-o 2 horas em água fresca com cebola, cenoura e louro, em lume brando.','Debulhe as favas e coza-as à parte com um raminho de segurelha até macias.','Prepare um roux com manteiga e farinha, molhe com um pouco do caldo de cozedura batendo até consistência napante.','Corte a carne, sirva com as favas e nape com o molho quente.']::text[]),
('souvla','pt','Souvla','Nicósia, Chipre','Grandes pedaços de porco ou borrego enfiados num longo espeto e virados à mão sobre as brasas durante horas, num ritual de domingo que reúne toda a família à volta do carvão.',ARRAY['Corte o porco em cubos grandes de 5 cm, marine 2 horas com azeite, sumo de limão, orégãos e louro.','Enfie os cubos num espeto longo, intercalando folhas de louro.','Gire o espeto sobre brasas moderadas 3 a 4 horas, regando com regularidade com a marinada.','Vinte minutos antes do fim, junte fatias de halloumi numa grelha ao lado para tostar.','Sirva a carne retirada do espeto com o halloumi grelhado, limão fresco e pão pita quente.']::text[]),
('potica','pt','Potica','Liubliana, Eslovénia','Uma massa levedada muito fina, esticada sobre um pano limpo e depois enrolada apertada com um recheio de nozes moídas, mel e canela. Existem dezenas de variantes regionais, cada família eslovena guarda a sua.',ARRAY['Amasse farinha, fermento, ovos, leite e manteiga derretida numa massa macia, deixe levedar 1h30.','Estique a massa o mais fina possível sobre um pano enfarinhado grande, quase transparente.','Triture as nozes com o mel, o açúcar, a canela e as passas para o recheio.','Espalhe o recheio sobre toda a massa, enrole apertado com ajuda do pano num rolo longo.','Coloque em coroa numa forma, deixe levedar 30 minutos e leve ao forno 45 minutos a 170 °C.']::text[]),
('bryndzove-halusky','pt','Bryndzové halušky','Bratislava, Eslováquia','O prato nacional eslovaco: pequenos bolinhos de batata crua ralada, escalfados e depois cobertos de bryndza, um queijo de ovelha fermentado e cremoso, coroados com pedacinhos de bacon bem estaladiços.',ARRAY['Ralhe finamente as batatas cruas, escorra ligeiramente sem pressionar demasiado.','Misture com a farinha, o ovo e o sal numa massa espessa e pegajosa.','Deixe cair pequenos bolinhos com colher ou escorredor de furos diretamente em água a ferver salgada.','Escorra os bolinhos assim que subirem à superfície, cerca de 3 minutos.','Esmague o bryndza com um pouco de leite, misture-o quente com os bolinhos, coroe com pedacinhos de bacon estaladiços.']::text[]),
('ghormeh-sabzi','pt','Ghormeh sabzi','Teerã, Irão','Considerado o prato nacional iraniano: uma montanha de ervas frescas — salsa, coentros, feno-grego, cebolinho — longamente refogadas e depois cozinhadas com carne e feijão vermelho, acidificadas com limas negras secas ao sol.',ARRAY['Pique bem fino todas as ervas frescas e refogue-as em óleo 20 minutos até escurecerem e perderem a água.','Aloure a cebola em rodelas e a vaca em cubos com a curcuma numa panela.','Junte as ervas refogadas, o feijão vermelho escorrido e cubra com água.','Fure as limas negras secas e junte-as inteiras, cozinhe 2 horas em lume brando.','Esmague levemente as limas no molho para libertar a acidez, acerte o sal e sirva com arroz.']::text[]),
('masgouf','pt','Masgouf','Bagdá, Iraque','Uma carpa do Tigre aberta pelas costas, esticada em estacas de madeira e grelhada de pé, inclinada para o lume de lenha durante horas. Um prato com mais de dois mil anos, citado em tabuinhas sumérias.',ARRAY['Abra o peixe em borboleta cortando pelas costas sem soltar a barriga, e achate-o.','Pincele o interior com azeite misturado com curcuma, tamarindo e sal.','Fixe o peixe aberto em duas estacas de madeira fincadas no chão, carne virada para o fogo.','Grelhe-o de pé a distância das brasas 45 minutos a 1 hora, regando com regularidade com azeite.','Cubra com tomate, cebola e salsa picados, sirva com gomos de limão.']::text[]),
('kabsa','pt','Kabsa','Riade, Arábia Saudita','Arroz basmati cozido no próprio suco do frango, perfumado com uma mistura de especiarias própria de cada família — cardamomo, canela, cravinho, lomi seco — servido numa enorme travessa comum ao centro da mesa, partilhado diretamente do arroz.',ARRAY['Aloure o frango inteiro ou em pedaços em óleo com a cebola em rodelas.','Junte tomate triturado, cenoura, especiarias inteiras e limas secas furadas, cubra com água e cozinhe 40 minutos.','Retire o frango, coe e reserve o caldo perfumado.','Refogue o arroz basmati enxaguado 2 minutos, molhe com o caldo coado e cozinhe tapado 18 minutos sem levantar a tampa.','Grelhe ou frite o frango uns minutos para dourar a pele, sirva sobre o arroz polvilhado com passas e amêndoas tostadas.']::text[]),
('khorovats','pt','Khorovats','Erevã, Arménia','O churrasco arménio, marinado longamente em vinho ou suco de cebola antes de grelhar sobre brasas de madeira frutífera. O seu sucesso julga-se pelo suco que corre ao cortar a carne, nunca seca.',ARRAY['Corte a carne em cubos grandes, triture duas cebolas em suco e misture com o vinho e o louro.','Marine a carne pelo menos 3 horas, idealmente uma noite inteira no frio.','Enfie os cubos em espetos largos e planos, alternando com o resto da cebola em gomos.','Grelhe sobre brasas moderadas 25 a 30 minutos virando com regularidade, até o suco sair claro.','Grelhe ao mesmo tempo tomates, pimentos e beringelas inteiros, descasque e esmague numa molho grosseiro para acompanhar.']::text[]),
('piti','pt','Piti','Baku, Azerbaijão','Um guisado de borrego e grão-de-bico cozinhado e servido na própria panelinha de barro individual, com açafrão e ameixas. Bebe-se primeiro o caldo, depois esmaga-se a carne com garfo dentro da panela para o segundo prato.',ARRAY['Demolhe o grão-de-bico a noite toda, escorra.','Reparta borrego, grão-de-bico, cebola e tomate em panelinhas individuais de barro.','Cubra com água, tape cada panela e cozinhe 2 horas em forno brando.','Junte batatas, ameixas e açafrão dissolvido nos últimos 30 minutos.','Deite primeiro o caldo numa tigela para beber, depois esmague o resto com garfo na panela e polvilhe sumagre.']::text[]),
('mansaf','pt','Mansaf','Amã, Jordânia','O prato nacional jordano, servido numa enorme travessa comum de pão achatado e arroz, com o borrego inteiro banhado em jameed, um iogurte de ovelha fermentado e seco em bolas duras, reconstituído em molho. Come-se tradicionalmente de pé, só com a mão direita.',ARRAY['Demolhe as bolas de jameed seco várias horas em água morna até amolecer por completo.','Escalfe o borrego com cebola e cardamomo 1h30 até macio, reserve o caldo.','Triture o jameed amolecido com um pouco de caldo até um molho liso, aqueça devagar sem ferver mexendo sem parar.','Coza o arroz no resto do caldo perfumado até macio.','Espalhe o pão achatado numa travessa grande, cubra com arroz e borrego, nape com o molho de jameed e polvilhe com amêndoas e pinhões dourados em manteiga.']::text[]),
('saltah','pt','Saltah','Sanaa, Iémen','Considerado o prato nacional iemenita: um guisado de carne condimentado coroado com houlba, uma espuma de feno-grego batida até ficar firme, servido a borbulhar numa panela de pedra vulcânica escaldante.',ARRAY['Demolhe as sementes de feno-grego 6 horas em água, escorra e triture com um pouco de água fresca até obter uma pasta, bata até espumar e triplicar de volume.','Refogue cebola, alho e carne em cubos até dourar.','Junte tomate triturado, cominho, malagueta e batata em cubos, molhe e cozinhe 30 minutos até um guisado espesso.','Triture um pouco de coentros e malagueta fresca com água para um relish verde picante, à parte.','Deite o guisado a escaldar em tigelas de pedra pré-aquecidas, corone com espuma de feno-grego e um fio do relish verde, sirva com pão achatado.']::text[]),
('nihari','pt','Nihari','Carachi, Paquistão','Um guisado de chambão de vaca cozinhado a noite toda em lume muito brando, nascido nas cozinhas da corte mogol para ser servido ao pequeno-almoço após a oração do amanhecer. A gordura dourada que sobe à superfície, o nihari, é misturada de volta ao molho com uma colherada.',ARRAY['Refogue a cebola em rodelas em ghee até dourar bem, reserve metade para a guarnição.','Junte a pasta de gengibre e alho, o chambão de vaca e as especiarias nihari, aloure a carne de todos os lados.','Cubra generosamente com água, leve a ferver e cozinhe tapado em lume muito brando 5 a 6 horas, até a carne se desfiar facilmente.','Misture a farinha com um pouco de água fria, incorpore ao guisado batendo para engrossar levemente o molho.','Sirva a escaldar, com cebola frita, gengibre em juliana, malagueta fresca, coentros e gomos de limão.']::text[]),
('beshbarmak','pt','Beshbarmak','Almaty, Cazaquistão','«Cinco dedos»: o prato das estepes comido tradicionalmente sem talheres, massa larga e plana coberta com carne de cavalo ou carneiro fervida e desfiada, com o caldo bebido à parte numa tigela chamada sorpa.',ARRAY['Escalfe o carneiro com uma cebola, o louro e a pimenta 2 horas em lume brando, até macio.','Amasse farinha, ovo, água e sal numa massa firme, repouse 30 minutos.','Estenda a massa fina e corte grandes losangos irregulares.','Escalfe os losangos de massa uns minutos no caldo de carne coado, escorra.','Corte o resto das cebolas em rodelas e amoleça-as em um pouco de caldo, sirva a massa coberta de cebola e carne desfiada, o caldo à parte com endro.']::text[]),
('ilish-bhapa','pt','Ilish bhapa','Daca, Bangladexe','O hilsa, o peixe mais precioso do delta do Ganges, marinado numa pasta de mostarda crua e malagueta verde e depois cozido a vapor envolto em folha de bananeira, sem nunca tocar em fogo direto que o secaria.',ARRAY['Demolhe as sementes de mostarda 30 minutos em água morna, triture com metade das malaguetas verdes numa pasta fina.','Misture a pasta de mostarda com a curcuma, o iogurte, o óleo de mostarda e o sal.','Cubra os pedaços de hilsa com esta pasta, marine 20 minutos.','Envolva o peixe marinado e as malaguetas restantes inteiras numa folha de bananeira passada pela chama para amolecer.','Coza a vapor 15 a 20 minutos no pacote fechado, sirva diretamente na folha aberta.']::text[]),
('momo','pt','Momo','Catmandu, Nepal','Pequenos dumplings dobrados à mão em coroa, recheados com porco ou legumes e gengibre, cozidos a vapor em cestos de bambu empilhados. Sempre servidos com um molho de tomate e sésamo chamado achar, tão importante quanto o próprio recheio.',ARRAY['Amasse farinha, água e sal numa massa firme e lisa, repouse 30 minutos sob um pano.','Misture porco picado, couve bem cortada, cebola, gengibre, alho e coentros picados, ligue com molho de soja.','Estenda a massa muito fina, corte discos e recheie cada um com uma colherada de recheio.','Dobre as bordas apertando à volta para fechar em coroa, deixando um pequeno buraco no topo.','Coza a vapor 12 minutos em cestos de bambu empilhados, sirva com um molho de tomate e sésamo picante triturado à parte.']::text[])
insert into public.atlas_dish_texts (dish_id,lang,name,place,description,steps) values
('mohinga','pt','Mohinga','Rangum, Myanmar','Considerado o prato nacional birmanês: um caldo de peixe-gato engrossado com farinha de grão-de-bico e talo de bananeira, deitado sobre aletria de arroz, comido na rua ao amanhecer, mesmo antes do pequeno-almoço de arroz.',ARRAY['Escalfe o peixe-gato com citronela e gengibre 20 minutos, escorra reservando o caldo, esmigalhe a carne.','Refogue cebola e alho em rodelas em óleo até dourar, junte ao caldo reservado.','Misture a farinha de grão-de-bico com um pouco de água fria, incorpore ao caldo batendo para engrossar levemente, cozinhe 20 minutos com o molho de peixe.','Coza os ovos duros 9 minutos, descasque e corte ao meio.','Reparta a aletria de arroz cozida em tigelas, deite o caldo quente, cubra com peixe esmigalhado, ovo duro, coentros, lima e malagueta esmagada.']::text[]),
('fish-amok','pt','Fish amok','Phnom Penh, Camboja','Uma mousse de peixe com leite de coco e pasta de caril kroeung, cozida a vapor numa pequena taça de folha de bananeira dobrada, até adquirir a textura de um flan leve e perfumado.',ARRAY['Triture citronela, galanga, alho, chalota e malagueta numa pasta de caril fina.','Refogue a pasta a seco uns minutos até perfumar.','Triture o peixe cru com a pasta de caril, o leite de coco, o ovo e o molho de peixe até uma mousse lisa.','Molde taças com as folhas de bananeira, deite a mistura, decore com folhas de lima kaffir cortadas.','Coza a vapor 20 minutos até a mousse solidificar e inchar um pouco.']::text[]),
('larb','pt','Larb','Vientiane, Laos','O prato nacional laociano: carne picada selada rapidamente e depois temperada crua com lima, malagueta e hortelã, ligada com arroz glutinoso tostado e moído que dá à salada morna a sua crocância única.',ARRAY['Toste o arroz glutinoso cru a seco numa frigideira até dourar bem, depois moa grosseiramente num almofariz.','Refogue a carne picada a seco numa frigideira muito quente até cozinhar totalmente, esmigalhando com colher.','Fora do lume, tempere de imediato com sumo de lima, molho de peixe e malagueta esmagada.','Junte chalota em rodelas, hortelã e coentros picados, misture com suavidade.','Incorpore o arroz glutinoso tostado mesmo antes de servir, apresente sobre folhas de alface frescas.']::text[]),
('hainanese-chicken-rice','pt','Arroz de frango hainanês','Singapura','Um frango inteiro escalfado a baixa temperatura e depois mergulhado em água gelada para firmar a pele, servido fatiado sobre arroz cozido na própria gordura e caldo do frango, com três molhos obrigatórios: gengibre, malagueta e soja doce.',ARRAY['Esfregue o frango com sal, recheie com gengibre e alho esmagados, escalfe 40 minutos em água mal fervendo, nunca a ferver forte.','Mergulhe-o de imediato em água gelada 10 minutos para firmar e tornar a pele translúcida.','Refogue arroz enxaguado com um pouco de gordura de frango, gengibre e alho, molhe com o caldo de cozedura e cozinhe como arroz normal.','Triture malagueta, gengibre e alho restantes para um molho picante, misture soja com um pouco de caldo para um molho agridoce.','Corte o frango, sirva sobre o arroz com pepino, coentros e os três molhos à parte.']::text[]),
('taiwanese-beef-noodle-soup','pt','Sopa de miúdos de vaca taiwanesa','Taipé, Taiwan','Um caldo cozinhado durante horas com pasta de feijão preto, anis-estrelado e doubanjiang picante, onde o chambão de vaca estufa até ficar macio. Cada bairro de Taipé reivindica a sua própria receita como um segredo de família.',ARRAY['Escalde a vaca e o tendão 5 minutos em água a ferver, enxague para tirar a espuma.','Refogue gengibre, alho e doubanjiang em um pouco de óleo até o óleo ficar vermelho.','Junte a vaca, a pasta de feijão preto, o anis-estrelado, o tomate, a soja e o vinho de arroz, cubra generosamente com água.','Cozinhe tapado 2h30 em lume brando até a carne ficar macia.','Coza a massa e o bok choy à parte, sirva em tigelas, deite o caldo a escaldar e enfeite com cebolinho picado.']::text[]),
('buuz','pt','Buuz','Ulan Bator, Mongólia','Dumplings a vapor de carneiro picado à faca, nunca moído, dobrados com cerca de vinte pregas à volta de um pequeno buraco deixado de propósito para libertar vapor — o prato emblemático do ano novo lunar mongol, o Tsagaan Sar.',ARRAY['Pique o carneiro grosseiramente à faca com a cebola, mais grosso que para um recheio normal.','Misture com alho esmagado, cominho e sal, sem trabalhar demasiado o recheio.','Amasse farinha, água e sal numa massa firme, repouse 20 minutos, estenda e corte discos.','Recheie cada disco e dobre as bordas em cerca de vinte pregas apertadas, deixando um pequeno buraco no topo.','Coza a vapor 12 a 15 minutos em cestos empilhados, sirva a escaldar, come-se à mão.']::text[]),
('ema-datshi','pt','Ema datshi','Thimphu, Butão','O prato nacional butanês, onde a malagueta não é um condimento mas o ingrediente principal: grandes malaguetas verdes inteiras cozinhadas em queijo datshi local derretido até formar um molho espesso e ardente.',ARRAY['Corte as malaguetas verdes ao comprido sem tirar as sementes, em pedaços grandes.','Refogue cebola e alho na manteiga até ficarem translúcidos.','Junte as malaguetas e o tomate triturado, cozinhe 5 minutos em lume forte.','Esfarele o queijo datshi por cima, molhe com um pouco de leite e deixe derreter em lume brando mexendo.','Cozinhe 10 minutos até o molho ficar espesso e cremoso, sirva com arroz vermelho.']::text[]),
('rendang','pt','Rendang','Padang, Indonésia','Um guisado de vaca minangkabau cozinhado quatro horas em leite de coco e uma pasta de especiarias, até todo o líquido evaporar e caramelizar numa carne seca, quase negra, que assim se conserva semanas sem refrigeração.',ARRAY['Triture malaguetas secas reidratadas, chalota, alho, gengibre e galanga numa pasta fina.','Toste a seco o coco ralado até ficar castanho e perfumado, reserve.','Refogue a pasta de especiarias em um pouco de óleo até perfumar, junte a vaca em cubos e aloure.','Deite o leite de coco, junte citronela, folhas de lima kaffir e tamarindo, cozinhe destapado 3 a 4 horas mexendo com regularidade.','Continue a cozinhar até o líquido evaporar quase por completo e o molho caramelizar à volta da carne, incorpore o coco tostado no final.']::text[]),
('xiaolongbao','pt','Xiaolongbao','Xangai, China','Dumplings a vapor que escondem uma sopa inteira dentro: um caldo de porco gelificado a frio, fechado no recheio, que volta a ficar líquido ao cozinhar. Exigem-se pelo menos vinte pregas no topo para uma dobra bem feita.',ARRAY['Ferva a pele de porco 3 horas em água até obter um caldo gelatinoso, coe e arrefeça até solidificar em gelatina firme.','Corte a gelatina em cubinhos, misture com o porco picado, gengibre, cebolinho, soja, vinho de arroz e óleo de sésamo.','Amasse farinha e água numa massa lisa, repouse 30 minutos, estenda muito fina e corte discos.','Recheie cada disco com o recheio e cubos de gelatina, dobre as bordas em pelo menos vinte pregas apertadas no topo.','Coza a vapor 8 minutos em cestos de bambu forrados, sirva de imediato com vinagre de arroz e gengibre em tiras.']::text[]),
('chongqing-hotpot','pt','Hotpot de Chongqing','Chongqing, China','Uma panela de caldo escarlate com gordura de vaca, malagueta seca e pimenta de Sichuan, a ferver ao centro da mesa onde cada um mergulha por turnos carne, legumes e tofu com os seus próprios pauzinhos.',ARRAY['Derreta a gordura de vaca numa panela grande, junte o doubanjiang e refogue até o óleo ficar vermelho.','Junte malaguetas secas, pimenta de Sichuan, gengibre e alho, deixe infundir 10 minutos em lume brando.','Molhe com água ou caldo, leve a ferver e mantenha a panela a ferver ao centro da mesa num fogareiro.','Prepare tigelas individuais de óleo de sésamo e alho esmagado para arrefecer cada dentada.','Cada um mergulha por turnos finas fatias de vaca, tofu, couve chinesa e cogumelos enoki uns segundos no caldo a ferver antes de mergulhar no seu molho.']::text[]),
('naengmyeon','pt','Naengmyeon','Pyongyang, Coreia do Norte','Massa elástica de trigo-sarraceno servida gelada num caldo de vaca e kimchi clarificado, refrigerado durante horas. Nascida em Pyongyang para suportar invernos rigorosos, a sopa come-se tradicionalmente fria mesmo com muito frio lá fora.',ARRAY['Escalfe o peito de vaca 2 horas em água até macio, coe e arrefeça o caldo a noite toda.','Desengordure o caldo frio retirando a camada de gordura solidificada à superfície.','Misture o caldo desengordurado com suco de kimchi, vinagre de arroz e mostarda, acerte o tempero.','Coza a massa de trigo-sarraceno al dente, enxague de imediato em água gelada para parar a cozedura e firmar a textura.','Sirva a massa em tigelas geladas, cubra com o caldo bem frio, cubra com vaca em fatias, ovo duro, pepino, pera e rabanete em lâminas finas.']::text[]),
('brik','pt','Brik','Tunes, Tunísia','Uma folha de massa malsouka tão fina que se parte como vidro, dobrada em triângulo à volta de um ovo inteiro cru, atum e alcaparras, frita apenas o tempo suficiente para a gema ficar líquida na primeira dentada.',ARRAY['Estenda uma folha de massa malsouka na bancada, ponha ao centro atum esmigalhado, cebola em rodelas, alcaparras e salsa.','Parta um ovo inteiro no meio do recheio sem bater.','Dobre a massa em triângulo fechando o ovo, trabalhando depressa para não escorrer antes de cozinhar.','Deslize com cuidado em óleo quente e frite 2 minutos de cada lado, sem virar mais de uma vez para a gema ficar líquida.','Escorra em papel absorvente e sirva de imediato a escaldar, com um gomo de limão.']::text[]),
('bazin','pt','Bazin','Trípoli, Líbia','Uma bola compacta de farinha de cevada batida longamente com espátula de madeira até ficar lisa e firme, colocada em forma de cúpula ao centro de um guisado de carne e ovos cozidos, do qual se arrancam pedaços à mão.',ARRAY['Deite a farinha de cevada em água a ferver salgada em chuva, batendo sem parar com espátula de madeira.','Continue a bater 20 minutos em lume brando até obter uma bola lisa, firme e sem grumos.','Aloure o borrego em pedaços com cebola, alho e curcuma, junte o tomate e cubra com água.','Cozinhe 45 minutos até a carne ficar macia, junte os ovos cozidos descascados no final.','Molde o bazin em cúpula lisa ao centro de um prato, rodeie com o guisado e os ovos, sirva arrancando pedaços à mão.']::text[]),
('ful-medames','pt','Ful medames','Cartum, Sudão','Favas castanhas cozinhadas a noite toda em lume muito brando numa panela cónica de cobre chamada precisamente «ful», esmagadas grosseiramente com garfo com azeite, limão e cominho. O pequeno-almoço sudanês por excelência, comido com pão achatado.',ARRAY['Demolhe as favas castanhas a noite toda em água fria.','Coza-as tapadas 1h30 em lume muito brando em água fresca, até muito macias.','Esmague-as grosseiramente com garfo na água de cozedura, sem reduzir a puré liso.','Tempere com alho esmagado, sumo de limão, azeite e cominho, misture.','Sirva morno num prato fundo, com tomate e cebola picados, com pão achatado para molhar.']::text[]),
('moambe-chicken','pt','Frango moambé','Quinxassa, RD Congo','Frango cozinhado em polpa de noz de palma, moambé, cuja cor alaranjada e sabor rico o tornam o prato nacional em ambas as margens do rio Congo. Servido com fufu de mandioca e folhas de mandioca pisadas, o pondu.',ARRAY['Aloure os pedaços de frango numa panela, reserve.','Refogue cebola, alho e gengibre em rodelas, junte tomate triturado e malagueta.','Devolva o frango, incorpore o creme de noz de palma e cubra com água.','Cozinhe tapado 45 minutos até o molho engrossar e o óleo de palma subir à superfície.','Prepare o fufu deitando a farinha de mandioca em chuva em água a ferver, batendo com energia até uma bola lisa, sirva com o frango.']::text[]),
('ndole','pt','Ndolé','Douala, Camarões','O prato nacional camaronês: folhas de ndolé, uma variedade de amaranto ligeiramente amarga, fervidas e depois cozinhadas com amendoim pisado, carne e camarão seco, até um molho espesso quase castanho.',ARRAY['Ferva as folhas de ndolé duas vezes mudando a água para tirar o amargor, escorra e pique-as.','Toste a seco o amendoim e depois triture com um pouco de água numa pasta espessa.','Aloure a vaca em cubos com cebola, alho, gengibre e malagueta.','Junte a pasta de amendoim, o camarão seco e os camarões pisados, molhe e cozinhe 30 minutos mexendo com frequência para não pegar.','Incorpore as folhas de ndolé picadas, continue a cozinhar 15 minutos até um molho espesso, sirva com banana-da-terra ou arroz.']::text[]),
('attieke','pt','Attiéké com peixe','Abidjan, Costa do Marfim','Uma sêmola de mandioca fermentada e depois cozida a vapor em grãos leves, quase um cuscuz vegetal, servida com um peixe inteiro grelhado no carvão e um molho de tomate e cebola apimentado com malagueta kpakpo shito.',ARRAY['Humedeça a sêmola de mandioca com um pouco de água, solte com garfo.','Coza a vapor 15 minutos numa cuscuzeira, soltando a meio da cozedura para evitar grumos.','Esfregue o peixe inteiro com sal e limão, grelhe no carvão 8 minutos de cada lado.','Triture tomate, cebola, malagueta e alho numa molho fresco, tempere com azeite e sal.','Sirva o attiéké quente com o peixe inteiro grelhado e o molho de tomate à parte.']::text[]),
('maafe','pt','Maafe (mafé)','Bamaco, Mali','Um guisado de vaca cozinhado numa molho de pasta de amendoim, engrossado até quase cremoso, com couve, cenoura e batata-doce. Nascido entre os bambara e malinké, hoje presente por toda a África Ocidental em várias variantes.',ARRAY['Aloure a vaca em cubos com cebola e alho em rodelas em óleo.','Junte o tomate triturado, cubra com água e cozinhe 30 minutos.','Dilua a manteiga de amendoim com um pouco de caldo quente, incorpore ao guisado mexendo.','Junte couve, cenoura, batata-doce e uma malagueta inteira, continue a cozinhar 30 minutos em lume brando mexendo com regularidade para não pegar.','Acerte o tempero quando o molho estiver espesso e aveludado, sirva com arroz branco.']::text[]),
('sadza','pt','Sadza ne nyama','Harare, Zimbabué','Uma papa de farinha de milho batida até formar uma bola firme e lisa, o alimento base de todo o país, servida com carne guisada e vegetais de folha amargos chamados muriwo. Come-se com os dedos, formando uma pequena colher na bola quente.',ARRAY['Dilua um terço da farinha de milho com um pouco de água fria, deite em água a ferver batendo.','Cozinhe 5 minutos até uma papa espessa, depois incorpore o resto da farinha batendo com energia com espátula de madeira.','Continue a bater e cozinhar em lume brando 15 minutos até a bola ficar lisa, firme e se soltar das paredes.','Cozinhe a vaca em pedaços com cebola e tomate até macia, salteie os vegetais de folha com um pouco de manteiga de amendoim.','Sirva o sadza em bola com a carne e os vegetais à parte, coma com os dedos.']::text[]),
('piri-piri-chicken','pt','Frango piri-piri','Maputo, Moçambique','Um frango achatado e marinado numa molho de malagueta africana piri-piri, alho e limão, nascida do cruzamento entre os colonos portugueses e as especiarias locais. Grelhado no carvão e pincelado uma última vez com molho ardente antes de servir.',ARRAY['Achate o frango inteiro desossando parcialmente ao longo das costas, para cozinhar plano.','Triture malaguetas, alho, sumo de limão, azeite, colorau e louro numa molho picante.','Esfregue o frango com o molho, insistindo sob a pele, marine pelo menos 2 horas no frio.','Grelhe no carvão 35 minutos em lume moderado, pele para baixo primeiro, virando com regularidade.','Pincele uma última vez com molho piri-piri quente ao sair da grelha, repouse 5 minutos antes de trinchar.']::text[]),
('zanzibar-pilau','pt','Pilau de Zanzibar','Zanzibar, Tanzânia','Arroz perfumado com a mistura de especiarias pilau masala — canela, cardamomo, cominho, cravinho — tostada a seco antes de juntar a carne, herdado das rotas comerciais omanitas que fizeram de Zanzibar um cruzamento de especiarias.',ARRAY['Toste a seco canela, cardamomo, cominho e cravinho 2 minutos até perfumar, moa grosseiramente.','Frite a cebola em rodelas em óleo até dourar bem e caramelizar, reserve metade.','Aloure a vaca com alho, gengibre e as especiarias tostadas, junte o tomate triturado.','Junte o arroz enxaguado, molhe com o caldo quente e cozinhe tapado 18 minutos sem levantar a tampa.','Polvilhe a cebola caramelizada reservada mesmo antes de servir.']::text[]),
('isombe','pt','Isombe','Kigali, Ruanda','Folhas de mandioca pisadas longamente em almofariz até uma pasta fina, cozinhadas com óleo de palma, beringelas locais e por vezes peixinhos secos, servidas com batata-doce ou fufu.',ARRAY['Pise longamente as folhas de mandioca em almofariz até uma pasta fina e homogénea.','Ferva-as 20 minutos em água, escorra.','Refogue cebola e alho em óleo de palma, junte a beringela em cubos e o peixe seco esmigalhado.','Incorpore a pasta de mandioca e a manteiga de amendoim, cozinhe 15 minutos mexendo.','Coza as batatas-doces em água ou a vapor, sirva junto ao isombe.']::text[]),
('seswaa','pt','Seswaa','Gaborone, Botsuana','O prato festivo do Botsuana: carne de vaca fervida em água salgada durante horas sem outro tempero, até ficar tão macia que se desfaz sozinha ao pisar em almofariz, servida sobre bogobe de sorgo.',ARRAY['Corte a vaca em pedaços grandes, coloque numa panela grande com a cebola e a água salgada.','Leve a ferver e cozinhe tapado 2h30 a 3 horas, até a carne ficar extremamente macia.','Escorra a carne reservando um pouco de caldo, deixe amornar ligeiramente.','Pise em almofariz ou desfie com garfo em fibras finas, humedeça com um pouco do caldo reservado.','Prepare o bogobe cozinhando a farinha de sorgo em água a ferver, mexendo até uma papa espessa, sirva com a vaca desfiada.']::text[]),
('calulu','pt','Calulu','Luanda, Angola','O prato nacional angolano, cozinhando peixe seco e fresco juntos com folhas de batata-doce ou mandioca em óleo de palma, herdado das cozinhas escravas que tinham de aproveitar todas as partes disponíveis do peixe.',ARRAY['Demolhe o peixe seco 30 minutos em água morna para dessalgar, escorra.','Refogue cebola e alho em óleo de palma, junte tomate triturado e malagueta.','Junte ambos os peixes, molhe e cozinhe 20 minutos em lume brando.','Incorpore folhas de batata-doce, beringela em cubos e quiabo, continue a cozinhar 15 minutos.','Junte a batata-doce em pedaços, cozinhe mais 15 minutos até macia, sirva com arroz ou fufu.']::text[]),
('rolex','pt','Rolex','Campala, Uganda','Uma omelete de legumes enrolada num chapati quente, nascida nas bancas universitárias de Kampala onde se gritava «roll eggs» aos clientes com pressa — um trocadilho que se tornou o nome da comida de rua mais popular do Uganda.',ARRAY['Amasse farinha, água e sal numa massa macia, repouse 20 minutos, estenda em discos finos.','Coza cada chapati a seco em frigideira quente até inchar em zonas e dourar ligeiramente.','Bata os ovos com tomate, cebola e couve finamente picados.','Deite a mistura na frigideira untada e cozinhe numa omelete fina, sem virar.','Coloque o chapati quente sobre a omelete ainda na frigideira, pressione levemente e enrole tudo junto apertado antes de cortar.']::text[]),
('pepian','pt','Pepián','Cidade da Guatemala, Guatemala','Prato nacional maia-quiché declarado património cultural da Guatemala, cujo molho espesso deve o seu caráter às sementes de abóbora e sésamo tostadas e moídas, misturadas com pimentas secas tostadas até escurecer ligeiramente.',ARRAY['Escalfe o frango em água salgada 30 minutos, reserve o caldo.','Toste a seco sementes de abóbora, sésamo e pimentas secas até perfumar.','Grelhe a seco tomate, tomatillo, cebola e alho em frigideira até ficarem marcados de negro em zonas.','Triture tudo com um pouco de caldo até um molho espesso e algo grumoso.','Junte o frango, as batatas e o feijão-verde ao molho, cozinhe 20 minutos e sirva com arroz.']::text[]),
('baleada','pt','Baleada','Tegucigalpa, Honduras','Uma tortilha de farinha grossa, dobrada sobre feijão vermelho esmagado, queijo esfarelado e natas espessas — a refeição de rua mais simples de Honduras, vendida a qualquer hora em bancas improvisadas.',ARRAY['Amasse farinha, fermento, sal, óleo e água numa massa macia, repouse 15 minutos.','Forme bolas e estenda em discos grossos, coza a seco em frigideira quente 2 minutos de cada lado.','Aqueça o feijão vermelho cozido e esmague grosseiramente em puré espesso.','Barre cada tortilha quente com o puré de feijão.','Cubra com queijo esfarelado e natas espessas, dobre ao meio e sirva quente.']::text[]),
('pupusas','pt','Pupusas','San Salvador, El Salvador','O prato nacional salvadorenho: um bolo grosso de massa de milho, recheado com queijo, feijão ou chicharrón antes de cozinhar na chapa, sempre acompanhado de curtido, couve fermentada ligeiramente ácida.',ARRAY['Misture couve bem cortada, cenoura ralada, vinagre, orégãos e sal, deixe fermentar pelo menos 2 horas para o curtido.','Amasse a massa de milho com a água e o sal até uma massa macia que não pegue nas mãos.','Forme bolas, escave um poço ao centro e recheie com queijo esfarelado, feijão ou chicharrón picado.','Feche apertando e achate com cuidado num bolo grosso sem rebentar o recheio.','Coza numa chapa quente levemente untada 4 minutos de cada lado, sirva a escaldar com o curtido e um molho de tomate.']::text[]),
('sancocho-panameno','pt','Sancocho panamenho','Cidade do Panamá, Panamá','O prato nacional panamenho, um caldo de frango perfumado com culantro, um coentro de folhas longas muito mais intenso que o comum, onde o inhame cozinha até engrossar a sopa naturalmente.',ARRAY['Coloque o frango em pedaços numa panela grande com cebola, alho e culantro, cubra com água.','Leve a ferver, escume e cozinhe 45 minutos em lume brando.','Junte o inhame descascado em pedaços grandes e os pedaços de milho.','Continue a cozinhar 30 minutos até o inhame se desfazer um pouco e engrossar o caldo.','Acerte o tempero, junte orégãos e cebolinho picado no final, sirva a escaldar com arroz branco.']::text[]),
('mangu','pt','Mangú','Santo Domingo, República Dominicana','Um puré de bananas-da-terra verdes fervidas, esmagadas com a água de cozedura até ficar liso e brilhante, coroado com cebola roxa ao vinagre cozida apenas o suficiente para amolecer sem se desfazer. A base de todo pequeno-almoço dominicano, chamado «os três golpes».',ARRAY['Descasque as bananas-da-terra verdes e corte em pedaços, coza 20 minutos em água salgada até macias.','Escorra reservando um pouco de água de cozedura, esmague com espremedor juntando a água reservada e a manteiga até consistência lisa.','Corte a cebola roxa em rodelas, refogue-a com o vinagre 5 minutos até amolecer apenas.','Frite fatias de salame e ovos para acompanhar.','Sirva o puré de banana coroado com cebola ao vinagre, com queijo fresco, salame e ovo frito à parte.']::text[]),
('griot','pt','Griot','Porto Príncipe, Haiti','Cubos de porco marinados durante horas em sumo de laranja amarga e especiarias, fervidos e depois fritos duas vezes até um exterior quase lacado, servidos com pikliz, um relish de couve e malagueta scotch bonnet marinada em vinagre.',ARRAY['Corte o porco em cubos grandes, marine pelo menos 3 horas com sumo de laranja amarga, alho esmagado, cebola, cravinho e sal.','Escorra e ferva a carne 30 minutos no seu líquido de marinada coado até macia.','Prepare o pikliz misturando couve e cenoura finamente cortadas, malagueta scotch bonnet e vinagre, marine pelo menos 2 horas.','Escorra o porco fervido e frite-o em duas fornadas 8 minutos em óleo muito quente até dourar e ficar estaladiço.','Sirva a escaldar com o pikliz e arroz djon-djon ou branco.']::text[]),
('salteñas','pt','Salteñas','La Paz, Bolívia','Um pastel agridoce com guisado de vaca e batata ligado com gelatina antes de assar, para voltar a ser caldo escaldante dentro do forno. Come-se de pé de manhã, nunca se fura antes da primeira dentada.',ARRAY['Refogue cebola e vaca em cubos com colorau e açúcar até dourar.','Junte batata em cubos pequenos e caldo, cozinhe 25 minutos.','Dissolva a gelatina no caldo quente do guisado, arrefeça e leve ao frio até solidificar em gelatina firme.','Amasse farinha, manteiga derretida, ovo e água morna numa massa macia, repouse 30 minutos.','Estenda a massa, recheie com o guisado gelificado em cubos, uma ervilha, uma azeitona e uma passa, feche em pastel trançado e leve ao forno 25 minutos a 200 °C.']::text[]),
('encebollado','pt','Encebollado','Guayaquil, Equador','Uma sopa de atum-albacora e mandioca afogada sob uma montanha de cebola roxa marinada em lima, famosa por curar a ressaca de domingo de manhã em todo o Guayaquil, comida com chips de banana-da-terra.',ARRAY['Coza a mandioca descascada em água salgada 25 minutos até macia, reserve o caldo.','Escalfe o atum nesse mesmo caldo 10 minutos, esmigalhe-o grosseiramente.','Refogue tomate e cominho em um pouco de óleo, junte ao caldo com a mandioca e o atum esmigalhado.','Corte bem fina a cebola roxa, marine em sumo de lima e mostarda pelo menos 20 minutos.','Sirva a sopa a escaldar coroada generosamente com cebola marinada e coentros, com chips de banana-da-terra à parte.']::text[]),
('sopa-paraguaya','pt','Sopa paraguaia','Assunção, Paraguai','Apesar do nome, não é uma sopa mas um bolo salgado de farinha de milho, cebola refogada e queijo, nascido de um acidente de cozinha na corte do presidente Carlos Antonio López no século XIX, quando uma papa demasiado espessa foi assada por engano.',ARRAY['Refogue as cebolas em rodelas em manteiga e óleo até ficarem translúcidas, sem dourar.','Misture a farinha de milho com o leite, deixe inchar 10 minutos.','Incorpore os ovos batidos, o queijo esfarelado e as cebolas refogadas.','Deite numa forma untada, a mistura deve ficar fluida como uma massa de bolo espessa.','Leve ao forno 40 minutos a 180 °C até dourar por cima e uma faca sair limpa, deixe amornar antes de cortar em quadrados.']::text[]),
('doubles','pt','Doubles','Porto de Espanha, Trindade','Dois pãezinhos fritos levedados com curcuma, empilhados um sobre o outro à volta de um caril de grão-de-bico condimentado, daí o nome: «doubles». O pequeno-almoço de rua mais popular de Trindade e Tobago, vendido em carrinhos desde o amanhecer.',ARRAY['Amasse farinha, fermento, curcuma, cominho, água e sal numa massa macia, deixe levedar 2 horas.','Coza o grão-de-bico demolhado até macio, esmague parte para engrossar.','Tempere o caril de grão-de-bico com alho esmagado, malagueta scotch bonnet picada e coentros.','Divida a massa levedada em bolinhas, achate cada uma em disco fino e frite 1 minuto de cada lado em óleo quente até incharem.','Empilhe dois discos fritos, recheie generosamente com o caril de grão-de-bico e feche dobrando, sirva quente.']::text[]),
('conch-salad','pt','Salada de lambi','Nassau, Baamas','O lambi, este grande molusco de carne firme, batido e depois cortado em cubinhos e «cozinhado» apenas pela acidez da lima, preparado e servido em minutos diretamente nos cais dos mercados de pescadores.',ARRAY['Bata a carne de lambi com maço para amaciar, enxague bem.','Corte em cubinhos muito pequenos e regulares.','Misture com tomate, pimento, cebola e malagueta scotch bonnet, tudo em cubinhos.','Tempere generosamente com sumo de lima e sumo de laranja, sale.','Marine 15 minutos no frio mexendo uma vez, sirva bem frio polvilhado com coentros.']::text[]),
('texas-brisket','pt','Brisket texano','Austin, Texas, Estados Unidos','Um peito de vaca inteiro fumado doze horas sobre madeira de carvalho, temperado apenas com um rub de sal e pimenta preta moída, até formar uma crosta negra chamada bark à volta de uma carne fumada rosada até ao centro.',ARRAY['Apare o peito deixando uma fina camada de gordura, esfregue generosamente com sal e pimenta moída de todos os lados.','Repouse à temperatura ambiente 1 hora antes de colocar num fumeiro pré-aquecido a 110 °C.','Fume com madeira de carvalho 10 a 12 horas mantendo uma temperatura constante, sem abrir o fumeiro desnecessariamente.','Envolva a carne em papel de talho assim que a crosta estiver bem formada, continue a cozinhar até uma sonda entrar sem resistência, cerca de 93 °C no centro.','Repouse envolto pelo menos 1 hora antes de cortar fino contra as fibras, sirva com pão branco, pickles e molho barbecue.']::text[]),
('mumu','pt','Mumu','Port Moresby, Papua-Nova Guiné','Um forno cavado na terra, forrado com pedras aquecidas a lume de lenha durante horas, onde se empilham porco, batata-doce e vegetais de folha envoltos em folhas de bananeira, cobertos de terra para cozinhar em vapor toda a tarde.',ARRAY['Cave uma cova e aqueça pedras vulcânicas numa grande fogueira de lenha durante 2 horas.','Disponha as pedras a arder no fundo da cova, cubra com uma camada de folhas de bananeira.','Envolva o porco, a batata-doce e a mandioca em pacotes separados de folhas de bananeira, sale.','Empilhe os pacotes sobre as pedras, regue com leite de coco, cubra com folhas e depois terra para selar bem.','Deixe cozinhar em vapor 2h30 sem abrir, desenterre e sirva diretamente nas folhas abertas.']::text[]),
('palusami','pt','Palusami','Apia, Samoa','Folhas jovens e tenras de taro sobrepostas em pequenos embrulhos com leite de coco fresco e por vezes cebola e carne enlatada, atadas e cozinhadas em vapor até as folhas se fundirem numa textura próxima do espinafre.',ARRAY['Lave com cuidado as folhas jovens de taro, empilhe cinco em estrela para formar uma base larga.','Ponha ao centro um pouco de cebola picada e carne enlatada esmigalhada.','Dobre as folhas fechando um embrulho apertado, ate com uma tira de folha ou fio de cozinha.','Disponha os embrulhos numa panela, cubra generosamente com leite de coco e sal.','Cozinhe tapado em lume brando 45 minutos a 1 hora até as folhas ficarem bem macias, sirva quente.']::text[]),
('lap-lap','pt','Lap lap','Port Vila, Vanuatu','O prato nacional de Vanuatu: uma massa ralada de inhame, mandioca ou taro, afogada em leite de coco e coroada com frango ou peixe, cozinhada durante horas num forno de pedras envolto em folhas até se tornar um pão denso e macio.',ARRAY['Descasque e ralhe finamente o inhame até obter uma massa húmida.','Misture com metade do leite de coco até consistência de massa de bolo espessa.','Espalhe a massa sobre uma ampla base de folhas de bananeira sobrepostas, em camada uniforme.','Disponha o frango em pedaços e os vegetais de folha por cima, regue com o resto do leite de coco.','Dobre as folhas para envolver bem tudo, cozinhe em vapor sobre pedras quentes ou em forno muito brando 2 horas, sirva cortado em porções.']::text[])
insert into public.atlas_dish_texts (dish_id,lang,name,place,description,steps) values
('mulgipuder','pt','Mulgipuder','Tartu, Estónia','Um puré camponês de cevada e batata fervidas juntas até se fundirem, coroado com bacon grelhado e a sua gordura derretida deitada a escaldar mesmo antes de servir.',ARRAY['Demolhe a cevada 2 horas, escorra.','Coza cevada e batatas descascadas juntas em água salgada 35 minutos até bem macias.','Esmague tudo com espremedor sem procurar ficar liso, a textura deve ser rústica.','Corte o bacon em cubinhos, frite-os a seco com a cebola em rodelas até ficarem bem estaladiços.','Sirva o puré coberto com o bacon e a sua gordura de cozedura deitada a escaldar.']::text[]),
('pelekie-zirni','pt','Pelēkie zirņi (ervilhas cinzentas)','Riga, Letónia','Ervilhas cinzentas, variedade antiga cultivada há séculos no Báltico, cozinhadas até macias e misturadas com bacon derretido e cebola caramelizada. O prato de Natal letão por excelência, servido com leite fermentado.',ARRAY['Demolhe as ervilhas cinzentas a noite toda, escorra.','Coza tapadas 45 minutos em água pouco salgada até macias sem se desfazerem.','Corte o bacon em cubos pequenos, derreta-o em frigideira até ficar estaladiço.','Junte a cebola em rodelas e deixe caramelizar devagar na gordura do bacon.','Misture as ervilhas escorridas com o bacon e a cebola caramelizada, sirva quente com leite fermentado à parte.']::text[]),
('tave-kosi','pt','Tavë kosi','Tirana, Albânia','O prato nacional albanês: borrego alourado e depois coberto por um molho de iogurte e ovo que incha no forno como um suflé, para depois assentar numa crosta dourada e ligeiramente ácida.',ARRAY['Aloure o borrego em pedaços em manteiga com alho esmagado.','Junte o arroz e um pouco de água, cozinhe 30 minutos até a carne ficar macia.','Espalhe a carne e o arroz numa travessa de forno untada.','Bata o iogurte com os ovos e a farinha até ficar liso, deite sobre a carne.','Leve ao forno 30 minutos a 190 °C até inchar e dourar por cima, deixe repousar 10 minutos antes de servir.']::text[]),
('tavce-gravce','pt','Tavče gravče','Skopje, Macedónia do Norte','O prato nacional macedónio: feijão branco cozinhado e depois terminado no forno numa travessa de barro com colorau fumado e hortelã seca, até se formar uma fina pele por cima.',ARRAY['Demolhe o feijão branco a noite toda, escorra.','Coza 1 hora em água fresca até quase macio.','Refogue cebola e pimento em azeite, junte farinha e colorau fumado, molhe com tomate.','Misture o feijão escorrido a este molho, deite numa travessa de barro.','Leve ao forno destapado 30 minutos a 200 °C, polvilhe hortelã seca no final até se formar uma pele dourada por cima.']::text[]),
('kacamak','pt','Kačamak','Cetinje, Montenegro','Uma papa de farinha de milho e batata batida com espátula de madeira até ficar elástica, coberta de queijo fresco derretido e natas coalhadas, prato de pastores das montanhas montenegrinas.',ARRAY['Coza as batatas descascadas e cortadas em água salgada até macias, esmague-as grosseiramente na água.','Deite a farinha de milho em chuva sobre as batatas esmagadas, batendo sem parar com espátula de madeira.','Continue a cozinhar e bater 15 minutos em lume brando até obter uma massa elástica que se solte das paredes.','Incorpore o queijo fresco esfarelado e metade das natas, misture até se fundirem na papa quente.','Sirva de imediato, com o resto das natas e um pouco de manteiga derretida por cima.']::text[]),
('draniki','pt','Draniki','Minsk, Bielorrússia','Panquecas de batata crua ralada, espremida para tirar o excesso de água e depois fritas até as bordas ficarem rendadas e estaladiças, servidas com natas azedas bem frias.',ARRAY['Ralhe finamente as batatas e a cebola, pressione firme para tirar o excesso de líquido.','Misture com o ovo, a farinha e o sal até uma massa espessa.','Aqueça uma camada generosa de óleo em frigideira larga.','Ponha colheradas achatadas de massa, frite 3 minutos de cada lado até as bordas ficarem rendadas e douradas.','Escorra em papel absorvente, sirva a escaldar com natas azedas bem frias.']::text[]),
('placinta','pt','Plăcintă de queijo','Chisinau, Moldávia','Uma massa esticada à mão num círculo quase transparente, enrolada em espiral com queijo fresco e endro antes de ser achatada e cozinhada em frigideira seca até empolar em bolsas douradas.',ARRAY['Amasse farinha, água, ovo e sal numa massa macia, repouse 30 minutos sob um pano.','Divida em bolas e estique cada uma à mão sobre superfície untada até quase transparente.','Esmague o queijo fresco com endro picado, espalhe sobre toda a massa esticada.','Enrole num rolo apertado e depois enrole o rolo sobre si mesmo em espiral, achate com cuidado com rolo.','Coza em frigideira seca 4 minutos de cada lado em lume médio, pincele com manteiga derretida ao sair.']::text[]),
('flija','pt','Flija','Pristina, Kosovo','Até vinte camadas finas de massa, cada uma untada com natas e cozida separadamente sob uma redoma metálica chamada sač coberta de brasas, empilhadas umas sobre as outras num bolo listrado como um tronco de árvore.',ARRAY['Prepare uma massa líquida com farinha, água e sal, fina como massa de crepe.','Deite uma camada fina numa travessa redonda grande untada, leve ao forno muito quente 5 minutos até colorir ligeiramente.','Unte com natas, deite uma nova camada fina de massa por cima sem misturar as camadas.','Repita quinze a vinte vezes, alternando cozedura e untar com natas entre cada camada.','Termine com uma passagem sob o grelhador para dourar por cima, deixe amornar e corte em porções triangulares listradas.']::text[]),
('machboos','pt','Machboos','Dubai, Emirados Árabes Unidos','Arroz basmati perfumado com a mistura de especiarias bezar própria do Golfo, cozido no suco da carne e lima negra seca, herdado das rotas marítimas que ligavam os portos emiratenses à Índia e à África Oriental.',ARRAY['Aloure o frango com a cebola em rodelas e o alho em óleo.','Junte tomate triturado, especiarias inteiras e limas negras furadas, cubra com água e cozinhe 40 minutos.','Retire o frango, reserve o caldo perfumado coado.','Refogue o arroz enxaguado 2 minutos, molhe com o caldo quente e cozinhe tapado 18 minutos sem levantar a tampa.','Grelhe o frango uns minutos para dourar a pele, sirva sobre o arroz polvilhado com passas douradas.']::text[]),
('harees','pt','Harees','Doha, Catar','Trigo partido e carne cozinhados durante horas e depois batidos longamente até se tornarem numa papa perfeitamente lisa e aveludada, servida durante o Ramadão e nos casamentos por todo o Golfo.',ARRAY['Demolhe o trigo partido 2 horas em água, escorra.','Coloque trigo e frango numa panela grande, cubra generosamente com água e leve a ferver.','Cozinhe tapado 2h30 em lume muito brando até o frango se desfazer por completo.','Retire os ossos, bata com energia com batedor ou batedeira até uma papa lisa e homogénea.','Sirva a escaldar, com manteiga derretida e canela polvilhada por cima.']::text[]),
('shuwa','pt','Shuwa','Mascate, Omã','Um borrego inteiro marinado vários dias numa pasta de especiarias e vinagre, envolto em folhas de bananeira e enterrado numa cova aquecida com brasas durante vinte e quatro horas, até ficar tão macio que se desfia sozinho.',ARRAY['Triture alho, vinagre e todas as especiarias numa pasta espessa.','Esfregue generosamente o borrego inteiro com esta pasta, trabalhando-a em cortes feitos à faca, marine 2 dias no frio.','Envolva a carne em várias camadas de folhas de bananeira, ate com firmeza.','Cozinhe em vapor 8 a 10 horas em forno muito brando ou uma cova de brasas, até extremamente macia.','Desembrulhe e desfie a carne com garfo, sirva com arroz basmati.']::text[]),
('jireesh','pt','Jireesh','Cidade do Kuwait, Kuwait','Trigo partido grosso cozinhado com frango e especiarias até engrossar numa papa rústica, mais grossa que o harees vizinho, tradicionalmente comida nas frescas noites de inverno kuwaitianas.',ARRAY['Demolhe o trigo partido 1 hora, escorra.','Aloure a cebola em rodelas e o frango em manteiga.','Junte o trigo, a canela, o cardamomo e as limas secas, cubra com água e leve a ferver.','Cozinhe tapado 1h30 em lume brando, mexendo com regularidade para não pegar.','Esmague levemente com colher no final para engrossar, sirva quente.']::text[]),
('kibbeh','pt','Kibbeh','Damasco, Síria','Uma casca de bulgur fino e carne crua pisada até uma pasta lisa, moldada à mão em torpedo oco, recheada com carne picada e pinhões e depois frita até um castanho profundo e crocante.',ARRAY['Demolhe o bulgur fino 20 minutos em água fria, esprema com firmeza.','Triture metade da carne picada com o bulgur, uma cebola e as especiarias até uma pasta lisa e maleável.','Refogue a cebola restante com o resto da carne e os pinhões para o recheio, deixe arrefecer.','Molde a pasta em pequenos torpedos ocos com os dedos húmidos, recheie e feche apertando as pontas.','Frite a 170 °C até um castanho profundo e crocante, escorra e sirva quente.']::text[]),
('musakhan','pt','Musakhan','Nablus, Palestina','Frango assado colocado sobre pão taboun embebido em azeite e uma montanha de cebola confitada com sumagre durante horas, até se tornar quase uma compota roxa e ácida.',ARRAY['Esfregue o frango com azeite, sumagre e especiarias, asse 45 minutos em forno a 200 °C.','Corte em juliana fina uma grande quantidade de cebolas.','Confite-as muito devagar em azeite em lume muito brando 45 minutos, até macias e ligeiramente caramelizadas.','Junte o sumagre às cebolas confitadas no final, misture.','Espalhe o pão taboun numa travessa, cubra generosamente com a cebola de sumagre, ponha o frango assado por cima e polvilhe pinhões dourados em manteiga.']::text[]),
('muhammar','pt','Muhammar','Manama, Barém','Arroz basmati adoçado com xarope de tâmara e açafrão, um contraste inesperado servido junto a peixe grelhado salgado, numa tradição culinária bareinita onde o doce e o salgado se respondem no mesmo prato.',ARRAY['Coza o arroz basmati enxaguado em água salgada até quase macio, escorra.','Aqueça o xarope de tâmara com a manteiga e o cardamomo até ficar fluido.','Deite o xarope sobre o arroz escorrido, misture com suavidade para cobrir sem esmagar.','Tape e cozinhe a vapor 15 minutos em lume muito brando até absorção completa.','Sale e grelhe o peixe inteiro com limão, sirva junto ao arroz doce.']::text[]),
('lagman','pt','Lagman','Bisqueque, Quirguistão','Massa esticada à mão, tensionada e batida na bancada até à espessura desejada, coberta com um guisado de vaca e legumes condimentado com cominho, herdado das rotas da seda que atravessavam a Ásia Central.',ARRAY['Amasse farinha, água e sal numa massa muito macia, repouse 1 hora sob óleo.','Estique a massa em cordões longos, tensione e bata-os contra a bancada para os afinar em massa.','Aloure a vaca em tiras com cebola e alho em óleo.','Junte pimento, cenoura e tomate em tiras, cominho e soja, molhe e cozinhe 25 minutos.','Coza a massa em água a ferver 3 minutos, escorra e cubra com o guisado de vaca quente.']::text[]),
('qurutob','pt','Qurutob','Dushambe, Tajiquistão','O prato nacional tajique: pão fatir esmigalhado em pedaços, coberto por um iogurte seco reconstituído em molho, com tomate e cebola crus por cima. Comido tradicionalmente à mão numa grande travessa comum.',ARRAY['Dissolva as bolas de iogurte seco em água morna até um molho aveludado e ácido.','Esmigalhe o pão fatir em pedaços irregulares diretamente numa travessa grande.','Deite o molho de iogurte sobre o pão esmigalhado, misture com suavidade para embeber bem.','Corte fino tomate e cebola, disponha por cima.','Regue com azeite, polvilhe coentros e sirva de imediato à temperatura ambiente.']::text[]),
('gutap','pt','Gutap','Asgabate, Turquemenistão','Um pastel em meia-lua de massa fina recheado com abóbora ou vegetais de folha silvestres, cozido a seco em frigideira de ferro fundido sem uma gota de óleo, até a massa inchar em pequenas bolsas crocantes.',ARRAY['Amasse farinha, água e sal numa massa macia, repouse 30 minutos.','Ralhe a abóbora crua, misture com a cebola em rodelas, o cominho e o sal.','Estenda a massa fina, corte discos e recheie cada um com o recheio de abóbora.','Dobre em meia-lua e aperte firmemente as bordas para selar bem.','Coza a seco em frigideira quente 4 minutos de cada lado, tapado, pincele com manteiga derretida ao sair.']::text[]),
('kabuli-palaw','pt','Kabuli palaw','Cabul, Afeganistão','O prato nacional afegão: arroz basmati cozido em caldo de borrego, colorido com caramelo de açúcar e coroado com fina juliana de cenoura e passas salteadas até caramelizar levemente.',ARRAY['Aloure o borrego com a cebola em rodelas, cubra com água e cozinhe 1 hora até macio, reserve o caldo.','Corte as cenouras em juliana fina, saltear com o açúcar até caramelizar levemente, junte as passas no final.','Refogue o arroz enxaguado em um pouco de óleo, molhe com o caldo de borrego perfumado com cardamomo e cominho.','Cozinhe tapado 18 minutos em lume brando sem levantar a tampa.','Sirva o arroz, disponha o borrego por cima e coroe com as cenouras e passas caramelizadas.']::text[]),
('mas-huni','pt','Mas huni','Malé, Maldivas','O pequeno-almoço nacional maldivo: atum seco e fumado esmigalhado à mão, misturado cru com coco acabado de ralar, cebola roxa e malagueta, comido envolto em roshi, um pão achatado fino.',ARRAY['Esmigalhe finamente o atum seco e fumado à mão, tirando as espinhas.','Ralhe o coco fresco.','Corte bem fino a cebola roxa e a malagueta.','Misture o atum esmigalhado, o coco ralado, a cebola e a malagueta, regue com sumo de lima e sal.','Sirva à temperatura ambiente com roshi quente para envolver cada dentada.']::text[]),
('ambuyat','pt','Ambuyat','Bandar Seri Begawan, Brunei','O prato nacional bruneano, uma pasta viscosa e quase sem sabor de amido de sagu, enrolada com paus de bambu bifurcados chamados candas e mergulhada num molho ácido de tamarindo e malagueta.',ARRAY['Dilua o amido de sagu com um pouco de água fria para formar uma pasta lisa.','Leve o resto da água a ferver, deite a pasta de sagu em fio mexendo sem parar.','Continue a mexer em lume brando até a mistura ficar translúcida e viscosa, como uma cola espessa.','Triture tamarindo, malagueta, açúcar e camarão seco com um pouco de água para o molho de acompanhamento.','Enrole o ambuyat em paus bifurcados e mergulhe cada dentada no molho antes de engolir de uma vez, sem mastigar.']::text[]),
('ikan-sabuko','pt','Ikan sabuko grelhado','Díli, Timor-Leste','Uma cavala inteira pincelada com uma pasta de malagueta, tamarindo e citronela, grelhada sobre brasas de lenha até a pele estalar, comida com arroz e folhas de mandioca pisadas, prato quotidiano das margens de Díli.',ARRAY['Limpe e escame as cavalas, marque a pele duas ou três vezes de cada lado.','Triture malagueta, tamarindo, citronela e alho numa pasta espessa.','Pincele generosamente os peixes com esta pasta, também nos cortes, marine 30 minutos.','Grelhe sobre brasas de lenha 5 a 6 minutos de cada lado até a pele estalar.','Ferva e depois pise as folhas de mandioca, sirva com o peixe grelhado, arroz e um gomo de lima.']::text[]),
('solomon-cassava-fish','pt','Peixe em leite de coco com mandioca','Honiara, Ilhas Salomão','Peixe branco apenas cozinhado em leite de coco fresco espremido à mão, acompanhado de mandioca e batata-doce fervidas, a refeição quotidiana da maioria dos lares do arquipélago das Salomão.',ARRAY['Descasque e corte a mandioca e a batata-doce, ferva 20 minutos até macias.','Corte o peixe em pedaços grandes, sale levemente.','Aqueça o leite de coco mal fervendo com a cebola em rodelas.','Junte o peixe e escalfe devagar 8 minutos sem nunca deixar ferver forte.','Sirva o peixe em leite de coco com a mandioca, a batata-doce e um toque de lima, junto a vegetais de folha fervidos.']::text[]),
('lu-pulu','pt','Lu pulu','Nukualofa, Tonga','Carne enlatada ou vaca guisada envolta em várias camadas de folhas de taro com leite de coco, atada e cozinhada em vapor até as folhas grossas se fundirem numa textura próxima de espinafre murcho.',ARRAY['Corte a vaca em pedaços, misture com a carne enlatada esmigalhada e a cebola em rodelas.','Empilhe quatro a cinco folhas de taro em estrela para formar uma base larga.','Ponha o recheio de carne ao centro, dobre as folhas num embrulho bem apertado, ate.','Disponha os embrulhos numa panela, cubra generosamente com leite de coco.','Cozinhe tapado 1h30 a 2 horas em lume brando até as folhas ficarem bem macias, sirva quente com arroz ou taro fervido.']::text[]),
('bougna','pt','Bougna','Numeá, Nova Caledónia','O prato festivo canaco: peixe, frango ou lagosta envoltos com inhame, batata-doce e banana-da-terra em folhas de bananeira, regados com leite de coco e cozinhados durante horas num forno de terra aquecido com pedras vulcânicas.',ARRAY['Descasque e corte o inhame, a batata-doce e a banana-da-terra.','Sobreponha várias folhas de bananeira para formar uma base larga e firme.','Disponha o peixe e os legumes ao centro, regue generosamente com leite de coco, sale.','Dobre as folhas para envolver tudo num grande embrulho, ate com firmeza.','Cozinhe em vapor 2 horas sobre pedras quentes ou em forno muito brando, desembrulhe e sirva diretamente nas folhas.']::text[]),
('dambou','pt','Dambou','Niamey, Níger','Sêmola de milhete cozida a vapor misturada com folhas de couve ou espinafre pisadas, perfumada com óleo de amendoim e malagueta seca, um prato familiar nigerino que varia conforme os legumes do mercado do dia.',ARRAY['Humedeça a sêmola de milhete e solte-a à mão, coza a vapor 20 minutos numa cuscuzeira.','Ferva a couve e o espinafre 10 minutos, escorra e pise grosseiramente em almofariz.','Refogue cebola e tomate em óleo de amendoim com a malagueta.','Misture os legumes pisados ao molho de tomate e cebola.','Incorpore a sêmola cozida aos legumes, solte com garfo, reaqueça 5 minutos a vapor e sirva quente.']::text[]),
('riz-gras','pt','Riz gras','Uagadugu, Burquina Faso','Arroz cozinhado diretamente num molho de tomate rico em óleo, carne e legumes, que lhe dá a cor alaranjada e o nome: «arroz gordo». O prato festivo burquinabê por excelência, preparado em grandes quantidades para as grandes ocasiões.',ARRAY['Aloure a vaca em pedaços com cebola e alho em óleo.','Junte tomate triturado, louro, cubra com água e cozinhe 40 minutos até macia.','Junte cenoura e couve em pedaços, continue a cozinhar 10 minutos.','Retire a carne e os legumes, cozinhe o arroz enxaguado diretamente no molho de tomate restante e o seu óleo.','Assim que o arroz estiver cozido e colorido, devolva a carne e os legumes, reaqueça juntos e sirva.']::text[]),
('soupe-kandia','pt','Soupe kandia','Conacri, Guiné','Um molho de quiabo pisado até ficar fibroso e viscoso, cozinhado com peixe fumado e óleo de palma até engrossar numa textura quase pegajosa, deitado sobre arroz branco bem quente.',ARRAY['Corte o quiabo em rodelas finas, pise metade em almofariz até uma pasta fibrosa.','Refogue cebola, alho e tomate em óleo de palma.','Junte o quiabo inteiro e pisado, o peixe fumado esmigalhado e a malagueta, molhe com água.','Cozinhe 30 minutos em lume brando mexendo com regularidade, até o molho ficar espesso e viscoso.','Sirva sobre uma cama de arroz branco bem quente.']::text[]),
('cassava-leaf-stew','pt','Guisado de folhas de mandioca','Freetown, Serra Leoa','Folhas de mandioca pisadas longamente em almofariz até uma pasta fina, cozinhadas durante horas com peixe fumado, carne e óleo de palma até ficarem quase negras e profundamente perfumadas.',ARRAY['Pise longamente as folhas de mandioca em almofariz até uma pasta fina e homogénea.','Ferva a vaca em pedaços 30 minutos até macia.','Junte a pasta de mandioca, o peixe fumado esmigalhado, a cebola, a malagueta e os camarões pisados.','Deite o óleo de palma e cozinhe 45 minutos em lume brando mexendo com frequência, até a mistura escurecer e engrossar.','Sirva generosamente sobre arroz branco quente.']::text[]),
('palava-sauce','pt','Molho palava','Monróvia, Libéria','Folhas de batata-doce ou amaranto finamente picadas, cozinhadas com peixe, carne fumada e manteiga de amendoim até um molho espesso e verde, cujo nome viria das animadas conversas trocadas ao cozinhá-lo.',ARRAY['Pique finamente as folhas de batata-doce.','Ferva a vaca em pedaços 25 minutos até macia.','Junte o peixe fumado esmigalhado, a cebola, a malagueta e as folhas picadas.','Dilua a manteiga de amendoim com um pouco de caldo quente, incorpore ao molho com o óleo de palma.','Cozinhe 25 minutos em lume brando mexendo, até um molho espesso e verde, sirva sobre arroz.']::text[]),
('amiwo','pt','Amiwo','Cotonu, Benim','Uma pasta de farinha de milho batida até ficar lisa e firme, tingida de vermelho por um molho de tomate muito picante, servida com peixe grelhado ou frango nas tasquinhas de Cotonu.',ARRAY['Prepare um molho de tomate bem picante com cebola, malagueta e óleo de palma, deixe reduzir 20 minutos.','Dilua um terço da farinha de milho com um pouco de água fria, deite em água a ferver batendo.','Incorpore o resto da farinha batendo com energia com espátula de madeira.','Junte metade do molho de tomate diretamente à massa de milho continuando a bater, até uma massa vermelha lisa e firme.','Grelhe o peixe inteiro, sirva o amiwo com o peixe e o resto do molho de tomate.']::text[]),
('ablo','pt','Ablo com molho picante','Lomé, Togo','Pequenos bolos de arroz fermentado cozidos a vapor em folhas de bananeira até ficarem macios e ligeiramente ácidos, vendidos à noite nas ruas de Lomé com um molho de tomate e malagueta ardente.',ARRAY['Misture farinha de arroz, água, fermento e açúcar numa massa semilíquida, deixe fermentar à temperatura ambiente 4 a 6 horas.','Corte quadrados de folha de bananeira, deite uma concha de massa fermentada ao centro de cada um.','Dobre em pequenos embrulhos fechados e coza a vapor 20 minutos até os bolos ficarem firmes.','Triture tomate, malagueta e cebola para um molho fresco e ardente, sale.','Sirva os bolos mornos desembrulhados, com o molho picante.']::text[]),
('domoda','pt','Domoda','Banjul, Gâmbia','Um guisado de vaca cozinhado num molho espesso de pasta de amendoim e tomate, com couve e batata-doce, prato nacional gambiano frequentemente comparado a um mafé mas sempre mais concentrado em amendoim.',ARRAY['Aloure a vaca em cubos com cebola e alho em óleo.','Junte o tomate triturado, cubra com água e cozinhe 30 minutos.','Dilua a manteiga de amendoim com um pouco de caldo quente, incorpore ao guisado.','Junte couve, batata-doce e uma malagueta inteira, continue a cozinhar 30 minutos em lume brando mexendo com regularidade.','Acerte o tempero quando o molho estiver espesso e aveludado, sirva com arroz branco.']::text[]),
('mechoui','pt','Méchoui mauritano','Nuaquechote, Mauritânia','Um borrego inteiro untado com manteiga e especiarias, virado lentamente sobre brasas de lenha durante horas até a pele ficar estaladiça e dourada, prato de hospitalidade oferecido nas grandes ocasiões familiares.',ARRAY['Triture manteiga derretida, alho esmagado, cominho, colorau, sumo de limão e sal numa marinada espessa.','Esfregue generosamente o borrego inteiro com esta marinada, também por dentro, deixe repousar 2 horas.','Espete o borrego numa vara longa e firme de metal ou madeira.','Gire devagar sobre brasas moderadas 3 a 4 horas, pincelando com regularidade com o resto da marinada.','Verifique que a carne se solta facilmente do osso antes de trinchar e servir com pão e uma salada fresca.']::text[]),
('gozo','pt','Gozo com molho de amendoim','Bangui, República Centro-Africana','Uma pasta de mandioca batida até ficar lisa e elástica, o alimento base centro-africano, servida com um molho espesso de amendoim e vegetais de folha, para arrancar em bolinhas e molhar.',ARRAY['Deite a farinha de mandioca em chuva na água a ferver, batendo sem parar com espátula de madeira até uma bola lisa.','Refogue cebola, tomate e malagueta em óleo de palma.','Dilua a manteiga de amendoim com um pouco de água quente, junte ao molho de tomate.','Incorpore o espinafre cortado, cozinhe 15 minutos até engrossar.','Sirva o gozo em bola junto ao molho de amendoim, arrancando pedaços à mão para molhar.']::text[]),
('poulet-nyembwe','pt','Poulet nyembwe','Libreville, Gabão','O prato nacional gabonês: frango cozinhado num creme de noz de palma extraído e pisado à mão, cuja cor alaranjada profunda e riqueza recordam o moambé congolês, mais picante.',ARRAY['Aloure os pedaços de frango numa panela, reserve.','Refogue cebola, alho e gengibre em rodelas, junte tomate triturado e malagueta.','Devolva o frango, incorpore o creme de noz de palma e o louro, cubra com água.','Cozinhe tapado 45 minutos até o molho engrossar e o óleo subir à superfície.','Sirva com arroz branco ou mandioca fervida.']::text[]),
('saka-saka','pt','Saka-saka com chikwangue','Brazzaville, Congo','Folhas de mandioca finamente pisadas, cozinhadas em óleo de palma com beringela e peixe fumado, servidas com chikwangue, um pão de mandioca fermentado envolto e cozido em folhas, de textura pegajosa e ligeiramente ácida.',ARRAY['Prepare o chikwangue fermentando a mandioca ralada 2 dias, depois envolva em folhas de bananeira e ferva 2 horas.','Pise finamente as folhas de mandioca, ferva 20 minutos, escorra.','Refogue cebola, alho e malagueta em óleo de palma, junte a beringela em cubos.','Incorpore as folhas de mandioca pisadas e o peixe fumado esmigalhado, cozinhe 25 minutos em lume brando.','Sirva o saka-saka quente com fatias de chikwangue morno.']::text[]),
('pepesoup','pt','Sopa de pimenta','Malabo, Guiné Equatorial','Um caldo claro de peixe com malagueta ardente e casca de árvore amarga local, fama de curar constipações e ressacas, servido a escaldar em tigelas pequenas ao longo do golfo da Guiné.',ARRAY['Corte o peixe em pedaços, enxague bem.','Leve a água a ferver com cebola, alho e gengibre em rodelas.','Junte o peixe e a malagueta, inteira ou esmagada conforme o picante desejado.','Cozinhe 20 minutos em lume brando até o peixe estar cozido e o caldo perfumado.','Junte as folhas aromáticas picadas no final, sirva a escaldar em tigelas pequenas individuais.']::text[]),
('skoudehkaris','pt','Skoudehkaris','Cidade de Djibouti, Djibuti','O prato nacional djibutiano: arroz cozido no próprio suco do borrego, colorido com curcuma e cardamomo, herdado do cruzamento comercial entre a península arábica, a Índia e o Corno de África.',ARRAY['Aloure o borrego em pedaços com cebola e alho em óleo.','Junte tomate triturado, curcuma, cardamomo e canela, cubra com água e cozinhe 40 minutos.','Retire a carne, reserve o caldo perfumado.','Refogue o arroz enxaguado 2 minutos, molhe com o caldo quente e cozinhe tapado 18 minutos.','Devolva a carne sobre o arroz, reaqueça juntos uns minutos e sirva quente.']::text[]),
('zigni','pt','Zigni','Asmara, Eritreia','Um guisado de vaca cozinhado em berbere, uma mistura de malaguetas e especiarias tostadas própria do Corno de África, servido sobre injera, esse grande pão achatado e esponjoso de teff fermentado, que também serve de talher.',ARRAY['Prepare a injera misturando farinha de teff e água, deixe fermentar 2 dias e coza em grandes panquecas finas em frigideira quente sem gordura.','Derreta devagar as cebolas em rodelas a seco numa panela até reduzirem e dourarem, 20 minutos.','Junte a manteiga, o alho, o gengibre e o berbere, refogue 5 minutos até o óleo ficar vermelho.','Junte a vaca em cubos e o tomate, molhe e cozinhe 45 minutos em lume brando até macia.','Sirva o guisado sobre a injera, arrancando pedaços de pão para apanhar a carne.']::text[])
insert into public.atlas_dish_texts (dish_id,lang,name,place,description,steps) values
('bariis-iskukaris','pt','Bariis iskukaris','Mogadíscio, Somália','Arroz basmati longo perfumado com a mistura de especiarias somali xawaash, tingido com um fio de açafrão, frequentemente servido com uma banana cortada ao lado, numa combinação agridoce típica do Corno de África.',ARRAY['Aloure o frango com cebola e alho em óleo.','Polvilhe com xawaash, molhe e cozinhe 30 minutos até macio.','Retire o frango, reserve o caldo perfumado coado.','Refogue o arroz enxaguado, molhe com o caldo quente açafroado, cozinhe tapado 18 minutos.','Sirva o arroz com o frango, as passas e fatias de banana fresca ao lado.']::text[]),
('ibiharage','pt','Ibiharage','Bujumbura, Burundi','Feijão vermelho cozinhado longamente em óleo de palma vermelho com cebola e tomate, até formar um molho espesso quase cremoso, o alimento quotidiano da maioria dos lares burundeses, servido com banana-da-terra fervida.',ARRAY['Demolhe o feijão vermelho a noite toda, escorra.','Coza 1 hora em água fresca até macio.','Refogue cebola, alho e tomate em óleo de palma.','Junte o feijão escorrido ao molho, cozinhe 20 minutos, esmagando levemente parte para engrossar.','Ferva as bananas-da-terra descascadas, sirva junto ao feijão.']::text[]),
('nsima-chambo','pt','Nsima com chambo','Lago Malawi, Malawi','Uma bola de farinha de milho batida até ficar firme, servida com chambo, uma tilápia pescada no lago Malawi e frita inteira até a pele estalar, peixe tão apreciado que figura nas notas de banco do país.',ARRAY['Dilua um terço da farinha de milho com água fria, deite em água a ferver batendo.','Incorpore o resto da farinha batendo com energia com espátula de madeira até uma bola lisa e firme.','Limpe e escame as tilápias, sale e frite inteiras em óleo quente 5 minutos de cada lado até a pele estalar.','Refogue tomate e cebola para um molho fresco de acompanhamento.','Sirva a nsima em bola com o chambo frito, o molho de tomate e um gomo de limão.']::text[]),
('ifisashi','pt','Ifisashi','Lusaca, Zâmbia','Vegetais de folha locais cozinhados num molho espesso de amendoim pisado, servidos com nshima, essa mesma bola de milho batida que acompanha quase toda refeição zambiana, seja qual for o dia.',ARRAY['Toste a seco o amendoim e depois pise-o grosseiramente em almofariz.','Refogue cebola e tomate, junte o amendoim pisado e um pouco de água para formar um molho.','Junte os vegetais de folha picados, cozinhe 15 minutos até macios.','Prepare a nshima batendo a farinha de milho em água a ferver até uma bola lisa e firme.','Sirva a nshima com o ifisashi bem quente ao lado.']::text[]),
('kapana','pt','Kapana','Windhoek, Namíbia','Carne de vaca grelhada viva numa chapa a escaldar no coração do mercado de Katutura, cortada à frente do cliente e mergulhada numa mistura de malagueta e especiarias moídas, comida de pé sem prato.',ARRAY['Corte a vaca em tiras largas e finas.','Aqueça uma chapa de ferro fundido ou frigideira muito larga em lume forte.','Grelhe as tiras de vaca 2 a 3 minutos de cada lado, virando com frequência para selar bem todos os lados.','Triture malagueta, colorau, alho e sal numa mistura seca para molhar.','Corte a carne grelhada em pedaços pequenos à frente dos convidados, sirva com a mistura picante e um gomo de limão.']::text[]),
('motoho','pt','Motoho','Maseru, Lesoto','Uma papa de sorgo fermentado uns dias antes de cozinhar, o que lhe dá um toque ácido natural, comida às colheradas ou deitada numa chávena como uma bebida espessa do pequeno-almoço basotho.',ARRAY['Misture a farinha de sorgo com um pouco de água morna, deixe fermentar à temperatura ambiente 2 a 3 dias num pote tapado com um pano.','Leve o resto da água a ferver.','Deite a farinha fermentada em fio na água a ferver, mexendo sem parar.','Cozinhe 15 minutos em lume brando, batendo com regularidade, até uma papa fluida e ligeiramente ácida.','Adoce levemente, sale e sirva morno, às colheradas ou deitado numa chávena.']::text[]),
('sidvudvu','pt','Sidvudvu','Mbabane, Essuatíni','Abóbora fervida e depois esmagada diretamente na farinha de milho com que cozinha, formando uma papa doce e alaranjada, prato reconfortante do reino suázi.',ARRAY['Descasque e corte a abóbora, ferva 20 minutos até bem macia.','Esmague a abóbora diretamente na água de cozedura.','Junte a farinha de milho em chuva, batendo sem parar com espátula de madeira.','Continue a cozinhar 10 minutos em lume brando até uma papa espessa e homogénea.','Adoce levemente, junte a manteiga e o sal, sirva quente.']::text[]),
('kari-pwason','pt','Kari pwason','Vitória, Seicheles','Um caril de peixe com leite de coco e massalé, a mistura de especiarias crioula própria das Seicheles, cozinhado com tamarindo fresco que lhe dá um toque ácido, servido com arroz e uma salada de fruta-pão.',ARRAY['Refogue cebola, alho, gengibre e folhas de caril em óleo.','Junte o massalé e toste brevemente até perfumar.','Junte tomate e tamarindo, molhe com o leite de coco e cozinhe 15 minutos.','Junte o peixe cortado em pedaços, deixe escalfar 10 minutos sem ferver forte para não se partir.','Ferva a fruta-pão em pedaços, sirva o caril com arroz e a fruta-pão.']::text[]),
('dholl-puri','pt','Dholl puri','Port Louis, Maurícia','Uma torta fina recheada com ervilhas amarelas partidas moídas e cozidas, enrolada mal mais grossa que um crepe, servida dobrada com um caril e molho de malagueta. A herança indiana mais comida da Maurícia, vendida em cada esquina.',ARRAY['Demolhe as ervilhas partidas 2 horas, coza até macias e depois escorra e deixe secar.','Moa as ervilhas cozidas com cominho e curcuma até um pó fino.','Amasse farinha, água e sal numa massa macia, repouse 20 minutos, divida em bolas.','Achate cada bola, recheie com o pó de ervilhas, feche e estenda de novo bem fino.','Coza numa chapa quente levemente untada 2 minutos de cada lado, sirva dobrado com um molho de malagueta e alho.']::text[]),
('langouste-vanille','pt','Lagosta à baunilha','Moroni, Comores','Lagostas das lagoas comorianas flambadas e depois cozinhadas num molho de creme de coco infundido com vagens de baunilha local, sendo o arquipélago um dos principais produtores mundiais desta especiaria.',ARRAY['Corte as lagostas ao meio ao comprido, descasque levemente a cauda.','Sele-as em manteiga 2 minutos de cada lado, flambeie com rum.','Retire as lagostas, refogue cebola e alho na mesma manteiga.','Junte o leite de coco e as sementes de baunilha raspadas, deixe reduzir 10 minutos até um molho aveludado.','Devolva as lagostas ao molho, reaqueça 3 minutos, sirva com um toque de lima.']::text[]),
('cachupa','pt','Cachupa','Praia, Cabo Verde','O prato nacional cabo-verdiano, milho partido e feijão cozinhados durante horas com porco e legumes até quase puré, ainda melhor reaquecido e refogado na frigideira no dia seguinte, chamado então cachupa refogada.',ARRAY['Demolhe o milho partido e o feijão branco a noite toda, escorra.','Aloure o porco e a salsicha fumada com cebola, alho e tomate.','Junte o milho e o feijão escorridos, cubra generosamente com água e cozinhe 2h30 em lume brando.','Junte couve e batata-doce em pedaços, continue a cozinhar 30 minutos até tudo estar muito macio.','Sirva quente, ou reserve e refogue no dia seguinte em frigideira para a versão refogada.']::text[]),
('muzongue','pt','Muzongue','São Tomé, São Tomé e Príncipe','Uma sopa de peixe temperada com malagueta vermelha local e óleo de palma, engrossada com banana-da-terra verde ralada, prato festivo são-tomense preparado para as grandes reuniões de família à beira do oceano.',ARRAY['Corte o peixe em pedaços, sale levemente.','Refogue cebola, alho e tomate em óleo de palma.','Ralhe fino as bananas-da-terra verdes cruas, junte ao molho com água para engrossar.','Junte o peixe e a malagueta, cozinhe 20 minutos em lume brando até o peixe estar cozido e a sopa engrossada.','Sirva a escaldar com um toque de lima.']::text[]),
('belize-rice-beans','pt','Arroz e feijão com frango guisado','Cidade de Belize, Belize','A refeição dominical belizenha por excelência: arroz cozido em leite de coco e a água de demolha do feijão vermelho, servido com frango cozinhado longamente num molho de recado, um condimento de urucum vermelho escuro.',ARRAY['Demolhe o feijão vermelho a noite toda, escorra reservando a água de demolha.','Esfregue o frango com pasta de urucum, alho e sal, aloure e depois cozinhe 40 minutos com cebola e pimento.','Coza o feijão na sua água de demolha até macio.','Junte o arroz enxaguado e o leite de coco ao feijão cozido, cozinhe tapado 18 minutos.','Sirva o arroz com feijão com o frango guisado e o seu molho.']::text[]),
('oil-down','pt','Oil down','St. George''s, Granada','O prato nacional granadino: fruta-pão, legumes e carne salgada cozinhados em camadas em leite de coco até o líquido evaporar por completo e o óleo de coco subir à superfície, daí o nome.',ARRAY['Dessalgue o porco salgado 2 horas em água fria, escorra e corte em pedaços.','Descasque e corte a fruta-pão em gomos grandes.','Disponha em camadas numa panela grande: porco, salsicha, cebola, depois fruta-pão, salgando cada camada.','Misture o leite de coco com a curcuma, deite sobre as camadas, junte a malagueta inteira.','Tape e cozinhe 45 minutos sem mexer até o líquido evaporar quase por completo, junte os vegetais de folha nos últimos 10 minutos.']::text[]),
('cou-cou-flying-fish','pt','Cou-cou com peixe-voador','Bridgetown, Barbados','O prato nacional barbadense: uma polenta de sêmola de milho e quiabo batida com colher de madeira até ficar lisa, servida com peixe-voador escalfado em molho de tomate crioulo, um peixe que aparece até nas moedas do país.',ARRAY['Corte o quiabo em rodelas, ferva 10 minutos em água salgada, escorra reservando a água.','Deite a farinha de milho em chuva na água de quiabo a ferver, batendo sem parar com colher de madeira.','Incorpore o quiabo cozido, continue a bater 10 minutos até um puré liso e macio, junte a manteiga.','Marine o peixe-voador com lima e tomilho, escalfe 15 minutos num molho de tomate e cebola.','Sirva o cou-cou em cúpula com o peixe e o seu molho ao lado.']::text[]),
('green-fig-saltfish','pt','Banana verde e bacalhau salgado','Castries, Santa Lúcia','O prato nacional santa-lucense: bananas verdes fervidas, chamadas «figos» nas Caraíbas anglófonas, desfiadas e misturadas com bacalhau salgado dessalgado e salteado com tomate, cebola e malagueta.',ARRAY['Dessalgue o bacalhau 24 horas, mudando a água várias vezes, depois escalfe 10 minutos e esmigalhe.','Ferva as bananas verdes por descascar 20 minutos até macias, descasque e corte em rodelas.','Refogue cebola, pimento, alho e malagueta em óleo.','Junte tomate triturado e bacalhau esmigalhado, cozinhe 10 minutos.','Misture com suavidade às bananas em rodelas, polvilhe cebolinho e sirva quente.']::text[]),
('fungee-pepperpot','pt','Fungee e pepperpot','St. John''s, Antígua e Barbuda','O prato nacional antiguano: uma bola firme de sêmola de milho e quiabo chamada fungee, servida com um guisado espesso de vegetais de folha, quiabo e carne salgada chamado pepperpot, tão antigo quanto a colonização das Caraíbas orientais.',ARRAY['Dessalgue o porco salgado 2 horas, escorra e corte em pedaços.','Cozinhe com abóbora, espinafre, cebola e malagueta em água 40 minutos até tudo estar macio e o molho espesso.','Corte o quiabo em rodelas, ferva em um pouco de água, escorra reservando a água.','Deite a farinha de milho em chuva na água de quiabo a ferver, bata com espátula, incorpore o quiabo cozido até uma bola firme.','Sirva o fungee em bola com o pepperpot bem quente ao lado.']::text[]),
('dominica-bouyon','pt','Bouyon de Dominica','Roseau, Dominica','Um caldo copioso de raízes locais — inhame, dasheen, banana verde — e carne salgada, engrossado com dumplings de farinha, preparado todos os domingos em quase todos os lares da ilha dos mil rios.',ARRAY['Dessalgue o porco salgado 2 horas, escorra e corte em pedaços.','Cozinhe com cebola e tomilho em água 30 minutos.','Descasque e corte inhame, dasheen e banana verde, junte ao caldo e continue a cozinhar 20 minutos.','Amasse farinha e água numa massa firme, forme pequenos dumplings alongados, junte ao caldo 10 minutos antes do fim.','Acerte o tempero, polvilhe cebolinho e sirva a escaldar em tigelas grandes.']::text[]),
('pom','pt','Pom','Paramaribo, Suriname','Um gratinado de frango desfiado e raiz de pomtajer ralada, ligado à herança judaico-surinamesa com um molho de laranja amarga, assado até dourar por cima, prato imperdível das grandes festas familiares.',ARRAY['Escalfe o frango 30 minutos até macio, desfie reservando o caldo.','Ralhe fino a raiz de pomtajer crua.','Refogue cebola e alho, junte tomate e sumo de laranja amarga, deixe reduzir 10 minutos.','Misture o frango desfiado, o pomtajer ralado e o molho, deite numa travessa de forno untada, polvilhe pão ralado.','Leve ao forno 45 minutos a 180 °C até a superfície ficar bem dourada e crocante.']::text[]),
('guyana-pepperpot','pt','Pepperpot guianense','Georgetown, Guiana','O prato nacional guianense de Natal, um guisado de vaca e rabo de porco cozinhado durante horas em cassareep, um xarope negro de mandioca amarga fervido que age como conservante natural, permitindo «referver» a panela todos os dias durante semanas.',ARRAY['Dessalgue o rabo de porco 2 horas, escorra.','Coloque vaca e rabo de porco numa panela grande com cebola, canela e cravinho.','Junte o cassareep e cubra com água, leve a ferver e cozinhe tapado 2h30 em lume brando.','Junte a malagueta scotch bonnet inteira sem furar para perfumar apenas levemente, e o açúcar.','Continue a cozinhar até o molho ficar negro e espesso e a carne macia, sirva com pão.']::text[]),
('appam-stew','pt','Appam e stew','Cochim, Kerala, Índia','Uma panqueca de arroz fermentado com leite de coco, fina e crocante nas bordas mas grossa e esponjosa ao centro, cozida numa frigideira curva chamada appachatti, servida com um caril de frango suave com leite de coco, sem excesso de malagueta.',ARRAY['Demolhe o arroz 6 horas, triture com um pouco de leite de coco até uma massa lisa.','Junte fermento e açúcar, deixe fermentar à temperatura ambiente a noite toda até a massa duplicar e espumar.','Deite uma concha de massa num appachatti quente, gire para espalhar bordas finas e deixe o centro grosso, tape 2 minutos.','Refogue cebola, alho, gengibre e especiarias, junte o frango e aloure-o.','Molhe com o resto do leite de coco, cozinhe 25 minutos até macio, sirva com os appams quentes.']::text[]),
('sarson-da-saag','pt','Sarson da saag com makki di roti','Amritsar, Punjabe, Índia','Folhas de mostarda cozinhadas durante horas e depois pisadas num puré verde aveludado com manteiga clarificada, acompanhado de um pão grosso de farinha de milho, especialidade de inverno panjabi comida com uma noz de manteiga a derreter ao centro.',ARRAY['Ferva folhas de mostarda e espinafre com gengibre, alho e malagueta 40 minutos até muito macios.','Escorra reservando um pouco de água, pise ou triture grosseiramente num puré espesso.','Refogue a cebola em rodelas em ghee até dourar, incorpore ao puré verde, cozinhe 10 minutos.','Amasse a farinha de milho com água morna numa massa macia, forme discos grossos à mão.','Coza os roti a seco em frigideira quente, pincele com ghee, sirva com o saag coroado com uma noz de manteiga.']::text[]),
('macher-jhol','pt','Macher jhol','Calcutá, Bengala Ocidental, Índia','Um caril de peixe de água doce leve e aguado, perfumado com panch phoron, uma mistura de cinco sementes inteiras própria de Bengala, com batata e curcuma, comido diariamente com arroz por milhões de lares bengalis.',ARRAY['Esfregue o peixe com curcuma e sal, frite levemente em óleo de mostarda, reserve.','Aqueça um pouco de óleo, junte o panch phoron e deixe crepitar uns segundos.','Junte batata em pedaços e tomate, refogue e molhe com água.','Cozinhe 15 minutos até a batata estar quase macia, junte as malaguetas verdes partidas.','Devolva o peixe ao caldo, deixe escalfar 8 minutos sem ferver forte, polvilhe coentros e sirva com arroz.']::text[]),
('dal-baati-churma','pt','Dal baati churma','Jaipur, Rajastão, Índia','Bolas de massa de trigo duro assadas e depois mergulhadas em ghee derretido, servidas com um dal de lentilhas misturadas e um churma doce de trigo pisado com açúcar e cardamomo. Três texturas, três temperaturas, uma só travessa do Rajastão.',ARRAY['Amasse farinha de trigo integral, ghee derretido e água numa massa firme, forme bolas grossas.','Leve ao forno as bolas 30 minutos a 180 °C até firmes e rachadas, virando a meio da cozedura.','Coza ambas as lentilhas juntas com curcuma até macias, refogue cebola, tomate e cominho e misture ao dal.','Esfarele um terço das bolas assadas, pise com açúcar, cardamomo e ghee derretido para o churma.','Mergulhe as bolas restantes em ghee derretido, sirva o trio dal, baati e churma numa mesma travessa.']::text[]),
('dapanji','pt','Dapanji (frango de prato grande)','Urumqi, Xinjiang, China','Frango em pedaços cozinhado com batata e pimentos num molho ao mesmo tempo picante e ligeiramente doce, deitado ainda fumegante sobre larga massa fresca esticada à mão, especialidade uigur das rotas da seda.',ARRAY['Amasse farinha, água e sal numa massa macia, repouse 1 hora sob óleo, estique em massa larga e plana.','Refogue o frango em pedaços com alho, malaguetas secas, pimenta de Sichuan e anis-estrelado em óleo.','Junte batata em pedaços grandes, soja e açúcar, molhe e cozinhe 30 minutos.','Junte os pimentos em tiras nos últimos 10 minutos de cozedura.','Coza a massa em água a ferver 3 minutos, escorra e deite o frango e o seu molho a escaldar por cima.']::text[]),
('yangzhou-fried-rice','pt','Arroz frito de Yangzhou','Yangzhou, Jiangsu, China','Arroz do dia anterior, salteado grão a grão em wok a escaldar com fiambre, camarão e ervilhas, cada grão deve ficar solto e coberto de ovo dourado, nunca pegajoso. Um clássico nascido nas cozinhas imperiais da dinastia Sui.',ARRAY['Use arroz cozido no dia anterior e bem frio, solte com garfo para separar os grãos.','Bata os ovos, mexa-os rápido no wok muito quente, reserve em pedaços pequenos.','Refogue camarão e fiambre em cubos em óleo até ficarem apenas cozidos.','Junte o arroz, salteie em lume forte mexendo sem parar para separar bem os grãos, junte ervilhas e ovo.','Tempere com molho de soja e óleo de sésamo, polvilhe cebolinho picado e sirva de imediato, a escaldar.']::text[]),
('guilin-rice-noodles','pt','Massa de arroz de Guilin','Guilin, Guangxi, China','Massa de arroz fresca coberta com um caldo de porco e ossos cozinhado durante horas com especiarias secretas próprias de cada banca, coroada com porco marinado e amendoim, prato de pequeno-almoço imperdível nas ruas cársicas de Guilin.',ARRAY['Ferva os ossos de porco 5 minutos, enxague para tirar a espuma.','Volte a cozer com anis-estrelado e canela em bastante água, cozinhe 3 horas em lume muito brando.','Marine e asse fatias de porco até ficarem bem perfumadas, corte finas.','Aqueça a massa de arroz fresca em água a ferver uns segundos, escorra e ponha numa tigela.','Deite o caldo coado quente, cubra com porco marinado, amendoim, feijão em conserva, cebolinho e um fio de óleo picante.']::text[]),
('guobaorou','pt','Guobaorou','Harbin, Heilongjiang, China','Finas fatias de porco panadas em amido e fritas duas vezes até ficarem extra crocantes, depois salteadas rapidamente num molho agridoce translúcido, especialidade do nordeste chinês inventada para agradar a diplomatas russos no início do século passado.',ARRAY['Corte o porco em fatias finas, achate levemente.','Misture amido, ovo e um pouco de água numa pasta espessa, cubra cada fatia.','Frite uma primeira vez 2 minutos a 160 °C, escorra, depois frite uma segunda vez a 190 °C até muito crocante.','Prepare um molho aquecendo açúcar, vinagre de arroz, soja e alho até ficar xaroposo e translúcido.','Deite o molho a escaldar sobre o porco frito mesmo antes de servir, mexendo rápido para cobrir sem amolecer, polvilhe coentros.']::text[]),
('banh-mi','pt','Bánh mì','Cidade Ho Chi Minh, Vietname','Uma baguete herdada da colonização francesa, de miolo leve e crosta fina, aberta e recheada com patê, porco grelhado, legumes marinados em vinagre e coentros frescos — o encontro mais bem-sucedido entre padaria francesa e cozinha vietnamita.',ARRAY['Corte cenoura e rabanete daikon em juliana fina, marine 30 minutos em vinagre e açúcar.','Marine o porco em fatias finas em molho de soja, grelhe 3 minutos de cada lado.','Abra a baguete ao comprido sem cortar por completo, barre com patê e maionese.','Recheie com porco grelhado, legumes em conserva escorridos e rodelas de pepino.','Termine com uns raminhos de coentros frescos e sirva de imediato, crocante.']::text[]),
('bun-cha','pt','Bún chả','Hanói, Vietname','Hambúrgueres de porco marinado grelhados no carvão até caramelizar, mergulhados junto a aletria de arroz fria e ervas frescas numa tigela de nuoc cham morno, agridoce e ácido, prato de almoço emblemático dos passeios de Hanói.',ARRAY['Misture porco picado com um pouco de molho de peixe, açúcar e alho esmagado, forme hambúrgueres planos.','Grelhe os hambúrgueres sobre brasas de carvão 4 minutos de cada lado até caramelizar.','Prepare o nuoc cham misturando molho de peixe, açúcar, sumo de lima, água morna, alho e malagueta picados.','Corte a cenoura em juliana fina, junte-a levemente marinada ao nuoc cham.','Sirva os hambúrgueres grelhados a flutuar no nuoc cham morno, com aletria de arroz fria e ervas frescas ao lado para molhar.']::text[]),
('tom-yum-goong','pt','Tom yum goong','Banguecoque, Tailândia','Uma sopa de camarão ao mesmo tempo ardente, ácida e perfumada, onde citronela, galanga e folhas de lima kaffir infundem um caldo claro realçado com malagueta e sumo de lima no último momento, para preservar a sua vivacidade.',ARRAY['Descasque os camarões, reservando cabeças e cascas.','Refogue as cascas com citronela, galanga e folhas de lima kaffir em um pouco de óleo, molhe com água e deixe infundir 15 minutos, coe.','Leve o caldo coado a ferver, junte cogumelos e tomate, cozinhe 5 minutos.','Junte os camarões descascados, cozinhe 3 minutos até ficarem rosados.','Fora do lume, tempere com molho de peixe, sumo de lima e malagueta esmagada, polvilhe coentros e sirva de imediato.']::text[]),
('som-tam','pt','Som tam','Nakhon Ratchasima, Tailândia','Papaia verde ralada pisada em almofariz com alho, malagueta, tomate-cereja e feijão longo, temperada com molho de peixe, lima e açúcar de palma, cujo estrondo do pilão contra o almofariz de madeira marca o ritmo das ruas de Isan.',ARRAY['Ralhe a papaia verde em tiras finas.','Pise alho e malagueta em almofariz, junte o feijão longo cortado e pise levemente para amolecer.','Junte a papaia ralada e os tomates-cereja partidos ao meio, pise e misture sem reduzir a puré.','Tempere com molho de peixe, açúcar de palma e sumo de lima, pise de novo para misturar bem os sabores.','Polvilhe amendoim esmagado e camarão seco, sirva de imediato bem fresco.']::text[]),
('manti','pt','Mantı','Kayseri, Turquia','Minúsculos dumplings recheados com vaca picada, tão pequenos que a tradição diz que devem caber quarenta numa só colher, cobertos com iogurte de alho e um óleo de colorau a chiar deitado à mesa.',ARRAY['Amasse farinha, ovo, água e sal numa massa muito firme, repouse 30 minutos.','Misture a vaca picada com cebola ralada e espremida para extrair o suco, sale.','Estenda a massa extremamente fina, corte quadradinhos de 2 cm.','Recheie cada quadrado com uma pitada de recheio, aperte os quatro cantos juntos para fechar.','Escalfe os mantı 10 minutos em água a ferver, escorra, cubra com iogurte de alho e manteiga de colorau a chiar deitada quente à mesa.']::text[]),
('lahmacun','pt','Lahmacun','Şanlıurfa, Turquia','Uma massa esticada fina como papel, coberta até às bordas com uma pasta crua de carne picada, tomate, pimento e especiarias, assada apenas uns minutos em forno muito quente, enrolada com salsa e limão para comer à mão.',ARRAY['Amasse farinha, água, fermento e sal numa massa macia, deixe levedar 1 hora.','Triture carne picada crua, tomate, pimento, cebola, alho e colorau numa pasta fina e homogénea.','Divida a massa de pão em bolas, estique cada uma o mais fino possível num disco quase transparente.','Espalhe uma fina camada da pasta de carne até às bordas de cada disco.','Leve ao forno 6 a 8 minutos em forno muito quente a 250 °C, enrole com salsa fresca e um toque de limão antes de servir.']::text[]),
('gado-gado','pt','Gado-gado','Jacarta, Indonésia','Uma salada composta de legumes cozidos e crus, tofu, tempeh e ovo cozido, coberta com um molho espesso de amendoim perfumado com kecap manis, esse xarope de soja doce indonésio. O nome significa literalmente «mistura-mistura».',ARRAY['Coza separadamente couve, feijão-verde, rebentos de soja e batatas a vapor até macios mas ainda crocantes.','Frite o tofu e o tempeh em cubos dourados, coza os ovos duros.','Toste a seco o amendoim, triture com alho, malagueta, kecap manis, sumo de lima e um pouco de água até um molho espesso.','Disponha todos os legumes, tofu, tempeh, ovos e pepino cru numa travessa grande.','Cubra generosamente com o molho de amendoim e sirva à temperatura ambiente.']::text[]),
('sate-ayam','pt','Satay ayam','Madura, Indonésia','Pequenos cubos de frango marinado enfiados em espetos de bambu, grelhados sobre brasas de casca de coco até caramelizar levemente, servidos com um molho espesso de amendoim e arroz compactado, especialidade da ilha de Madura famosa pelos seus vendedores ambulantes.',ARRAY['Corte o frango em cubos pequenos, marine com soja, alho esmagado e coentros moídos 30 minutos.','Enfie os cubos em espetos de bambu previamente demolhados em água.','Grelhe sobre brasas moderadas 8 a 10 minutos virando com regularidade, até caramelizar levemente.','Toste a seco o amendoim, triture com kecap manis, malagueta, sumo de lima e um pouco de água para o molho.','Sirva os espetos cobertos com molho de amendoim, com cubos de arroz compactado.']::text[]),
('jambalaya','pt','Jambalaya','Nova Orleães, Luisiana, EUA','Um arroz cozinhado num caldo colorido pela santíssima trindade crioula — cebola, aipo, pimento verde — com enchido andouille fumado e camarão, herdeiro das paellas espanholas e dos pilafs africanos unidos por séculos de mistura da Luisiana.',ARRAY['Frite o enchido fumado em rodelas até soltar a gordura, reserve.','Na mesma gordura, refogue cebola, aipo e pimento verde picados até macios.','Junte alho, tomate, caiena e louro, refogue 2 minutos, devolva o enchido.','Junte o arroz, molhe com caldo de galinha, tape e cozinhe 20 minutos em lume brando sem mexer.','Junte o camarão nos últimos 5 minutos, misture com cuidado e sirva bem quente.']::text[]),
('philly-cheesesteak','pt','Cheesesteak de Filadélfia','Filadélfia, Pensilvânia, EUA','Vaca cortada fina e grelhada na chapa, misturada com cebola refogada e coberta de queijo derretido, empilhada num pãozinho macio — uma sanduíche nascida nos anos 1930 cuja versão cada morador defende conforme o seu bairro.',ARRAY['Congele ligeiramente a vaca para facilitar o corte, corte em tiras muito finas.','Derreta a cebola em rodelas em manteiga em chapa quente até dourar.','Junte a vaca, grelhe rápido picando-a com a espátula enquanto cozinha.','Espalhe o queijo sobre a carne quente, deixe derreter enquanto dobra tudo junto.','Recheie o pão hoagie aberto com esta mistura fumegante e sirva de imediato.']::text[]),
('nashville-hot-chicken','pt','Frango frito picante de Nashville','Nashville, Tennessee, EUA','Frango frito com uma panagem extra-crocante, pincelado mal sai da fritadeira com uma pasta ardente de pimenta caiena e gordura quente, servido sobre uma fatia de pão branco com pickles para absorver o fogo.',ARRAY['Marine os pedaços de frango em leitelho pelo menos 4 horas, idealmente a noite toda.','Escorra, passe por farinha temperada com sal e pimenta pressionando bem para aderir.','Frite a 175 °C 15 a 18 minutos até dourado escuro e crocante, virando a meio.','Misture caiena, açúcar mascavado, colorau e um pouco de óleo de fritura escaldante numa pasta espessa.','Pincele generosamente o frango ainda quente com esta pasta, sirva sobre pão branco com pickles.']::text[]),
('kalua-pig-laulau','pt','Kalua pig e laulau','Honolulu, Havai, EUA','Um porco inteiro enterrado horas num forno subterrâneo imu aquecido com pedras vulcânicas, saindo fumado, salgado e a desfazer-se, servido junto ao laulau — porco e peixe envolvidos em folhas de taro cozidas a vapor — peça central do festim luau.',ARRAY['Esfregue generosamente a pá de porco com sal marinho e fumo líquido para imitar o sabor do imu.','Envolva em folhas de bananeira, leve ao forno a baixa temperatura 190 °C durante 5 horas até se desfazer.','Para o laulau, envolva pedaços de porco e peixe em várias folhas de taro, depois numa folha de bananeira.','Cozinhe os embrulhos de laulau a vapor 3 horas até as folhas de taro ficarem macias e não irritantes.','Desfie o porco com garfo, sirva com os embrulhos de laulau abertos à mesa.']::text[])
insert into public.atlas_dish_texts (dish_id,lang,name,place,description,steps) values
('new-mexico-green-chile-stew','pt','Ensopado de chile verde do Novo México','Santa Fe, Novo México, EUA','Um ensopado de porco e batata sustentado por chiles verdes de Hatch, assados até enegrecer e depois descascados à mão, cujo sabor fumado e terroso distingue a cozinha do Novo México do resto do sudoeste americano.',ARRAY['Asse os chiles verdes em chama direta ou no forno até a pele enegrecer por completo.','Feche em saco plástico 10 minutos e depois descasque, retire sementes e pique.','Doure o porco em cubos com cebola, alho e cominho numa panela.','Junte os chiles picados, a batata em cubos e o caldo, leve a ferver.','Cozinhe 45 minutos tapado até o porco estar macio, tempere com orégãos e sirva com tortilhas.']::text[]),
('cochinita-pibil','pt','Cochinita pibil','Mérida, Iucatã, México','Porco marinado em achiote que o tinge de vermelho profundo, envolvido em folhas de bananeira e cozinhado originalmente num forno enterrado chamado pib, herdado dos maias, saindo macio e perfumado de citrinos amargos.',ARRAY['Dilua a pasta de achiote em sumo de laranja azeda e alho esmagado numa marinada lisa.','Cubra generosamente o porco com esta marinada, deixe repousar pelo menos 4 horas ou a noite toda.','Envolva o porco marinado em folhas de bananeira passadas pela chama para amolecer.','Leve ao forno o embrulho 4 horas a 150 °C até a carne se desfazer facilmente.','Desfie o porco, sirva com cebola roxa em conserva de vinagre e habanero, com tortilhas.']::text[]),
('mole-negro','pt','Mole negro','Oaxaca, México','Um molho quase preto que mistura chiles chilhuacle assados até amargar, chocolate, especiarias e fruta seca, reduzido durante horas numa pasta complexa que cobre o frango — o mais elaborado dos sete moles de Oaxaca.',ARRAY['Toste a seco os chiles secos até quase pretos e quebradiços, demolhe em água quente.','Toste igualmente amêndoas, passas, sésamo e uma tortilha rasgada até dourar.','Triture os chiles escorridos, a fruta seca tostada, o tomate e a canela com um pouco de caldo numa pasta lisa.','Refogue a pasta numa panela 20 minutos mexendo sem parar para não pegar, junte o chocolate e o resto do caldo.','Cozinhe o frango nesse molho 40 minutos até macio e o molho espesso e brilhante.']::text[]),
('huachinango-veracruzana','pt','Huachinango à veracruzana','Veracruz, México','Um pargo inteiro estufado num molho de tomate polvilhado com azeitonas verdes, alcaparras e jalapeños em rodelas, herança direta das influências espanhola, árabe e caribenha convergindo no primeiro porto colonial do México.',ARRAY['Refogue cebola e alho picados em azeite até translúcidos.','Junte tomate triturado e louro, cozinhe 15 minutos até reduzir.','Junte azeitonas verdes, alcaparras e jalapeño em rodelas, cozinhe mais 5 minutos.','Coloque o peixe inteiro no molho, tape e cozinhe 15 minutos, regando com regularidade.','Verifique se a carne se solta facilmente com garfo e sirva o peixe coberto com o seu molho.']::text[]),
('feijao-tropeiro','pt','Feijão tropeiro','Belo Horizonte, Minas Gerais, Brasil','Feijão preto escorrido e depois salteado com farinha de mandioca, toucinho, linguiça, couve e ovo mexido, prato robusto nascido dos tropeiros que cruzavam Minas Gerais com provisões que duravam semanas.',ARRAY['Coza o feijão preto em água até macio, escorra reservando um pouco da sua água.','Frite toucinho e linguiça em cubos até crocantes, junte cebola e alho.','Junte o feijão escorrido, misture em lume forte uns minutos.','Incorpore gradualmente a farinha de mandioca mexendo para cobrir sem grumos.','Junte a couve em tiras e o ovo mexido à parte, misture tudo e sirva quente.']::text[]),
('acaraje','pt','Acarajé','Salvador, Bahia, Brasil','Bolinhos de feijão-fradinho descascado, moído e frito em azeite de dendê até formar uma crosta dourada, abertos e recheados com vatapá e camarão seco, vendidos pelas baianas de vestido branco nas ruas de Salvador.',ARRAY['Demolhe o feijão-fradinho a noite toda, esfregue entre as mãos para tirar as peles.','Triture o feijão descascado com cebola e um pouco de água numa pasta lisa e arejada.','Bata a pasta vigorosamente com colher vários minutos para incorporar ar.','Forme bolinhos ovais com colher, frite em azeite de dendê a ferver até dourados.','Abra cada acarajé quente, recheie com vatapá e camarão seco, sirva de imediato.']::text[]),
('tacaca','pt','Tacacá','Manaus, Amazonas, Brasil','Um caldo amarelo vivo de tucupi, sumo de mandioca brava fermentado e fervido para retirar a sua toxicidade, engrossado com folhas de jambu que formigam e adormecem a língua, guarnecido com camarão seco, servido a escaldar em cuias talhadas numa cabaça amazónica.',ARRAY['Ferva o tucupi com alho esmagado durante 30 minutos para purgar bem a sua toxicidade residual.','Escalde separadamente as folhas de jambu em água a ferver 5 minutos.','Dissolva um pouco de fécula de mandioca em água fria, incorpore ao tucupi a ferver para engrossar levemente.','Reidrate o camarão seco num pouco de água quente.','Sirva o tucupi a escaldar numa tigela funda com folhas de jambu e camarão seco dispostos por cima.']::text[]),
('lomo-saltado','pt','Lomo saltado','Lima, Peru','Vaca salteada rapidamente em wok com cebola roxa e tomate, regada com molho de soja, servida com batata frita e arroz no mesmo prato — o prato chifa mais emblemático nascido do encontro entre imigrantes cantoneses e a cozinha andina.',ARRAY['Corte as batatas em palitos, frite até douradas e crocantes, reserve.','Corte a vaca em tiras grossas, sele muito rápido num wok a escaldar.','Junte cebola roxa e tomate em quartos, salteie mais 2 minutos em lume máximo.','Desglaceie com molho de soja e vinagre, sacuda o wok para cobrir bem sem soltar demasiado suco.','Junte as batatas fritas no fim da cozedura para se manterem crocantes, polvilhe coentros e sirva com arroz branco.']::text[]),
('anticuchos','pt','Anticuchos','Cusco, Peru','Espetos de coração de vaca marinados em pasta de ají panca, cominho e vinagre, grelhados sobre brasas até apenas caramelizar por fora mantendo-se macios por dentro, tradição inca perpetuada nos braseiros das ruas peruanas.',ARRAY['Limpe o coração de vaca retirando nervos e membranas, corte em cubos regulares.','Misture pasta de ají panca, vinagre, cominho e alho esmagado numa marinada espessa.','Cubra os cubos de coração com esta marinada, deixe repousar pelo menos 4 horas no frio.','Enfie os cubos em espetos de madeira, pincele com um pouco de óleo.','Grelhe sobre brasas vivas 3 a 4 minutos de cada lado pincelando com marinada, sirva de imediato bem quente.']::text[]),
('empanadas-saltenas','pt','Empanadas salteñas','Salta, Argentina','Pequenos pastéis de massa dobrados com uma trança apertada, recheados com carne picada à faca, ovo cozido, azeitona e cominho, assados em forno de lenha, especialidade do noroeste argentino onde cada província reivindica ciosamente a sua própria receita.',ARRAY['Amasse farinha, manteiga derretida, água morna e sal numa massa macia, repouse 30 minutos.','Refogue a cebola muito finamente picada com cominho e colorau até macia, junte a vaca picada à faca.','Molhe com um pouco de caldo para manter o recheio suculento, deixe arrefecer e incorpore ovo cozido picado e azeitonas.','Estenda a massa, corte círculos, recheie e feche apertando as bordas numa trança apertada.','Leve ao forno 20 minutos a 200 °C até douradas, sirva quentes.']::text[]),
('ajiaco-bogotano','pt','Ajiaco bogotano','Bogotá, Colômbia','Uma sopa de frango engrossada por três variedades de batata andina que se desfazem a velocidades diferentes, perfumada com guasca, uma erva local que não se encontra em mais lado nenhum, servida com natas azedas, alcaparras e meia espiga de milho.',ARRAY['Escalfe o frango inteiro no caldo com cebola e alho 40 minutos até macio, desfie a carne e reserve o caldo.','Descasque as três variedades de batata, corte em pedaços de tamanhos diferentes conforme a sua capacidade de se desfazer.','Cozinhe as batatas no caldo 25 minutos mexendo, algumas dissolvendo-se para engrossar a sopa.','Junte o frango desfiado e as espigas cortadas em pedaços, cozinhe 10 minutos.','Junte a guasca no fim da cozedura, sirva com natas azedas, alcaparras e um pedaço de milho por tigela.']::text[]),
('civet-de-sanglier-corse','pt','Civet de javali corso','Ajácio, Córsega, França','Javali caçado no maquis marinado vários dias em vinho tinto e murta, cozinhado durante horas até o molho engrossar naturalmente com o sangue, prato de caça de inverno servido com polenta de castanha local.',ARRAY['Corte o javali em pedaços grandes, marine 48 horas em vinho tinto com bagas de murta, zimbro, cebola, cenoura e louro.','Escorra a carne reservando a marinada, doure-a vigorosamente numa panela.','Junte os legumes da marinada, molhe com o vinho coado, cozinhe tapado 2h30 em lume muito brando.','Verifique se o molho engrossou naturalmente e a carne se solta facilmente, corrija o tempero.','Prepare a polenta de castanha dissolvendo a farinha em água a ferver com sal, sirva o civet coberto com o seu molho com a polenta.']::text[]),
('poulet-vallee-auge','pt','Frango vallée d’Auge','Pont-l’Évêque, Normandia, França','Um frango caseiro flambado em calvados e depois cozinhado num molho de natas espesso com maçãs macias, prato emblemático do Pays d''Auge onde macieiras, vacas leiteiras e alambiques desenham a paisagem.',ARRAY['Doure os pedaços de frango em manteiga até boa cor.','Aqueça o calvados, deite sobre o frango e flambe fora do lume.','Junte a cebola em rodelas e a sidra seca, cozinhe tapado 30 minutos.','Entretanto, refogue os gomos de maçã em um pouco de manteiga até macios e dourados.','Incorpore as natas ao suco de cozedura, deixe engrossar uns minutos, junte as maçãs e sirva coberto de molho.']::text[]),
('aligot-aubrac','pt','Aligot do Aubrac','Laguiole, Aveyron, França','Puré de batata batido energicamente com tome fresco do Aubrac até formar uma fita elástica que se estica metros, especialidade dos burons, essas cabanas de pastoreio de altitude.',ARRAY['Coza as batatas inteiras em água com sal até macias, descasque ainda quentes.','Esmague em puré muito liso, sem grumos, com um espremedor.','Devolva o puré à panela em lume brando, incorpore manteiga, natas e alho esmagado.','Junte o tome fresco cortado em lâminas aos poucos, batendo energicamente com espátula de madeira.','Continue a bater sem parar até o aligot formar uma longa fita elástica, sirva de imediato.']::text[]),
('culurgiones','pt','Culurgiones','Ogliastra, Sardenha, Itália','Ravioli fechados à mão num padrão entrançado em forma de espiga de trigo, recheados com batata esmagada, pecorino e hortelã selvagem, cuja dobra precisa distingue cada aldeia da Ogliastra sarda.',ARRAY['Amasse farinha, água e uma pitada de sal numa massa firme e lisa, repouse 30 minutos sob um pano.','Esmague a batata cozida com pecorino ralado, hortelã picada, alho e azeite num recheio homogéneo.','Estenda a massa fina, corte círculos, ponha uma colher de recheio ao centro de cada um.','Feche cada disco apertando as bordas em pequenas dobras sucessivas para formar o padrão entrançado característico.','Escalfe os culurgiones em água a ferver com sal uns minutos até flutuarem, sirva cobertos com molho de tomate.']::text[]),
('nduja-pasta','pt','Massa com nduja','Spilinga, Calábria, Itália','Um enchido fermentado de porco e malagueta calabresa, tão mole que se barra, derretido num molho de tomate até tingir a massa de um vermelho ardente, especialidade de Spilinga hoje exportada pelo mundo inteiro.',ARRAY['Aqueça o azeite com o alho esmagado até perfumado.','Junte a nduja esfarelada, deixe derreter em lume brando até tingir o azeite de vermelho.','Deite o molho de tomate, cozinhe 15 minutos em lume brando.','Coza a massa al dente em água bem salgada, escorra reservando um pouco da água de cozedura.','Misture a massa ao molho juntando um pouco de água de cozedura se necessário, polvilhe pecorino e salsa.']::text[]),
('canederli','pt','Canederli','Trento, Trentino, Itália','Grandes bolinhos de pão duro, toucinho fumado e queijo ligados com ovo, escalfados e servidos a flutuar num caldo de vaca claro ou simplesmente com manteiga, especialidade alpina que denuncia a influência austríaca do Trentino-Alto Ádige.',ARRAY['Corte o pão duro em cubos pequenos, demolhe em leite morno 15 minutos.','Frite o toucinho em cubos até crocante, junte ao pão demolhado.','Incorpore ovos batidos, farinha e salsa picada, misture numa massa homogénea mas não muito compacta.','Forme bolinhos grandes com as mãos húmidas, deixe repousar 15 minutos para se manterem.','Escalfe os canederli em caldo de vaca a fervilhar 15 minutos, sirva a flutuar no caldo ou escorridos com manteiga derretida.']::text[]),
('goya-champuru','pt','Gōyā champurū','Naha, Okinawa, Japão','Um salteado de melão amargo, tofu firme e toucinho, ligado com ovo batido, cujo nome champurū significa «mistura» em dialeto okinawano — prato quotidiano da ilha famosa pela longevidade excecional dos seus habitantes.',ARRAY['Corte o melão amargo ao meio, retire sementes e corte fino, sale 10 minutos para tirar o amargor e enxague.','Prense o tofu firme, corte em cubos, doure a seco em frigideira e reserve.','Frite o toucinho em fatias finas até crocante.','Junte o melão amargo escorrido, salteie 3 minutos, devolva o tofu dourado, tempere com molho de soja.','Deite o ovo batido por cima, deixe assentar sem mexer muito, polvilhe flocos de bonito e sirva.']::text[]),
('takoyaki','pt','Takoyaki','Osaka, Japão','Pequenas bolas de massa à base de dashi, cozinhadas numa chapa de moldes hemisféricos com um pedaço de polvo escondido ao centro, viradas com um gesto preciso de espeto, cobertas com molho agridoce e maionese.',ARRAY['Misture farinha, dashi e ovos batidos numa massa líquida e lisa, repouse 20 minutos.','Corte o polvo em cubinhos, pique a cebolinho e o gengibre em conserva.','Unte generosamente a chapa de takoyaki quente, deite a massa em cada molde hemisférico até transbordar levemente.','Ponha um pedaço de polvo, cebolinho e gengibre em cada cova antes de a massa assentar por completo.','Vire cada bola a meio da cozedura com um espeto fino para formar uma esfera perfeita, cubra com molho, maionese e flocos de bonito.']::text[]),
('jingisukan','pt','Jingisukan','Sapporo, Hokkaido, Japão','Cordeiro e ovelha grelhados numa chapa abaulada em forma de capacete mongol, rodeados de legumes que cozinham na gordura que escorre para as bordas, prato convivial de Hokkaido cujo nome vem de Gengis Khan.',ARRAY['Prepare a marinada misturando soja, mirin, alho e maçã ralada.','Marine fatias finas de cordeiro em metade do molho 30 minutos.','Aqueça a chapa abaulada, disponha os legumes cortados na borda baixa onde a gordura vai escorrer.','Grelhe o cordeiro marinado no centro abaulado da chapa uns minutos de cada lado.','Misture o cordeiro grelhado aos legumes cozinhados no suco de cozedura, sirva com o resto do molho para molhar.']::text[]),
('cataplana-de-marisco','pt','Cataplana de marisco','Portimão, Algarve, Portugal','Um guisado de amêijoas, camarão e chouriço cozinhado num recipiente de cobre em forma de concha que se fecha hermeticamente, o vapor cozinhando tudo lá dentro, símbolo culinário do Algarve nascido das trocas com o norte de África.',ARRAY['Deixe as amêijoas em água salgada 1 hora para largarem a areia.','Refogue cebola, alho e pimento em rodelas na base da cataplana aberta.','Junte tomate triturado e chouriço em rodelas, cozinhe 10 minutos.','Disponha amêijoas e camarão por cima, regue com vinho branco, feche hermeticamente a cataplana.','Cozinhe 12 minutos em lume forte sem abrir, abra à mesa e polvilhe coentros.']::text[]),
('espetada-madeirense','pt','Espetada madeirense','Funchal, Madeira, Portugal','Grandes cubos de vaca marinados em alho e louro, espetados num ramo de loureiro fresco talhado em ponta, suspensos sobre a mesa num suporte de ferro forjado para se soltarem diretamente no prato.',ARRAY['Corte a vaca em cubos grandes e regulares de cerca de 4 cm.','Marine com alho esmagado, louro esmigalhado, sal e vinho branco durante 4 horas.','Espete os cubos em ramos de loureiro frescos talhados em ponta.','Grelhe sobre brasas vivas virando com regularidade, 10 a 12 minutos conforme o ponto desejado.','Suspenda os espetos sobre a mesa num suporte, sirva com pão de milho.']::text[]),
('bolo-do-caco','pt','Bolo do caco','Câmara de Lobos, Madeira, Portugal','Um pão chato redondo à base de batata-doce, cozido não em forno mas diretamente sobre uma pedra vulcânica quente chamada caco, partido ainda fumegante e barrado com manteiga de alho nas ruas da Madeira.',ARRAY['Coza e esmague a batata-doce em puré fino, deixe arrefecer.','Amasse farinha, puré de batata-doce, fermento, sal e água morna numa massa macia, deixe levedar 1 hora.','Divida em bolas, achate cada uma num disco grosso de cerca de 2 cm.','Coza sobre pedra quente ou frigideira de ferro seca, 5 minutos de cada lado.','Misture manteiga derretida, alho esmagado e salsa, barre generosamente o pão ainda quente partido ao meio.']::text[]),
('cozido-das-furnas','pt','Cozido das Furnas','Furnas, São Miguel, Açores, Portugal','Um cozido de carnes e legumes fechado numa grande panela envolta em pano, enterrado no solo vulcânico fumegante da caldeira das Furnas e cozinhado seis horas apenas pelo calor geotérmico da ilha.',ARRAY['Disponha todas as carnes e enchidos no fundo de uma grande panela de pano resistente.','Junte couve em quartos, cenoura, batata e batata-doce por cima.','Feche hermeticamente a panela e enterre-a num buraco cavado no solo quente das fumarolas.','Deixe cozinhar assim 6 horas apenas pelo vapor geotérmico natural.','Desenterre a panela, abra-a à mesa e sirva as carnes e legumes macios no seu suco concentrado.']::text[]),
('tripas-a-moda-do-porto','pt','Tripas à moda do Porto','Porto, Portugal','Um guisado de tripas, feijão branco e carnes variadas, prato que deu aos habitantes do Porto a alcunha de tripeiros depois de, reza a lenda, terem oferecido toda a sua carne aos navios do infante D. Henrique.',ARRAY['Demolhe o feijão branco a noite toda, coza à parte até macio.','Limpe bem as tripas, escalde-as e depois coza 2 horas em água com cenoura e cebola.','Frite chouriço e toucinho, junte o frango em pedaços e doure.','Reúna tripas escorridas, carnes, feijão cozido e cominho numa mesma panela, cozinhe 45 minutos.','Sirva com arroz branco, prato substancial tradicionalmente partilhado numa grande mesa.']::text[]),
('migas-alentejanas','pt','Migas alentejanas','Beja, Alentejo, Portugal','Pão duro esmigalhado e prensado numa massa compacta em gordura de porco, formando uma crosta dourada e um interior macio, servido em fatias grossas com costeletas de porco grelhadas, prato camponês do Alentejo.',ARRAY['Esmigalhe o pão duro muito fino, regue com água morna salgada para humedecer ligeiramente.','Derreta a gordura de porco em frigideira grande com alho esmagado e louro.','Junte o pão esmigalhado, prense numa massa compacta, cozinhe em lume brando pressionando com regularidade até crosta dourada.','Grelhe à parte as costeletas de porco marinadas em colorau.','Corte as migas em fatias grossas, sirva com as costeletas grelhadas.']::text[]),
('posta-mirandesa','pt','Posta mirandesa','Miranda do Douro, Trás-os-Montes, Portugal','Uma grossa posta de vitela mirandesa, raça local criada em liberdade nos planaltos fronteiriços, grelhada simplesmente com azeite e alho para deixar falar apenas a qualidade da carne.',ARRAY['Tire a carne do frigorífico 1 hora antes de cozinhar para ficar à temperatura ambiente.','Aqueça uma chapa de ferro em lume forte com um pouco de azeite.','Sele as fatias grossas de vitela 3 minutos de cada lado para um ponto mal passado.','Regue com azeite infundido em alho e louro quente no final da cozedura.','Sirva com batatas grandes salteadas inteiras e sal grosso.']::text[]),
('rojoes-a-moda-do-minho','pt','Rojões à moda do Minho','Barcelos, Minho, Portugal','Cubos de porco marinados a noite toda em vinho branco, alho e colorau, fritos na sua própria gordura até crocantes por fora e macios por dentro, servidos com tripas de porco e castanhas.',ARRAY['Corte o porco em cubos, marine a noite toda com vinho branco, alho esmagado, colorau e louro.','Escorra os cubos reservando a marinada, doure-os na sua própria gordura em lume médio.','Junte um pouco de marinada durante a cozedura para desglacear e aromatizar, deixe reduzir.','Coza as castanhas à parte em água até macias.','Sirva o porco dourado com as castanhas e gomos de laranja fresca para cortar a gordura.']::text[]),
('chanfana-da-beira','pt','Chanfana da Beira','Miranda do Corvo, Beira, Portugal','Um cabrito cozinhado durante horas em vinho tinto espesso e tânico até a carne se soltar sozinha do osso, cozinhado tradicionalmente numa panela preta de barro colocada num forno de pão a lenha.',ARRAY['Corte o cabrito em pedaços grandes, esfregue com alho esmagado e colorau.','Disponha numa panela de barro com cebola, louro e gordura de porco.','Cubra por completo com vinho tinto tânico, feche a panela.','Leve ao forno a baixa temperatura 190 °C durante 4 horas em forno a lenha se possível.','Verifique se a carne se solta facilmente do osso e o molho reduziu, sirva com pão de milho.']::text[]),
('bifana','pt','Bifana','Vendas Novas, Alentejo, Portugal','Uma fina fatia de porco marinada em vinho branco, alho e piripiri, cozinhada no seu suco até extremamente macia, enfiada num papo-seco acabado de sair do forno, sanduíche popular devorada em duas dentadas.',ARRAY['Corte o porco em fatias finas, marine pelo menos 4 horas em vinho branco, alho, louro, colorau e piripiri.','Coza as fatias marinadas em lume médio em frigideira larga com a sua marinada.','Cozinhe destapado até o molho reduzir e cobrir a carne, cerca de 15 minutos.','Aqueça os papo-secos no forno uns minutos.','Recheie cada papo-seco com fatias de porco cobertas de molho e um toque de mostarda.']::text[]),
('ameijoas-a-bulhao-pato','pt','Amêijoas à bulhão pato','Lisboa, Portugal','Amêijoas abertas em minutos num caldo de alho, coentros frescos e vinho branco, receita batizada em homenagem a um poeta do século XIX conhecido pela sua gula, comidas diretamente com os dedos e pão para molhar.',ARRAY['Deixe as amêijoas em água salgada pelo menos 1 hora.','Aqueça o azeite com alho em lâminas e piripiri até perfumado sem dourar.','Junte as amêijoas escorridas e o vinho branco, tape.','Cozinhe em lume forte 5 minutos abanando a panela, até todas as amêijoas abrirem.','Polvilhe generosamente coentros frescos picados, regue com um fio de limão e sirva com pão.']::text[]),
('arroz-de-pato','pt','Arroz de pato','Aveiro, Portugal','Um arroz cozinhado no caldo de pato desfiado, disposto em camadas com chouriço e courato num tabuleiro de barro e depois levado ao forno até a superfície caramelizar numa crosta estaladiça, prato dominical por excelência.',ARRAY['Escalfe o pato inteiro com cebola, cenoura e louro 1 hora até macio, desfie a carne e reserve o caldo.','Coza o arroz no caldo de pato coado até dois terços da cozedura.','Disponha metade do arroz num tabuleiro de barro, cubra com pato desfiado e chouriço em rodelas.','Cubra com o resto do arroz, disponha o courato por cima, regue com um pouco de caldo.','Leve ao forno 20 minutos a 220 °C até a superfície ficar dourada e estaladiça, sirva com raspa de laranja.']::text[]),
('feijoada-a-transmontana','pt','Feijoada à transmontana','Chaves, Trás-os-Montes, Portugal','Um guisado robusto de feijão vermelho e vários enchidos fumados de Trás-os-Montes — chouriço, alheira, orelha e pé de porco — cozinhado durante horas para que os sabores fumados impregnem por completo o feijão.',ARRAY['Demolhe o feijão vermelho a noite toda, escorra.','Dessalgue a orelha e o rabo de porco escaldando em água a ferver.','Reúna feijão, carnes salgadas, chouriço, cebola, cenoura e louro numa panela grande, cubra com água.','Cozinhe tapado 2 horas em lume brando até o feijão e as carnes estarem macios.','Corrija o tempero, deixe repousar 10 minutos antes de servir bem quente.']::text[]),
('polvo-a-lagareiro','pt','Polvo à lagareiro','Sesimbra, Portugal','Um polvo inteiro fervido até macio e depois assado no forno, tentáculos abertos em estrela, banhado num generoso jorro de azeite virgem depois de cozinhado, rodeado de batatas assadas esmagadas à mão.',ARRAY['Congele e descongele o polvo para amaciar, ferva 40 minutos com louro até macio.','Asse batatas inteiras com pele até macias.','Coloque o polvo inteiro fervido num tabuleiro de forno, rodeie com as batatas levemente esmagadas à mão.','Regue generosamente com azeite e polvilhe alho esmagado, leve ao forno 15 minutos a 220 °C.','Polvilhe salsa fresca e sirva de imediato bem regado a azeite.']::text[]),
('sopa-da-pedra','pt','Sopa da pedra','Almeirim, Ribatejo, Portugal','Uma sopa farta de feijão vermelho, enchidos e legumes, nascida de uma lenda de um mendigo que convenceu uma aldeia a cozinhar uma simples pedra em sopa juntando, ingrediente a ingrediente, tudo o que era preciso para um verdadeiro festim.',ARRAY['Demolhe o feijão vermelho a noite toda, coza a meio.','Junte chouriço e orelha de porco dessalgada, cozinhe 40 minutos até macios.','Junte batata em cubos e couve em tiras, cozinhe mais 20 minutos.','Corrija o tempero com alho esmagado, deixe reduzir até consistência espessa.','Coloque tradicionalmente uma pedra lisa e limpa no fundo da tigela em homenagem à lenda, polvilhe coentros e sirva a escaldar.']::text[]),
('queijo-serra-broa','pt','Queijo da Serra e broa','Seia, Serra da Estrela, Portugal','Um queijo de ovelha cremoso de coração fluido, coalhado com flor de cardo segundo um método milenar, servido cortando simplesmente o topo para mergulhar uma colher, acompanhado de pão de milho denso chamado broa.',ARRAY['Amasse farinha de milho, farinha de trigo, fermento, sal e água morna numa massa densa e pegajosa.','Deixe a massa levedar 1 hora sob um pano num local morno.','Forme um grande pão redondo, leve ao forno 40 minutos a 200 °C até crosta grossa e escura.','Deixe o queijo de ovelha repousar à temperatura ambiente 30 minutos para amaciar a textura.','Corte o topo do queijo como uma tampa, sirva com fatias grossas de broa ainda morna.']::text[]),
('toucinho-do-ceu','pt','Toucinho do céu','Guimarães, Portugal','Um bolo conventual denso de amêndoas moídas e gemas de ovo, cujo nome significa «toucinho do céu» apesar de já não conter dele vestígio algum, herança das freiras que usavam as claras para engomar as suas toucas.',ARRAY['Faça uma calda espessa com açúcar e água, ferva 8 minutos até fiar.','Triture as amêndoas finas, incorpore à calda quente fora do lume, deixe amornar.','Bata as gemas, incorpore gradualmente à pasta de amêndoa morna batendo.','Junte raspa de limão, deite em forma untada.','Leve ao forno em banho-maria 35 minutos a 170 °C até apenas firme ao centro, deixe arrefecer antes de desenformar.']::text[]),
('favas-a-portuguesa','pt','Favas à portuguesa','Santarém, Ribatejo, Portugal','Favas frescas de primavera cozinhadas com chouriço, coentros e um ovo escalfado colocado no último momento, prato campestre do Ribatejo que celebra a chegada das primícias depois do inverno.',ARRAY['Descasque as favas frescas, refogue cebola e alho em lâminas em azeite.','Junte o chouriço em rodelas, refogue 3 minutos.','Junte as favas, molhe com um pouco de água, cozinhe tapado 20 minutos até macias.','Escalfe os ovos à parte em água a fervilhar com vinagre.','Sirva as favas polvilhadas com coentros frescos, um ovo escalfado em cada porção.']::text[]),
('confit-de-canard','pt','Confit de pato','Sarlat-la-Canéda, Perigord, França','Coxas de pato salgadas e depois cozinhadas lentamente submersas na sua própria gordura até extremamente macias, técnica de conservação ancestral do Perigord que se tornou um clássico de pele dourada e estaladiça.',ARRAY['Esfregue generosamente as coxas de pato com sal grosso, alho esmagado e tomilho, deixe repousar 24 horas no frio.','Enxague e seque bem as coxas para retirar o excesso de sal.','Submerja-as totalmente em gordura de pato derretida com o louro.','Cozinhe a temperatura muito baixa 3 horas, a gordura nunca deve ferver forte.','Doure a pele em frigideira antes de servir com batatas salteadas em gordura de pato.']::text[]),
('baeckeoffe','pt','Baeckeoffe','Colmar, Alsácia, França','Três carnes marinadas em riesling com batata e cebola, empilhadas numa terrina selada com um cordão de massa, que as camponesas alsacianas levavam ao forno do padeiro às segundas-feiras, dia da lavagem da roupa.',ARRAY['Corte as três carnes em pedaços grandes, marine a noite toda em riesling com cebola, louro e zimbro.','Descasque e corte finas as batatas.','Disponha em camadas numa terrina: batatas, carne marinada, batatas, terminando com batatas.','Deite a marinada por cima, sele a tampa com um cordão de massa de farinha e água.','Leve ao forno 3 horas a 160 °C sem abrir, quebre o cordão de massa à mesa para libertar os aromas.']::text[])
insert into public.atlas_dish_texts (dish_id,lang,name,place,description,steps) values
('biscuits-roses-de-reims','pt','Biscoitos rosa de Reims','Reims, Champagne, França','Um biscoito seco tingido de um rosa delicado, nascido no século XVII de padeiros champanheses que procuravam aproveitar o calor residual dos seus fornos, hoje mergulhado tradicionalmente numa taça de champanhe.',ARRAY['Separe as claras das gemas, bata as claras em castelo firme com metade do açúcar.','Bata as gemas com o resto do açúcar e a baunilha até esbranquiçar, junte umas gotas de corante rosa.','Incorpore delicadamente a farinha e depois as claras batidas, sem fazer descair a massa.','Com saco de pasteleiro, disponha palitos num tabuleiro, polvilhe generosamente com açúcar em pó.','Leve ao forno 12 minutos a 180 °C, deixe secar fora do forno antes de servir com uma taça de champanhe.']::text[]),
('tarte-tatin','pt','Tarte Tatin','Lamotte-Beuvron, Sologne, França','Uma tarte de maçãs caramelizadas assada ao contrário e virada no último momento, nascida de um famoso descuido das irmãs Tatin que esqueceram a massa e a adicionaram às pressas sobre a fruta já a cozinhar.',ARRAY['Amasse uma massa quebrada com farinha, manteiga, ovo e um pouco de água, deixe repousar 30 minutos no frio.','Derreta o açúcar a seco numa forma que vá ao forno até caramelo dourado.','Junte a manteiga ao caramelo, disponha as maçãs descascadas e cortadas em gomos apertados por cima.','Cozinhe as maçãs no caramelo em lume brando 15 minutos, cubra com a massa estendida, dobrando as bordas para dentro.','Leve ao forno 30 minutos a 200 °C, deixe amornar 10 minutos e depois vire num prato, sirva com natas frescas.']::text[]),
('poulet-au-vin-jaune','pt','Frango ao vinho amarelo e morilhas','Arbois, Jura, França','Um frango caseiro cozinhado em vinho amarelo do Jura, vinho oxidativo de notas a noz envelhecido seis anos sob véu, casado com morilhas secas reidratadas e umas natas aveludadas — o casamento mais prestigiado do Jura.',ARRAY['Demolhe as morilhas secas em um pouco de água morna 30 minutos, coe e reserve o líquido.','Doure os pedaços de frango em manteiga, reserve.','Refogue a chalota em lâminas, desglaceie com vinho amarelo, deixe reduzir a metade.','Devolva o frango, junte as morilhas e o seu líquido coado, cozinhe tapado 35 minutos.','Incorpore as natas no final da cozedura, deixe engrossar levemente e sirva bem quente.']::text[]),
('salade-lyonnaise','pt','Salada lionesa','Lyon, França','Uma salada de chicória amarga coroada com toucinho crocante e um ovo escalfado cuja gema líquida se mistura com um vinagrete quente, prato de bouchon lionês reconfortante apesar da aparência leve.',ARRAY['Lave e seque bem a chicória, disponha numa saladeira grande.','Frite o toucinho a seco até crocante, reserve a gordura libertada.','Esfregue croutons de pão tostado com alho.','Desglaceie a gordura de toucinho quente com vinagre e mostarda para o vinagrete quente, deite sobre a chicória.','Escalfe os ovos, coloque um em cada prato com toucinho e croutons, sirva de imediato.']::text[]),
('soupe-au-pistou','pt','Sopa au pistou','Toulon, Provença, França','Uma sopa de legumes de verão e feijão branco e vermelho, coroada mesmo antes de servir com uma colher de pistou — manjericão, alho e parmesão pisados com azeite — primo provençal do pesto genovês.',ARRAY['Coza separadamente o feijão branco e vermelho até macios.','Leve a ferver um grande volume de água, junte batata e courgette em cubos, cozinhe 15 minutos.','Junte tomate triturado, feijão-verde cortado, feijão cozido e massa, cozinhe mais 15 minutos.','Pise em almofariz manjericão, alho e parmesão, incorpore o azeite aos poucos até pasta lisa.','Sirva a sopa a escaldar, uma colher de pistou ao centro de cada tigela mesmo antes de saborear.']::text[]),
('potjevleesch','pt','Potjevleesch','Dunquerque, Flandres, França','Uma terrina fria de quatro carnes — coelho, frango, porco e vitela — cozinhadas separadamente e depois solidificadas juntas numa gelatina de vinagre branco, especialidade flamenga servida em fatias com batatas fritas quentes.',ARRAY['Corte as quatro carnes em pedaços grandes, disponha numa panela grande com cebola e louro.','Cubra com água e vinagre branco, cozinhe tapado 2h30 em lume brando até muito macias.','Escorra as carnes reservando o caldo, disponha numa terrina.','Reduza o caldo, dissolva a gelatina nele, deite sobre as carnes na terrina.','Deixe solidificar no frigorífico pelo menos 12 horas, desenforme e sirva fatiado frio com batatas fritas.']::text[]),
('brandade-de-morue','pt','Brandade de bacalhau','Nîmes, Occitânia, França','Bacalhau dessalgado desfiado e depois montado com azeite como uma maionese, até formar uma espuma branca e aveludada, herança das trocas entre pescadores nórdicos e produtores de azeite do sul mediterrânico.',ARRAY['Dessalgue o bacalhau 24 horas, mudando a água várias vezes.','Escalfe o bacalhau em água a fervilhar 10 minutos, escorra e desfie retirando pele e espinhas.','Esmague o bacalhau desfiado com alho, monte com azeite aos poucos batendo como uma maionese.','Junte leite morno gradualmente para amaciar a textura, tempere com noz-moscada.','Sirva morno com croutons de pão tostado, como entrada ou prato leve.']::text[]),
('kig-ha-farz','pt','Kig ha farz','Brest, Bretanha, França','Um cozido bretão onde fervem vaca salgada e legumes, dentro do qual cozinha envolto num saco de pano um far de trigo-sarraceno que, desenformado e esfarelado, se rega com manteiga avelã e gwell, leite fermentado local.',ARRAY['Coza a vaca salgada e o toucinho em bastante água 2 horas até macios.','Junte couve em quartos e cenoura, cozinhe mais 40 minutos.','Prepare o far misturando farinha de trigo-sarraceno, ovos, leite e passas numa massa líquida.','Deite a massa num saco de pano limpo atado frouxamente, mergulhe-o no caldo para cozinhar 1 hora.','Desenforme o far, esfarele-o com garfo, regue com manteiga derretida e sirva com a carne e os legumes.']::text[]),
('axoa-espelette','pt','Axoa de Espelette','Espelette, País Basco, França','Vitela picada grosseiramente à faca, cozinhada com pimentos verdes e a famosa malagueta de Espelette que pende em grinaldas pelas fachadas da aldeia durante todo o outono, prato basco profundamente colorido e perfumado.',ARRAY['Pique a vitela grosseiramente à faca em pedaços pequenos irregulares.','Refogue cebola e pimentos verdes em lâminas até macios.','Junte a vitela, doure-a em lume forte uns minutos.','Junte tomate triturado, alho, malagueta de Espelette e vinho branco, cozinhe tapado 30 minutos.','Corrija o picante a gosto, sirva com malaguetas de Espelette fritas como acompanhamento.']::text[]),
('fiadone','pt','Fiadone','Corte, Córsega, França','Um bolo macio de brocciu, queijo fresco corso de ovelha ou cabra, perfumado com raspa de limão, de textura entre flan e cheesecake, servido morno ou frio no fim de uma refeição insular.',ARRAY['Esmague o brocciu com garfo até consistência lisa.','Bata os ovos inteiros com o açúcar até esbranquiçar e duplicar de volume.','Incorpore o brocciu esmagado, a raspa de limão e a aguardente à preparação.','Deite em forma untada, leve ao forno 35 minutos a 180 °C até dourado e apenas firme ao centro.','Deixe arrefecer antes de desenformar, sirva morno ou fresco conforme a estação.']::text[]),
('potee-auvergnate','pt','Potée auvernhesa','Clermont-Ferrand, Auvérnia, França','Um cozido de terreiro que reúne toucinho curado, salsicha e couve verde com hortaliças de raiz do Maciço Central, cozinhado durante horas numa grande panela de ferro outrora suspensa na corrente da lareira.',ARRAY['Dessalgue o toucinho curado várias horas, mudando a água.','Coza em bastante água 1 hora com louro.','Junte cenoura, nabo e alho-francês, cozinhe mais 45 minutos.','Junte couve em quartos, batata e salsicha, cozinhe mais 30 minutos até tudo macio.','Sirva a carne e os legumes escorridos em pratos fundos grandes, com um pouco de caldo e mostarda à parte.']::text[]),
('diots-au-vin-blanc','pt','Diots ao vinho branco','Chambéry, Saboia, França','Pequenas salsichas de porco saboianas cozinhadas em vinho branco de Apremont com cebola e louro, até a pele se embeber de vinho, servidas tradicionalmente com polenta cremosa ou batatas.',ARRAY['Pique levemente as salsichas com garfo para evitar que rebentem.','Doure-as numa panela com a cebola em lâminas.','Molhe com vinho branco, junte o louro, cozinhe tapado 30 minutos em lume brando.','Entretanto, prepare uma polenta cremosa dissolvendo a sêmola de milho em água a ferver com sal, incorpore manteiga e comté ralado.','Sirva os diots cobertos com o seu suco de cozedura sobre uma cama de polenta fundente.']::text[]),
('entrecote-bordelaise','pt','Entrecosto à bordalesa','Bordéus, França','Um entrecosto grelhado tradicionalmente sobre sarmentos de vinha para lhe dar um aroma fumado subtil, coberto com um molho reduzido de vinho tinto de Bordéus, chalota e tutano de vaca, opulento e encorpado.',ARRAY['Grelhe o entrecosto sobre brasas vivas, idealmente sarmentos de vinha, conforme o ponto desejado.','Deixe a carne repousar sob papel de alumínio uns minutos.','Refogue a chalota finamente picada em um pouco de manteiga.','Desglaceie com vinho tinto, reduza dois terços, junte o caldo de vaca e o tutano em cubos, deixe derreter.','Monte o molho com manteiga fria fora do lume, cubra o entrecosto fatiado e sirva de imediato.']::text[]),
('tripes-mode-de-caen','pt','Tripas à moda de Caen','Caen, Normandia, França','Tripas de vaca cozinhadas oito horas em sidra e calvados com pé de vitela para a gelatina, numa panela de barro selada com massa, receita normanda outrora elogiada até à mesa de Luís XIV.',ARRAY['Limpe bem as tripas, corte-as em quadrados regulares.','Disponha tripas e pé de vitela cortado numa grande panela de barro com cenoura, cebola, alho-francês e louro.','Molhe com sidra e calvados, feche hermeticamente com um cordão de massa de farinha e água.','Leve ao forno a temperatura muito baixa 90 °C durante 8 horas sem abrir.','Quebre o selo de massa à mesa, desengordure levemente a superfície e sirva a escaldar em pratos fundos.']::text[]),
('pot-au-feu','pt','Pot-au-feu','Paris, França','Um caldo claro de vaca cozinhado durante horas com osso de tutano, cenoura, alho-francês e nabo, servido em dois serviços sucessivos — primeiro o caldo com aletria, depois a carne e os legumes — pilar da mesa francesa há séculos.',ARRAY['Mergulhe a vaca e o osso de tutano numa grande panela de água fria, leve lentamente a ferver escumando.','Espete a cebola com cravinho, junte com cenoura, alho-francês e nabo, cozinhe tapado 3 horas em lume brando.','Verifique a maciez da carne com garfo, deve soltar-se facilmente.','Coe parte do caldo, coza nele a aletria para o primeiro serviço.','Sirva a carne e os legumes como segundo serviço com sal grosso, pickles e mostarda.']::text[]),
('rougail-saucisse','pt','Rougail de salsicha','Saint-Denis, Reunião, França','Salsichas fumadas cozinhadas num molho de tomate com gengibre, alho e malagueta, o prato quotidiano mais consumido da Reunião, servido com arroz branco e grãos — lentilhas ou feijão vermelho.',ARRAY['Escalde as salsichas fumadas 5 minutos em água a ferver para retirar o excesso de gordura, escorra.','Refogue cebola, alho e gengibre em lâminas até perfumados.','Junte tomate triturado, tomilho e malagueta, cozinhe 10 minutos num molho espesso.','Junte as salsichas escaldadas cortadas em pedaços, cozinhe tapado 25 minutos.','Coza arroz e lentilhas à parte, sirva o rougail com ambos como acompanhamento.']::text[]),
('colombo-de-poulet','pt','Colombo de frango','Fort-de-France, Martinica, França','Um caril de frango com especiarias colombo, mistura indiana trazida pelos trabalhadores contratados tâmiles do século XIX, cozinhado com batata, beringela e um fio de sumo de lima, prato crioulo que se tornou emblema da Martinica.',ARRAY['Esfregue os pedaços de frango com especiarias colombo, marine 1 hora.','Refogue cebola e alho em lâminas, junte o frango marinado, doure.','Junte batata e beringela em pedaços, molhe com água e leite de coco.','Junte a malagueta scotch bonnet inteira sem furar para aromatizar sem picar demasiado, cozinhe 30 minutos.','Retire a malagueta, regue com um fio de sumo de lima e sirva com arroz branco.']::text[]),
('accras-de-morue','pt','Accras de bacalhau','Pointe-à-Pitre, Guadalupe, França','Pequenos bolinhos de bacalhau dessalgado e desfiado numa massa realçada com malagueta e cebolinho, fritos até uma crosta dourada irregular, aperitivo imprescindível em toda festa familiar das Caraíbas.',ARRAY['Dessalgue o bacalhau 24 horas, mudando a água, desfie fino sem cozer.','Prepare uma massa de bolinho com farinha, fermento, ovo e água morna, deixe levedar 30 minutos.','Incorpore o bacalhau desfiado, cebolinho, malagueta e alho picados.','Forme bolinhas com colher, deslize diretamente em óleo quente a 180 °C.','Frite até douradas e infladas, escorra em papel absorvente e sirva quente como aperitivo.']::text[]),
('beef-stroganoff','pt','Vaca Stroganoff','São Petersburgo, Rússia','Finas tiras de vaca seladas rapidamente e cobertas com um molho de natas smetana e mostarda, prato criado no século XIX para a mesa do conde Stroganov, suficientemente simples para se tornar um clássico mundial.',ARRAY['Corte a vaca em tiras finas e regulares.','Refogue cebola em lâminas e cogumelos em manteiga até dourados, reserve.','Sele as tiras de vaca em lume muito forte apenas uns segundos de cada lado.','Devolva a cebola e os cogumelos, junte natas smetana, mostarda e um pouco de caldo, misture fora do lume forte.','Aqueça sem ferver para não talhar as natas, sirva de imediato com batatas salteadas.']::text[]),
('olivier-salad','pt','Salada Olivier','Moscovo, Rússia','Uma salada de batata, cenoura, ervilhas, pickles e carne em cubos ligados com maionese, criada por um chef belga de Moscovo cuja receita exata permaneceu secreta, hoje o prato imprescindível do Ano Novo russo.',ARRAY['Coza batata, cenoura e ovos separadamente em água até macios, deixe arrefecer.','Corte batata, cenoura, ovos cozidos, pickles e carne em cubinhos regulares.','Reúna todos os cubos numa tigela grande com as ervilhas.','Junte a maionese e um toque de mostarda, misture com cuidado para cobrir bem sem esmagar.','Reserve no frio pelo menos 2 horas antes de servir, idealmente a noite toda para os sabores se misturarem.']::text[]),
('pelmeni-sibirskie','pt','Pelmeni siberianos','Irkutsk, Sibéria, Rússia','Pequenos dumplings de vaca e porco misturados, fechados à mão e depois congelados em grandes quantidades ao ar livre no frio siberiano, reserva de inverno que se escalfava conforme a necessidade durante os longos meses gelados.',ARRAY['Amasse farinha, ovo, água e sal numa massa firme, repouse 30 minutos sob um pano.','Misture vaca e porco picados com cebola ralada, sal e pimenta num recheio homogéneo.','Estenda a massa fina, corte círculos, recheie e dobre apertando firme as bordas em forma de orelhinha.','Congele os pelmeni crus em tabuleiro enfarinhado se preparar reserva.','Escalfe em água a ferver com sal 8 minutos até flutuarem, sirva com natas smetana e endro.']::text[]),
('syrniki','pt','Syrniki','Suzdal, Anel Dourado, Rússia','Pequenos bolinhos dourados de tvorog, esse queijo fresco granulado russo semelhante ao requeijão, misturado com ovo e um pouco de farinha, servidos quentes com natas smetana e compota de bagas ao pequeno-almoço.',ARRAY['Esmague o tvorog com garfo para tirar os grumos grandes.','Incorpore ovo, açúcar, baunilha e a maior parte da farinha numa massa macia mas firme.','Forme pequenos bolinhos redondos, passe levemente pelo resto da farinha.','Doure em manteiga em lume médio, 3 minutos de cada lado até crosta dourada.','Sirva quente com natas smetana e compota de bagas ao lado.']::text[]),
('blini-ikra','pt','Blinis com caviar','Veliki Novgorod, Rússia','Pequenas panquecas grossas de trigo-sarraceno levedadas, macias e ligeiramente ácidas, cobertas com natas smetana e ovas de salmão ou esturjão, prato festivo que acompanhava tradicionalmente as celebrações da Maslenitsa.',ARRAY['Dissolva o fermento em um pouco de leite morno, deixe espumar 10 minutos.','Misture farinhas de trigo-sarraceno e de trigo, incorpore o fermento, o resto do leite morno e os ovos batidos numa massa lisa.','Deixe a massa levedar 45 minutos em local morno até duplicar.','Coza pequenas panquecas grossas em frigideira untada, 2 minutos de cada lado até douradas.','Sirva morno com natas smetana e uma colher de ovas de salmão em cada blini.']::text[]),
('okroshka','pt','Okroshka','Yaroslavl, Anel Dourado, Rússia','Uma sopa fria de verão de legumes crus, ovo cozido e carne em cubos, coberta com kvas fermentado ligeiramente efervescente ou kefir, servida gelada para refrescar nos raros dias quentes do curto verão russo.',ARRAY['Corte pepino, ovos cozidos, carne e rabanete em cubinhos muito regulares.','Pique fino cebolinho e endro.','Reúna todos os ingredientes cortados numa tigela grande, misture.','Deite o kvas frio por cima até cobrir generosamente, junte uma colher de mostarda diluída.','Junte uma colher de natas smetana em cada tigela individual, sirva de imediato bem gelado.']::text[]),
('shchi','pt','Chtchi','Vladimir, Anel Dourado, Rússia','Uma sopa de couve fresca ou fermentada cozinhada com carne de porco e raízes, o prato quotidiano mais antigo da mesa russa, sobre o qual um velho ditado afirma que ela e a kasha, a papa, são a nossa comida.',ARRAY['Coza o porco em pedaços em bastante água 1 hora até macio, escume com regularidade.','Junte cebola e cenoura em lâminas, cozinhe 15 minutos.','Junte couve fermentada e batata em cubos, cozinhe mais 25 minutos.','Tempere com louro, corrija o sal conforme a acidez da couve.','Sirva a escaldar com uma colher de natas smetana e endro fresco picado em cada tigela.']::text[]),
('ukha','pt','Ukha','Astracã, delta do Volga, Rússia','Uma sopa de peixe clara e límpida, nunca engrossada nem turva, preparada tradicionalmente com vários peixes diferentes incluindo o esturjão do delta do Volga, realçada com um toque de vodca mesmo antes de servir.',ARRAY['Escalfe o peixe inteiro em água com cebola inteira e louro 20 minutos, escume com cuidado para manter o caldo claro.','Retire o peixe, desfie a carne retirando pele e espinhas, coe o caldo.','Reaqueça o caldo coado, junte batata e cenoura em pedaços, cozinhe 15 minutos.','Devolva o peixe desfiado ao caldo, reaqueça sem ferver.','Junte um fio de vodca mesmo antes de servir, polvilhe endro fresco.']::text[]),
('kulebyaka','pt','Kulebiaka','Pskov, Rússia','Um pastel em massa folhada longo e dourado que encerra várias camadas distintas de peixe, arroz, ovo cozido e cogumelos, cada uma separada por uma fina panqueca para evitar que a humidade encharque a massa.',ARRAY['Coza o arroz até macio, coza os ovos duros, refogue cogumelos e cebola em lâminas.','Prepare panquecas finas com farinha, ovo, leite e um pouco de manteiga derretida.','Estenda a massa folhada num grande retângulo, disponha ao centro uma panqueca e depois uma camada de arroz.','Sobreponha camada de salmão, panqueca, cogumelos, ovo cozido em fatias e endro, separando cada camada com uma panqueca.','Feche a massa num longo pastel dourado, leve ao forno 35 minutos a 200 °C até bem dourado, deixe repousar antes de fatiar.']::text[]),
('solyanka','pt','Solianka','Tula, Rússia','Uma sopa picante e ácida que mistura vários tipos de carnes fumadas e enchidos curados, azeitonas, alcaparras e pepinos em conserva, de sabores contrastantes pensados como remédio revigorante depois de uma noite demasiado regada.',ARRAY['Refogue cebola em lâminas em um pouco de gordura de toucinho.','Junte as várias carnes cortadas em tiras e o concentrado de tomate, refogue 5 minutos.','Molhe com água ou caldo, junte pickles em rodelas, azeitonas e alcaparras, cozinhe 25 minutos.','Corrija a acidez com um pouco de salmoura de pickle se necessário.','Sirva a escaldar com uma rodela de limão e uma colher de natas smetana em cada tigela.']::text[]),
('chak-chak','pt','Chak-chak','Kazan, Tartaristão, Rússia','Pequenos pedaços de massa fritos até dourados e depois unidos com mel quente, moldados numa pirâmide decorativa, bolo festivo tártaro apresentado infalivelmente em casamentos e nascimentos.',ARRAY['Amasse farinha, ovos, açúcar e uma pitada de sal numa massa firme, repouse 20 minutos.','Estenda a massa fina, corte em tiras finas e depois em pedaços pequenos irregulares do tamanho de uma ervilha.','Frite os pedaços em pequenas quantidades em óleo quente a 180 °C até dourados e inflados.','Aqueça o mel até fluido sem deixar caramelizar.','Misture os pedaços fritos escorridos com o mel quente, forme de imediato uma pirâmide numa travessa, deixe endurecer antes de servir.']::text[]),
('azu-po-tatarski','pt','Azu à tártara','Naberejnie Tchelny, Tartaristão, Rússia','Tiras de vaca cozinhadas com pepinos em conserva e batata num molho de tomate condimentado, especialidade tártara onde a acidez dos pickles corta a riqueza da carne cozinhada longamente.',ARRAY['Corte a vaca em tiras grossas, doure vigorosamente numa panela.','Junte cebola em lâminas, refogue até translúcida.','Junte concentrado de tomate e caldo, cozinhe tapado 40 minutos até macia.','Junte batata em quartos e pickles em tiras, cozinhe mais 20 minutos.','Junte o alho esmagado no final da cozedura, corrija o tempero e sirva a escaldar.']::text[]),
('pirozhki','pt','Pirojki','Rostov do Don, Rússia','Pequenos pastéis de massa levedada recheados com carne, couve ou batata, fritos ou assados, outrora vendidos aos gritos em estações e cais, lanche de viagem por excelência em toda a Rússia.',ARRAY['Amasse farinha, fermento, leite morno, ovo e sal numa massa macia, deixe levedar 1 hora.','Refogue vaca picada ou couve em lâminas com cebola para o recheio escolhido, deixe amornar.','Divida a massa em bolas, achate cada uma num disco, recheie.','Feche em pastel apertando bem as bordas para selar.','Frite em óleo quente até dourados ou leve ao forno 20 minutos a 190 °C, sirva quente.']::text[]),
('kholodets','pt','Kholodets','Níjni Novgorod, Rússia','Uma gelatina fria de porco cozinhada tão longamente que o colagénio de patas e jarretes se transforma naturalmente em aspic, sem gelatina adicionada, servida fatiada com rábano picante ou mostarda forte.',ARRAY['Demolhe as patas e jarretes de porco umas horas, escove bem.','Coza em bastante água em lume muito brando 6 horas com cebola, cenoura e louro, sem nunca ferver forte.','Escume com regularidade, sale no final da cozedura.','Desfie a carne cozida, disponha com alho esmagado no fundo de formas ou uma travessa.','Coe o caldo rico em colagénio, deite sobre a carne, deixe solidificar no frigorífico pelo menos 8 horas, desenforme e sirva com rábano picante.']::text[]),
('shashlyk-kubanskiy','pt','Shashlik do Kuban','Krasnodar, Kuban, Rússia','Cubos de porco marinados a noite toda em cebola, vinagre e especiarias, grelhados em largos espetos planos sobre brasas de madeira frutífera, tradição festiva do sul fértil da Rússia perto do Cáucaso.',ARRAY['Corte o porco em cubos grandes e regulares.','Misture com cebola em rodelas grossas, vinagre, louro, pimenta e coentros esmagados.','Deixe marinar a noite toda no frio, mexendo de vez em quando.','Enfie os cubos em largos espetos planos alternando com rodelas de cebola marinada.','Grelhe sobre brasas vivas 12 a 15 minutos virando com regularidade, sirva com as cebolas grelhadas.']::text[]),
('pozy-buryatskie','pt','Pozy buriatos','Ulan-Ude, Buriácia, Rússia','Grandes dumplings a vapor mongol-buriatos fechados numa coroa plissada com exatamente vinte e cinco dobras, recheados com carne gorda e cebola, dos quais primeiro se sorve o suco a escaldar por um buraquinho antes de morder.',ARRAY['Amasse farinha, água e sal numa massa firme, repouse 30 minutos.','Misture vaca e porco picados grosso com cebola muito finamente picada e um pouco de água para um recheio suculento.','Estenda a massa, corte círculos bastante grandes, recheie generosamente.','Feche numa coroa plissada apertando as bordas à volta, deixando um buraquinho no topo.','Cozinhe a vapor 18 minutos, deixe amornar 2 minutos, sorva o suco pelo buraco antes de comer o resto.']::text[]),
('stroganina','pt','Stroganina','Yakutsk, Iacútia, Rússia','Um peixe de água doce congelado até ao coração pelo frio extremo da Iacútia, raspado em lascas finas como papel com faca diretamente à mesa, molhado numa mistura de sal e pimenta, comido de imediato antes de descongelar.',ARRAY['Use um peixe de água doce completamente congelado, nunca antes descongelado.','Segure o peixe congelado firmemente envolto num pano para pega.','Raspe lascas muito finas com uma faca bem afiada, diretamente sobre um prato frio.','Misture sal fino e pimenta preta moída na hora num pratinho.','Molhe cada lasca de peixe congelado no sal e pimenta mesmo antes de comer, enquanto ainda está duro e frio.']::text[]),
('medovik','pt','Medovik','Smolensk, Rússia','Um bolo de camadas finas de massa de mel empilhadas com natas smetana aveludadas, deixado repousar a noite toda para as camadas amaciarem absorvendo as natas, nascido de um pasteleiro que queria agradar a uma czarina que detestava mel.',ARRAY['Derreta mel, manteiga e açúcar em banho-maria, junte o bicarbonato fora do lume até espumar.','Incorpore os ovos batidos e depois a farinha gradualmente numa massa macia ainda quente.','Divida em 8 bolas, estenda cada uma muito fina, coza cada disco 4 minutos a 200 °C até dourado.','Bata as natas smetana com o açúcar em pó até aveludadas.','Empilhe os discos barrando natas entre cada um, reserve no frio a noite toda antes de servir fatiado.']::text[]),
('pashka','pt','Pashka','Kostroma, Anel Dourado, Rússia','Uma sobremesa fria de tvorog, manteiga e fruta cristalizada prensada num molde piramidal de madeira marcado com as letras XB, símbolo pascal ortodoxo abençoado na igreja antes de ser servido em finas fatias na manhã de Páscoa.',ARRAY['Passe o tvorog por um peneiro fino para uma textura perfeitamente lisa.','Bata a manteiga amolecida com o açúcar até cremosa, incorpore as gemas uma a uma.','Misture com o tvorog peneirado, as natas smetana e a baunilha.','Incorpore fruta cristalizada e amêndoas trituradas à preparação.','Forre uma forma piramidal com pano limpo, encha e prense firme, refrigere sob peso 24 horas antes de desenformar.']::text[]),
('rassolnik','pt','Rassolnik','Perm, Urais, Rússia','Uma sopa ácida de pepinos em conserva e cevada em pérolas, cuja acidez da salmoura de pickle adicionada no final da cozedura contrasta com a maciez dos rins de porco ou vaca tradicionalmente usados.',ARRAY['Demolhe os rins em leite 1 hora para tirar o cheiro forte, enxague e corte em cubos.','Coza a cevada em pérolas à parte até macia.','Refogue rins, cebola e cenoura, molhe com água, cozinhe 25 minutos.','Junte batata, pickles em cubos e cevada cozida, cozinhe mais 15 minutos.','Junte salmoura de pickle no final conforme a acidez desejada, polvilhe endro e sirva a escaldar.']::text[]),
('vareniki-vishnya','pt','Vareniki de cereja','Voronej, Rússia','Grandes dumplings doces recheados com cerejas sem caroço maceradas em açúcar, escalfados e servidos mornos cobertos com natas smetana, sobremesa de verão que tinge a massa de um rosa suave durante a cozedura.',ARRAY['Amasse farinha, ovo, água e uma pitada de sal numa massa macia, repouse 30 minutos.','Retire os caroços das cerejas, misture com açúcar, deixe macerar 20 minutos para soltarem o suco.','Estenda a massa fina, corte círculos bastante largos.','Recheie cada círculo com umas cerejas escorridas, feche apertando firme as bordas em meia-lua.','Escalfe em água a ferver 6 minutos até flutuarem, escorra e sirva com manteiga derretida e natas smetana.']::text[]),
('gurievskaya-kasha','pt','Kacha Gúrievskaya','Saratov, região do Volga, Rússia','Uma papa de sêmola doce montada em camadas sucessivas com a nata cremosa que se forma na superfície do leite aquecido no forno, polvilhada com fruta seca e nozes, sobremesa imperial do século XIX batizada em homenagem a um ministro das Finanças guloso.',ARRAY['Deite o leite num tabuleiro largo para forno, leve ao forno a baixa temperatura até se formar uma nata cremosa na superfície, retire-a com cuidado e repita várias vezes.','Coza a sêmola no resto do leite açucarado até engrossar, aromatize com baunilha.','Disponha uma camada de sêmola num tabuleiro, cubra com as natas de leite reservadas e fruta seca triturada.','Repita as camadas alternando sêmola, natas de leite e fruta seca até esgotar.','Regue com mel quente, leve uns minutos ao grelhador para caramelizar levemente a superfície, sirva morno.']::text[])
insert into public.atlas_dish_texts (dish_id,lang,name,place,description,steps) values
('lobster-roll','pt','Lobster roll','Portland, Maine, EUA','Carne de lagosta recém-descascada, apenas ligada com maionese ou simplesmente manteiga derretida conforme a escola, empilhada num pãozinho de cachorro-quente tostado nos lados, sanduíche de verão emblemática do Maine.',ARRAY['Coza a lagosta em água a ferver com sal 10 minutos, deixe arrefecer e descasque.','Corte a carne em pedaços grandes e regulares.','Misture com cuidado com maionese, aipo finamente picado e um fio de limão.','Toste os pãezinhos amanteigados em ambos os lados cortados até dourados.','Recheie generosamente cada pãozinho com carne de lagosta, polvilhe cebolinho e sirva de imediato.']::text[]),
('buffalo-wings','pt','Asas Buffalo','Buffalo, estado de Nova Iorque, EUA','Asas de frango fritas simples e depois cobertas com um molho ardente de manteiga e picante, nascidas em 1964 num bar de Buffalo para aproveitar uma entrega inesperada, servidas com aipo e molho de queijo azul para acalmar o fogo.',ARRAY['Seque bem as asas de frango, frite em óleo quente 12 minutos até bem douradas e crocantes.','Derreta a manteiga, misture-a ao molho picante ainda quente para emulsionar.','Escorra as asas fritas, mergulhe-as no molho a escaldar mexendo para cobrir bem.','Prepare o molho de queijo azul misturando queijo azul esfarelado, natas azedas e um pouco de vinagre.','Sirva as asas de imediato com aipo e o molho de queijo azul à parte.']::text[]),
('deep-dish-pizza','pt','Pizza deep dish','Chicago, Illinois, EUA','Uma pizza grossa assada numa forma de bordo alto como uma tarte, montada ao contrário com o queijo sob o molho de tomate para evitar que queime durante os 35 minutos de forno necessários, especialidade nascida em Chicago nos anos 1940.',ARRAY['Amasse farinha, sêmola de milho, fermento, azeite e água morna numa massa macia, deixe levedar 1 hora.','Estenda a massa grossa numa forma de bordo alto bem untada, subindo pelas laterais.','Disponha mozzarela em fatias diretamente sobre a massa.','Junte salsicha esfarelada cozida, depois o molho de tomate espesso temperado com orégãos por cima.','Leve ao forno 30 a 35 minutos a 220 °C até crosta dourada, polvilhe parmesão e deixe repousar 10 minutos antes de cortar.']::text[]),
('chicago-hot-dog','pt','Cachorro-quente de Chicago','Chicago, Illinois, EUA','Uma salsicha de vaca escalfada aninhada num pãozinho de sementes de papoila, coberta com uma lista precisa e intocável de sete condimentos — mostarda, cebola, relish verde vivo, tomate, pickle, malagueta suave e sal de aipo — nunca ketchup.',ARRAY['Escalfe as salsichas de vaca em água a fervilhar 6 minutos sem ferver forte.','Aqueça os pãezinhos de sementes de papoila a vapor para amolecer levemente.','Coloque cada salsicha num pãozinho, regue mostarda em zigue-zague.','Cubra pela ordem com cebola finamente picada, relish verde, gomos de tomate, um pickle inteiro em tira.','Termine com uma pitada de sal de aipo e uma malagueta suave, sirva de imediato sem nunca adicionar ketchup.']::text[]),
('crab-cakes-maryland','pt','Crab cakes de Maryland','Baltimore, Maryland, EUA','Bolinhos de carne de caranguejo azul da baía de Chesapeake, apenas ligados com pão ralado e maionese para deixar dominar o caranguejo, dourados em frigideira, temperados com a mistura de especiarias Old Bay emblemática de Maryland.',ARRAY['Verifique bem a carne de caranguejo para retirar fragmentos de casca.','Misture com cuidado com pão ralado, maionese, ovo, mostarda e tempero Old Bay, sem trabalhar demais para manter pedaços grandes.','Forme bolinhos grossos à mão, reserve no frio 30 minutos para se manterem.','Doure os bolinhos em manteiga em lume médio, 4 minutos de cada lado.','Polvilhe salsa fresca e sirva com um gomo de limão e molho tártaro.']::text[]),
('shrimp-and-grits','pt','Camarão e grits','Charleston, Carolina do Sul, EUA','Uma papa de milho cremosa com queijo e manteiga, coroada com camarão salteado com toucinho e especiarias cajun, prato de pescadores do Lowcountry elevado em poucas décadas a especialidade gastronómica nacional.',ARRAY['Leve o leite a ferver, incorpore os grits em fio batendo para evitar grumos.','Cozinhe em lume brando 20 minutos mexendo com regularidade até cremoso, incorpore queijo cheddar e manteiga.','Frite o toucinho em cubos até crocante, reserve.','Salteie o camarão temperado com cajun e alho na gordura de toucinho até rosado, 4 minutos.','Sirva o camarão e o toucinho sobre os grits cremosos, polvilhe cebolinho picado.']::text[]),
('kentucky-hot-brown','pt','Kentucky Hot Brown','Louisville, Kentucky, EUA','Uma sanduíche aberta de peru coberta com molho mornay de queijo, gratinada no forno com toucinho crocante e tomate, inventada nos anos 1920 por um chef de hotel em Louisville para alimentar dançarinos famintos depois da meia-noite.',ARRAY['Faça um roux com manteiga e farinha, molhe com leite quente batendo até molho liso e espesso.','Incorpore o gruyère ralado fora do lume até derreter, tempere.','Disponha uma fatia de pão num prato individual, cubra com fatias grossas de peru.','Cubra generosamente com molho mornay, junte rodelas de tomate e parmesão ralado por cima.','Leve ao grelhador uns minutos até dourado e a borbulhar, decore com toucinho crocante e sirva de imediato a escaldar.']::text[]),
('chicken-and-waffles','pt','Frango e waffles','Harlem, Nova Iorque, EUA','Frango frito extra-crocante colocado diretamente sobre um waffle macio, regado com xarope de ácer que contrasta doce e salgado, prato nascido nos clubes de jazz do Harlem onde se comia entre o jantar tardio e o pequeno-almoço.',ARRAY['Marine o frango em leitelho pelo menos 4 horas.','Escorra, passe por farinha temperada com caiena, frite a 175 °C 15 minutos até dourado e crocante.','Prepare a massa de waffle misturando farinha, ovos, leite e manteiga derretida.','Coza os waffles em máquina quente até dourados e crocantes.','Coloque o frango frito sobre os waffles quentes, regue generosamente com xarope de ácer e sirva de imediato.']::text[]),
('new-york-cheesecake','pt','Cheesecake de Nova Iorque','Nova Iorque, EUA','Um cheesecake denso e liso à base de cream cheese, assado em banho-maria sobre uma fina base de bolacha esfarelada, cuja textura alta e compacta contrasta radicalmente com as versões mais leves da Europa.',ARRAY['Triture as bolachas em migalhas finas, misture com manteiga derretida e prense no fundo de uma forma desmontável.','Bata o cream cheese até liso, incorpore o açúcar gradualmente.','Junte os ovos um a um batendo pouco para não incorporar demasiado ar, depois as natas, a baunilha e a raspa de limão.','Deite sobre a base, leve ao forno em banho-maria 55 minutos a 160 °C até apenas trémulo ao centro.','Deixe arrefecer no forno desligado com a porta entreaberta, depois refrigere pelo menos 6 horas antes de desenformar.']::text[]),
('pastrami-on-rye','pt','Pastrami on rye','Manhattan, Nova Iorque, EUA','Peito de vaca curado em salmoura condimentada e depois fumado longamente e cozido a vapor, cortado grosso e empilhado alto entre duas fatias de pão de centeio, herança dos delicatessens judaicos da Europa de Leste.',ARRAY['Esfregue o peito com sal grosso, alho esmagado e especiarias, cure no frio 5 dias, virando todos os dias.','Enxague bem, cubra com uma crosta grossa de pimenta e coentros triturados.','Fume a frio várias horas e depois a quente até formar uma crosta negra.','Cozinhe a vapor 3 horas até extremamente macio.','Corte muito fino contra a fibra, empilhe generosamente entre duas fatias de pão de centeio com mostarda, sirva com pickles.']::text[]),
('cuban-sandwich-miami','pt','Sanduíche cubana de Miami','Miami, Flórida, EUA','Porco assado, fiambre, queijo suíço, pickle e mostarda prensados em pão cubano até o queijo derreter e a crosta ficar crocante, sanduíche forjada pelas comunidades cubanas de Ybor City e Miami.',ARRAY['Asse ou reaqueça o porco desfiado ou fatiado.','Abra o pão cubano ao meio, barre mostarda em ambos os lados.','Recheie com porco, fiambre, queijo suíço em fatias e pickles em tiras.','Unte com manteiga o exterior da sanduíche, prense numa chapa ou prensa de panini quente.','Cozinhe 5 minutos pressionando até o queijo derreter e o pão ficar crocante e achatado, corte na diagonal e sirva quente.']::text[]),
('key-lime-pie','pt','Key lime pie','Key West, Flórida, EUA','Uma tarte ácida com o sumo das pequenas limas key lime dos Keys da Flórida, misturado com leite condensado açucarado para engrossar sem cozedura complexa, sobre uma base de bolacha Graham, sobremesa típica do arquipélago tropical.',ARRAY['Triture as bolachas Graham em migalhas finas, misture com manteiga derretida e prense numa forma de tarte.','Leve a base ao forno 10 minutos a 180 °C, deixe arrefecer.','Bata o leite condensado com as gemas e o sumo de lima key lime até espesso e liso.','Deite sobre a base fria, leve ao forno 15 minutos a 160 °C até apenas firme.','Deixe arrefecer e refrigere pelo menos 3 horas, sirva com natas batidas.']::text[]),
('sonoran-hot-dog','pt','Cachorro-quente sonorense','Tucson, Arizona, EUA','Uma salsicha envolta em toucinho e grelhada até crocante, aninhada num pão macio estilo bolillo e coberta com feijão pinto, cebola, tomate e um molho cremoso de jalapeño, especialidade nascida na fronteira com o México.',ARRAY['Envolva cada salsicha com uma fatia de toucinho em espiral apertada.','Grelhe em lume médio virando com regularidade até o toucinho ficar crocante, cerca de 10 minutos.','Aqueça o feijão pinto esmagado grosseiramente.','Triture jalapeño e maionese para o molho cremoso picante.','Recheie o pão quente com feijão, salsicha envolta em toucinho, cebola e tomate em cubos, termine com um fio de molho de jalapeño.']::text[]),
('fish-tacos-baja','pt','Tacos de peixe estilo Baja','San Diego, Califórnia, EUA','Peixe branco panado em cerveja e depois frito crocante, enrolado numa tortilha de milho quente com couve finamente cortada e um molho cremoso picante, prato nascido da pesca transfronteiriça entre San Diego e a Baixa Califórnia mexicana.',ARRAY['Misture farinha e cerveja fria numa massa leve e espumosa.','Corte o peixe em tiras, mergulhe na massa de cerveja.','Frite em óleo quente a 180 °C até dourado e crocante, escorra em papel absorvente.','Triture maionese e chipotle para o molho cremoso picante.','Recheie as tortilhas quentes com couve cortada, peixe frito e molho chipotle, regue com um fio de lima.']::text[]),
('cioppino','pt','Cioppino','San Francisco, Califórnia, EUA','Um ensopado de peixe e marisco variado num caldo de tomate e vinho branco, nascido dos pescadores imigrantes italianos de Fisherman''s Wharf que juntavam o não vendido do dia numa mesma grande panela.',ARRAY['Refogue cebola e alho em lâminas em azeite até translúcidos.','Junte tomate triturado e vinho branco, cozinhe 15 minutos numa base perfumada.','Junte o caldo de peixe, leve a lume brando.','Junte o peixe em pedaços primeiro, depois caranguejo, camarão, mexilhões e amêijoas conforme o tempo de cozedura.','Cozinhe 12 minutos até todos os mariscos abrirem, sirva a escaldar com pão estaladiço.']::text[]),
('wisconsin-cheese-curds','pt','Cheese curds fritos de Wisconsin','Madison, Wisconsin, EUA','Pequenos grãos de queijo fresco que rangem sob o dente, panados e depois fritos até formar uma crosta dourada que aprisiona um interior derretido, especialidade da feira do condado de Wisconsin, o principal estado leiteiro dos EUA.',ARRAY['Tire os cheese curds do frigorífico 20 minutos antes de panar para ficarem à temperatura ambiente.','Prepare três pratos: farinha, ovo batido com leite, pão ralado temperado com colorau.','Passe cada grão de queijo por farinha, depois ovo, depois pão ralado, pressionando bem para aderir.','Frite em óleo quente a 190 °C em pequenas quantidades, só 1 a 2 minutos até dourados sem deixar o queijo derreter por completo.','Escorra em papel absorvente e sirva de imediato a escaldar, o queijo deve continuar a ranger sob o dente.']::text[]),
('minnesota-hotdish','pt','Hotdish do Minnesota','Minneapolis, Minnesota, EUA','Um gratinado reconfortante de vaca picada, feijão-verde e sopa de cogumelos enlatada, coroado com chips de cebola crocantes, prato de refeição comunitária próprio da cultura escandinavo-americana do Midwest.',ARRAY['Refogue a vaca picada com a cebola em lâminas até bem dourada.','Disponha a vaca cozinhada no fundo de um tabuleiro grande para forno.','Cubra com feijão-verde e depois sopa de cogumelos espalhada uniformemente.','Junte batata em rodelas finas ou em puré por cima, polvilhe queijo ralado.','Leve ao forno 30 minutos a 190 °C, corone com chips de cebola crocantes nos últimos 10 minutos.']::text[]),
('detroit-coney-dog','pt','Coney dog de Detroit','Detroit, Michigan, EUA','Uma salsicha coberta com chili de vaca sem feijão, mostarda e cebola crua finamente picada, nascida da rivalidade secular entre dois restaurantes vizinhos do centro de Detroit geridos por imigrantes gregos e macedónios.',ARRAY['Refogue a vaca muito fina até quase ficar em pó, sem deixar dourar crocante.','Junte concentrado de tomate, cominho e chili em pó, molhe levemente e cozinhe 20 minutos num chili espesso sem feijão.','Escalfe ou grelhe as salsichas até quentes.','Coloque cada salsicha num pãozinho, cubra generosamente com chili de vaca quente.','Termine com um fio de mostarda e cebola crua finamente picada, sirva de imediato com garfo.']::text[]),
('beignets-nola','pt','Beignets estilo Café du Monde','Nova Orleães, Luisiana, EUA','Quadrados de massa levedada fritos até incharem em almofadas douradas, sepultados sob uma espessa neve de açúcar em pó, sobremesa francesa transformada em instituição de Nova Orleães, comida tradicionalmente com café de chicória com leite.',ARRAY['Dissolva o fermento em leite morno, deixe espumar 10 minutos.','Amasse com farinha, ovo, açúcar, manteiga derretida e sal numa massa macia, deixe levedar 1 hora.','Estenda a massa a 1 cm de espessura, corte em quadrados regulares de cerca de 8 cm.','Frite em óleo quente a 180 °C até bem inflados e dourados de ambos os lados.','Escorra e cubra de imediato com uma grossa camada de açúcar em pó, sirva quente.']::text[]),
('shoofly-pie','pt','Shoofly pie','Lancaster, Pensilvânia, EUA','Uma tarte de melaço extremamente doce coroada com um crumble de farinha e manteiga, herança das comunidades amish e menonitas da Pensilvânia, cujo nome viria das moscas que era preciso enxotar da tarte a arrefecer no parapeito da janela.',ARRAY['Misture farinha, açúcar mascavado e manteiga fria com as pontas dos dedos até um crumble grosso.','Dissolva o melaço, o bicarbonato e o ovo em água quente até homogéneo.','Forre uma forma de tarte com massa quebrada, deite metade do crumble no fundo.','Deite a mistura de melaço por cima, cubra com o resto do crumble.','Leve ao forno 35 minutos a 190 °C até o centro apenas tremer, deixe arrefecer antes de servir.']::text[]),
('peach-cobbler-georgia','pt','Cobbler de pêssego da Geórgia','Atlanta, Geórgia, EUA','Pêssegos maduros e sumarentos do estado apelidado Peach State, cozinhados com açúcar e canela sob uma massa de bolacha que incha ao assar numa tampa irregular e dourada, sobremesa de final de verão servida morna com uma bola de gelado de baunilha.',ARRAY['Descasque e corte os pêssegos, misture com metade do açúcar e a canela, deixe macerar 15 minutos.','Disponha os pêssegos e o seu suco num tabuleiro untado para forno.','Misture farinha, resto do açúcar, fermento, manteiga derretida, leite e baunilha numa massa de bolacha espessa.','Deite a massa sobre os pêssegos sem espalhar por completo, deixando zonas de fruta à mostra.','Leve ao forno 40 minutos a 190 °C até dourado e a borbulhar, sirva morno com uma bola de gelado de baunilha.']::text[]),
('king-crab-alaska','pt','Caranguejo real do Alasca','Anchorage, Alasca, EUA','Enormes patas de caranguejo real das águas geladas do Alasca, já pré-cozidas no mar em navios-fábrica logo após a captura, simplesmente reaquecidas a vapor e servidas com manteiga derretida, uma das pescas mais perigosas do mundo.',ARRAY['Tire as patas de caranguejo real, já pré-cozidas, do congelador para descongelar levemente.','Aqueça uma grande panela de água com cesto de vapor.','Reaqueça as patas a vapor 8 a 10 minutos até bem quentes por dentro.','Derreta a manteiga com alho esmagado e um pouco de sumo de limão.','Parta as cascas com um quebra-nozes, sirva com a manteiga de alho quente e gomos de limão.']::text[]),
('tourtiere','pt','Tourtière','Cidade de Quebec, Canadá','Uma empada de porco picado condimentada com canela e cravinho, encerrada numa massa quebrada dourada, prato imprescindível da consoada quebequense transmitido de geração em geração desde a Nova França.',ARRAY['Refogue o porco picado com cebola e alho até bem dourado.','Junte batata ralada, canela e cravinho, molhe com caldo.','Cozinhe tapado 25 minutos até engrossar e a batata se fundir no recheio.','Forre uma forma com massa quebrada, recheie com o recheio frio, cubra com um segundo disco de massa selando as bordas.','Leve ao forno 40 minutos a 190 °C até dourado, sirva quente com ketchup de fruta caseiro.']::text[]),
('soupe-aux-pois-quebec','pt','Sopa de ervilha quebequense','Trois-Rivières, Quebec, Canadá','Uma sopa espessa de ervilha amarela partida cozinhada durante horas com toucinho salgado, tão substancial que valeu aos canadenses franceses a alcunha zombeteira de «comedores de ervilha» por parte dos vizinhos anglófonos.',ARRAY['Demolhe a ervilha partida a noite toda, escorra.','Coza o toucinho salgado em bastante água 30 minutos, escume.','Junte ervilha partida, cebola espetada com cravinho, cenoura e louro.','Cozinhe tapado 2h30 em lume brando mexendo de vez em quando, até a ervilha se desfazer numa sopa espessa.','Retire a cebola e o louro, desfie o toucinho na sopa, sirva a escaldar com pão caseiro.']::text[]),
('donair-halifax','pt','Donair de Halifax','Halifax, Nova Escócia, Canadá','Carne de vaca condimentada ao estilo kebab grego, cortada fina e enrolada em pão pita, mas coberta com um molho doce inédito de leite condensado, vinagre e alho — invenção local tão amada que se tornou o prato oficial da cidade.',ARRAY['Misture a vaca picada com alho em pó, orégãos e especiarias, prense firme numa forma de pão para formar um bolo de carne compacto.','Leve ao forno 1 hora a 180 °C até bastante firme, deixe arrefecer e corte muito fino.','Frite as fatias em frigideira ou sob o grelhador até crocantes nas bordas.','Prepare o molho misturando leite condensado, vinagre branco e alho esmagado até espesso e liso.','Recheie o pita quente com carne, tomate e cebola, cubra generosamente com o molho doce.']::text[]),
('pei-mussels','pt','Mexilhões da Ilha do Príncipe Eduardo','Charlottetown, Ilha do Príncipe Eduardo, Canadá','Mexilhões azuis cultivados em suspensão nas águas frias e limpas da ilha, abertos em minutos a vapor de vinho branco, chalota e natas, a ilha produz sozinha a maioria dos mexilhões cultivados no Canadá.',ARRAY['Raspe e limpe bem os mexilhões, descarte os que continuarem abertos.','Refogue chalota e alho em lâminas em manteiga até translúcidos.','Junte o vinho branco, leve a ferver.','Junte os mexilhões, tape e cozinhe 6 minutos abanando a panela, até todos abrirem.','Junte as natas, deixe engrossar 1 minuto, polvilhe salsa e sirva de imediato com pão estaladiço.']::text[]),
('jiggs-dinner','pt','Jiggs dinner','St. John''s, Terra Nova, Canadá','Vaca salgada fervida com couve, nabo, cenoura e batata, servida tradicionalmente aos domingos junto a um pudim de ervilha cozinhado à parte num saco de pano, refeição dominical mais emblemática da Terra Nova.',ARRAY['Dessalgue a vaca salgada a noite toda, mudando a água várias vezes.','Demolhe a ervilha partida à parte a noite toda, ate-a num saco de pano.','Coza a vaca em bastante água com louro 2 horas, mergulhe o saco de ervilha no mesmo caldo.','Junte nabo e cenoura, cozinhe 30 minutos, depois couve e batata nos últimos 20 minutos.','Escorra o saco de ervilha, esmague em puré, sirva a vaca fatiada com os legumes e o puré de ervilha ao lado.']::text[]),
('fish-and-brewis','pt','Fish and brewis','Twillingate, Terra Nova, Canadá','Bacalhau salgado e pão duro demolhados separadamente a noite toda e depois reunidos e coroados com scrunchions, torresmos de porco fritos a chiar, prato de subsistência dos pescadores da Terra Nova transformado em imprescindível dominical.',ARRAY['Demolhe o bacalhau salgado e o pão duro separadamente em água fria a noite toda, mudando a água uma vez.','Escalfe o bacalhau demolhado 15 minutos até macio, escorra e desfie.','Coza o pão demolhado em água a fervilhar 10 minutos até amolecido, escorra.','Frite a gordura de porco em cubos até crocante com cebola em lâminas, reserve os scrunchions e a sua gordura.','Misture bacalhau e pão numa travessa, regue com a gordura de porco quente e os scrunchions crocantes, sirva de imediato.']::text[]),
('peameal-bacon-sandwich','pt','Sanduíche de peameal bacon','Toronto, Ontário, Canadá','Uma grossa fatia de lombo de porco desossado curado em salmoura e depois enrolado em sêmola de milho amarela, dourada em frigideira, servida num pãozinho macio — sanduíche nascida no mercado St. Lawrence de Toronto, vendida ao amanhecer aos trabalhadores do mercado.',ARRAY['Cure o lombo de porco em sal, açúcar e água 24 horas no frio.','Enxague e seque, corte em fatias grossas de cerca de 2 cm.','Enrole cada fatia em sêmola de milho amarela pressionando bem para aderir.','Doure as fatias em manteiga em lume médio, 4 minutos de cada lado até bem cozidas.','Recheie um pãozinho macio barrado com mostarda com uma ou duas fatias, sirva quente.']::text[]),
('butter-tarts','pt','Butter tarts','Muskoka, Ontário, Canadá','Pequenas tarteletes com recheio de açúcar mascavado, manteiga e xarope de ácer que borbulha ao assar até ficar pegajoso ao centro e ligeiramente crocante à superfície, um debate nacional sobre as passas que nunca encontrou consenso.',ARRAY['Forre pequenas formas de tarteleta com massa quebrada cortada em círculos.','Distribua umas passas no fundo de cada base para quem gosta.','Derreta a manteiga com o açúcar mascavado e o xarope de ácer até homogéneo, deixe amornar.','Incorpore os ovos batidos e a baunilha, deite o recheio até dois terços em cada base.','Leve ao forno 15 a 18 minutos a 200 °C até o recheio borbulhar e as bordas dourarem, deixe amornar antes de desenformar.']::text[]),
('saskatoon-berry-pie','pt','Tarte de bagas de Saskatoon','Saskatoon, Saskatchewan, Canadá','Uma tarte de bagas púrpuras das pradarias canadianas, semelhantes ao mirtilo mas de sabor mais próximo da amêndoa, colhidas silvestres nas margens do rio que deu nome à cidade, entre duas massas quebradas amanteigadas.',ARRAY['Misture as bagas com açúcar, farinha, sumo de limão e uma pitada de canela.','Forre uma forma com massa quebrada, deite o recheio de bagas.','Espalhe pequenos pedaços de manteiga.','Cubra com um segundo disco de massa, aperte as bordas e faça uns cortes para deixar sair o vapor.','Leve ao forno 40 a 45 minutos a 200 °C até dourada e a borbulhar, deixe arrefecer antes de fatiar.']::text[]),
('perogies-canadian','pt','Perogies canadianos','Winnipeg, Manitoba, Canadá','Grandes dumplings de batata e queijo cheddar herdados dos imigrantes ucranianos das Pradarias, escalfados e depois dourados em manteiga com cebola caramelizada, servidos com uma colher de natas azedas bem frias.',ARRAY['Amasse farinha, ovo, parte das natas azedas e água morna numa massa macia, repouse 30 minutos.','Coza e esmague a batata, misture ainda quente com cheddar ralado até derreter.','Estenda a massa fina, corte círculos, recheie e feche em meia-lua apertando bem as bordas.','Escalfe os perogies em água a ferver com sal 5 minutos até flutuarem.','Doure os perogies escalfados em manteiga com a cebola caramelizada, sirva com o resto das natas azedas.']::text[]),
('alberta-beef-steak','pt','Bife de vaca do Alberta','Calgary, Alberta, Canadá','Um grosso bife de vaca alimentada com pasto das vastas pradarias do Alberta, grelhado simplesmente com sal e pimenta para deixar falar a qualidade da carne, orgulho regional celebrado todos os anos no Calgary Stampede.',ARRAY['Tire o bife do frigorífico 45 minutos antes de cozinhar para ficar à temperatura ambiente.','Tempere generosamente com sal grosso e pimenta triturada em ambos os lados.','Aqueça uma frigideira de ferro em lume muito forte até fumegar.','Sele o bife 3 a 4 minutos de cada lado conforme a espessura, regando com manteiga de alho e tomilho derretida no final.','Deixe repousar 5 minutos sob papel de alumínio antes de cortar e servir.']::text[]),
('nanaimo-bars','pt','Barras de Nanaimo','Nanaimo, Colúmbia Britânica, Canadá','Um quadrado frio de três camadas sem cozedura, base de bolacha esfarelada com coco, creme de pasteleiro de manteiga amarelo-claro e cobertura de chocolate preto estaladiço, sobremesa de uma cidade mineira que se tornou emblema nacional.',ARRAY['Triture as bolachas em migalhas, misture com coco, cacau e manteiga derretida, junte o ovo batido e cozinhe 3 minutos em banho-maria mexendo.','Prense esta mistura numa forma quadrada forrada com papel, refrigere 20 minutos.','Bata manteiga, açúcar em pó e pó para natas até leve, espalhe sobre a base fria.','Refrigere mais 20 minutos até firme.','Derreta o chocolate preto, deite sobre a camada de creme, refrigere até endurecer antes de cortar em quadradinhos.']::text[]),
('bc-spot-prawns','pt','Camarão pintado da Colúmbia Britânica','Vancouver, Colúmbia Britânica, Canadá','Grandes camarões pintados pescados nas águas frias do Pacífico, disponíveis apenas umas semanas por ano na primavera, grelhados inteiros simplesmente na casca para preservar a sua carne doce e delicada.',ARRAY['Deixe os camarões inteiros com a casca, não descasque.','Misture azeite, alho esmagado e malagueta em lâminas, pincele generosamente os camarões.','Aqueça uma grelha ou chapa em lume forte.','Grelhe os camarões 2 minutos de cada lado até a casca ficar rosada e a carne opaca.','Regue com um fio de limão, polvilhe salsa e sirva de imediato, para descascar com os dedos.']::text[]),
('arctic-char-grilled','pt','Salvelino ártico grelhado','Iqaluit, Nunavut, Canadá','Um peixe das águas geladas do Ártico canadiano, primo do salmão de carne rosa-alaranjada delicada, pescado por comunidades inuítes e simplesmente grelhado inteiro em fogo de lenha com sal, deixando falar a sua frescura excecional.',ARRAY['Limpe e enxague o peixe inteiro, seque bem.','Sale generosamente por dentro e por fora, meta uns raminhos de endro e rodelas de limão na cavidade.','Aqueça uma grelha ou brasas de lenha até calor vivo mas estável.','Grelhe o peixe inteiro 6 a 7 minutos de cada lado conforme a espessura, até a carne se soltar facilmente.','Regue com manteiga derretida e um fio de limão mesmo antes de servir.']::text[]),
('bannock','pt','Bannock','Yellowknife, Territórios do Noroeste, Canadá','Um pão chato sem fermento tradicional dos povos indígenas do norte do Canadá, cozinhado em frigideira ou sobre pedra quente, por vezes até enrolado num pau e cozinhado sobre a fogueira, base indispensável da cozinha do mato.',ARRAY['Misture farinha, fermento e sal numa tigela grande.','Junte água gradualmente misturando até formar uma massa macia mas não pegajosa.','Amasse brevemente, deixe repousar 10 minutos sob um pano.','Achate a massa num ou vários discos grossos de cerca de 2 cm.','Coza em frigideira untada em lume médio, 8 minutos de cada lado até dourado e cozido por dentro.']::text[]),
('montreal-smoked-meat','pt','Carne fumada de Montreal','Montreal, Quebec, Canadá','Um peito de vaca curado em especiarias e depois fumado e cozido a vapor, menos doce que o seu primo pastrami nova-iorquino, cortado à mão diante do cliente e empilhado alto entre duas fatias de pão de centeio com mostarda.',ARRAY['Esfregue o peito de vaca com uma mistura de sal grosso, alho esmagado e especiarias, cure no frio 10 dias, virando com regularidade.','Enxague bem, cubra com uma crosta generosa de pimenta e coentros triturados.','Fume a frio e depois a quente várias horas até formar uma crosta negra.','Cozinhe a vapor 4 horas até extremamente macio.','Corte à mão diante dos convidados, empilhe generosamente entre duas fatias de pão de centeio barradas com mostarda.']::text[]),
('beavertails','pt','BeaverTails','Ottawa, Ontário, Canadá','Uma massa levedada esticada à mão numa forma oval plana que lembra uma cauda de castor, frita até dourada e estaladiça, coberta com açúcar e canela, vendida quente aos patinadores no canal Rideau gelado todos os invernos.',ARRAY['Amasse farinha, fermento, leite morno, ovo, açúcar e uma pitada de sal numa massa macia, deixe levedar 1 hora.','Divida a massa em bolas, estique cada uma à mão numa forma oval plana e alongada.','Frite em óleo quente a 180 °C 1 minuto de cada lado até dourada e estaladiça.','Escorra rápido em papel absorvente.','Pincele com manteiga derretida e polvilhe generosamente com açúcar e canela, sirva de imediato a escaldar.']::text[]),
('tire-erable','pt','Puxa-puxa de ácer na neve','Saint-Hyacinthe, Quebec, Canadá','Xarope de ácer puro aquecido até engrossar num xarope concentrado, deitado em longos fios diretamente sobre neve fresca onde solidifica instantaneamente, enrolado num pauzinho de madeira e comido ainda morno-frio mesmo na cabana de açúcar.',ARRAY['Deite o xarope de ácer puro numa panela grande de fundo grosso.','Aqueça em lume médio até atingir 112 °C no termómetro de açúcar, sem nunca mexer.','Prepare um tabuleiro grande de neve limpa recém-caída, ou gelo picado em alternativa.','Deite de imediato longos fios de xarope quente sobre a neve compactada.','Enrole rapidamente cada fio solidificado num pauzinho de madeira antes de endurecer demais, saboreie de imediato.']::text[])
